// The beam (banded across, pulses running down it, sine strands that brighten in front, a source flare with
// spinning rays, an end flare spraying rays and sparks) is adapted from Sprite Fusion's open-source energy beam
// (https://www.spritefusion.com/pixel-art-vfx/energy), MIT License, Copyright (c) 2026 Hugo Duprez.
import { PAL, fit, cycle, fly, flyV, loopNoise, fract, ease, sparkle, TAU, WHITE, READY } from "../../core/index.js";
import { bayer, mote } from "./_lib.js";

const D = 1.2, HX = 15, HY = -24, L = 168, W = 6;

export const meta = {
  name: "Arcane beam",
  desc: "A beam fires right from the hand: a white core, strands twisting round it, pulses running down it, a flaring source and an end that sprays sparks.",
  tags: ["arcane", "beam", "laser", "ray", "magic", "directional", "loop"],
  size: [264, 100],
  origin: [26, 84],
  duration: D,
  loop: true,
  fps: 30,
  bg: "ground",
  actor: 2,
  options: { palette: PAL.arcane, seed: 10 },
};

const AIM = { ...READY, x: -3, crouch: 4, lean: 4, fx: 18, fy: -24, bx: 13, by: -20, ffx: 11, fbx: -9, toeB: true };
const PULL = { ...READY, x: -3, crouch: 4, lean: -3, fx: 1, fy: -20, bx: 4, by: -22, ffx: 9, fbx: -7 };
export const act = {
  target: { x: 186 },
  poses: [
    [-0.62, { ...READY, x: -3 }],
    [-0.3, PULL],
    [-0.04, { ...PULL, crouch: 5, lean: -4 }],
    [0, { ...AIM, crouch: 3 }, "snap"],
    [0.3, AIM],
    [0.6, { ...AIM, crouch: 5, lean: 3 }],
    [0.9, AIM],
    [1.2, { ...AIM, crouch: 3 }],
  ],
  hits: [{ t: 0.1, push: 0.5, straw: 3, flash: 0.02, y: -24 }, { t: 0.7, push: 0.5, straw: 3, flash: 0.02, y: -24 }],
  dust: [{ t: 0, x: -10, n: 5, dir: -1 }],
};

export function draw(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, S = o.seed, EX = HX + L;
  // the body, built across from a white core out to a dithered violet edge, wobbling and pulsing as it goes
  const LV = [WHITE, C[6], C[5], C[4], C[3], C[2]];
  for (let d = 0; d <= L; d += 0.5) {
    const x = HX + d, w = W * (1 + 0.12 * Math.sin(d * 0.35 - ph * TAU * 8)) * Math.min(1, (d + 3) / 7);
    const pulse = fract(d * 0.025 - ph * 4) < 0.07 ? 1 : 0;
    for (let q0 = -w * 1.3; q0 <= w * 1.3; q0 += 0.5) {
      const q = Math.abs(q0) / w, y = HY + q0;
      let lv = q < 0.2 ? 0 : q < 0.4 ? 1 : q < 0.62 ? 2 : q < 0.85 ? 3 : q < 1 ? 4 : 5;
      lv = Math.max(0, lv - pulse);
      if (lv === 5 && bayer(x, y) > (1.3 - q) / 0.3) continue;
      p.px(x, y, LV[lv]);
    }
    // three strands twisting round it: bright on the near side, gone behind
    for (let s = 0; s < 3; s++) {
      const a = d * 0.17 - ph * TAU * 6 + (s * TAU) / 3, off = Math.sin(a) * w * 1.05;
      if (Math.cos(a) > -0.15) p.dot(x, HY + off, Math.cos(a) > 0.55 ? WHITE : C[6]);
    }
    if ((Math.round(d * 2) & 11) === 0) p.glow(x, HY, w * 2.2 + 4, C[5], 0.2);
  }

  // the source: a flickering flare with spinning rays at the hand
  const fr = 4.2 + Math.sin(ph * TAU * 10) * 0.6;
  for (let i = 0; i < 4; i++) {
    const a = ph * TAU * 2.5 + (i * TAU) / 4, l = 7 + 3 * Math.sin(ph * TAU * 6 + i);
    p.line(HX, HY, HX + Math.cos(a) * l, HY + Math.sin(a) * l, (u) => (u < 0.5 ? WHITE : C[6]), (u) => (u < 0.6 ? 1 : 1.6 - u));
  }
  p.circle(HX, HY, fr + 1.5, C[4]);
  p.circle(HX, HY, fr, C[6]);
  p.circle(HX, HY, fr * 0.6, WHITE);
  p.glow(HX, HY, 32, C[5], 0.8);
  // energy drawn into the hand
  cycle(t, D, 10, S * 3 + 1, 0.18, (age, life, r) => {
    const a = r.range(0, TAU), dd = 16 * (1 - age / life) + 3, x = HX + Math.cos(a) * dd, y = HY + Math.sin(a) * dd;
    p.dot(x, y, age / life > 0.6 ? WHITE : C[6]);
  });

  // the end: a hot flare spraying rays, rings shocking out, sparks thrown back and falling
  const ir = 5 + Math.sin(ph * TAU * 12) * 0.8;
  for (let i = 0; i < 7; i++) {
    const a = Math.PI + (i - 3) * 0.36, l = 8 + 8 * Math.abs(loopNoise(ph, 4, S * 7 + i));
    p.line(EX, HY, EX + Math.cos(a) * l, HY + Math.sin(a) * l, (u) => (u < 0.4 ? WHITE : i % 2 ? C[5] : C[6]), (u) => (u < 0.6 ? 1 : 1.6 - u));
  }
  for (let k = 0; k < 3; k++) {
    const q = fract(ph * 3 + k / 3);
    p.ring(EX, HY, 3 + 15 * ease.outCubic(q), Math.max(1, 2 * (1 - q)), q < 0.25 ? WHITE : C[5], 1.1 - q);
  }
  p.circle(EX, HY, ir + 1.5, C[4]);
  p.circle(EX, HY, ir, C[6]);
  p.circle(EX, HY, ir * 0.55, WHITE);
  p.glow(EX, HY, 40, C[5], 0.9);
  p.glow(EX, HY, 12, WHITE, 0.6);
  // a fountain of sparks thrown up and back off the end, arcing down
  cycle(t, D, 220, S * 3 + 2, (g) => g.range(0.18, 0.5), (age, life, r) => {
    const a = Math.PI * 1.5 + r.range(-1.7, 0.45), sp = r.range(70, 260), vx = Math.cos(a) * sp, vy = Math.sin(a) * sp - 30;
    const [x, y] = fly(EX, HY, vx, vy, age, 480, 2.2), [ux, uy] = flyV(vx, vy, age, 480, 2.2), k = 1 - age / life;
    if (y > -1) return;
    const head = k > 0.6 ? WHITE : k > 0.3 ? C[6] : C[5], sp2 = Math.hypot(ux, uy) || 1, len = Math.min(8, 1 + sp2 * 0.022);
    p.line(x - (ux / sp2) * len, y - (uy / sp2) * len, x, y, (u) => (u > 0.5 ? head : C[4]));
    p.glow(x, y, 3, head, 0.45 * k);
  });
  cycle(t, D, 6, S * 3 + 3, 0.3, (age, life, r) => {
    const k = Math.sin((age / life) * Math.PI);
    sparkle(p, EX + r.range(-12, 4), HY + r.range(-12, 12), 1 + 2.5 * k, C[6], C[5], 0.4 * k);
  });
  // violet vapour lifting off the end
  cycle(t, D, 7, S * 3 + 5, (g) => g.range(0.8, 1.2), (age, life, r) => {
    const q = age / life, x = EX + r.range(-8, 4) - q * 6, y = HY - 4 - q * r.range(14, 24), rad = r.range(3, 5) * (0.7 + 0.8 * q);
    p.disc(x, y, rad, C[4], (dd) => 0.28 * Math.sin(q * Math.PI) * (1 - dd * dd));
  });
  // motes shed along the beam
  cycle(t, D, 16, S * 3 + 4, (g) => g.range(0.3, 0.6), (age, life, r) => {
    const q = age / life, x = HX + r.range(10, L - 10) + q * 20, y = HY + r.sign() * (W + 1 + q * r.range(4, 10));
    mote(p, x, y, 40, (y - HY) * 1.5, r.chance(0.5) ? C[6] : C[5], 0.6, 1 - q, 0.3);
  });
  // the floor beneath catches the light
  p.glow(EX, -1, 30, C[5], 0.25);
  p.glow(HX + L / 2, -1, 60, C[4], 0.12);
}

// The bolt and its pop (a layered head with spinning rays, a flash disc, a cross, a ring, plasma sparks and stars)
// are adapted from Sprite Fusion's open-source energy bolt (https://www.spritefusion.com/pixel-art-vfx/energy),
// MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, PAL, fit, sparkle, clamp, smooth, ease, TAU, WHITE, READY } from "../../core/index.js";

const HX = 15, HY = -24, TX = 152, TY = -22, N = 5, TRAIL = 18;

export const meta = {
  name: "Arcane missiles",
  desc: "A volley of violet bolts fans out of the hand, curls round on twisting ribbons and pops on the target one after another.",
  tags: ["arcane", "missile", "projectile", "homing", "volley", "magic", "directional", "one-shot"],
  size: [240, 116],
  origin: [26, 88],
  duration: 1.75,
  loop: false,
  fps: 30,
  bg: "ground",
  actor: 2,
  options: { palette: PAL.arcane, seed: 3 },
};

const OPEN = { ...READY, x: -3, crouch: 4, lean: 4, fx: 18, fy: -24, bx: -6, by: -22, ffx: 11, fbx: -9 };
const KICK = { ...OPEN, fx: 15, fy: -26, lean: 2 };
const GATHER = { ...READY, x: -3, crouch: 4, lean: -2, fx: 6, fy: -24, bx: 8, by: -24, ffx: 9, fbx: -7 };
export const act = {
  target: { x: 152 },
  poses: [
    [-0.52, { ...READY, x: -3 }],
    [-0.24, GATHER],
    [0, { ...GATHER, crouch: 5 }],
    [0.05, KICK, "snap"],
    [0.1, OPEN, "snap"],
    [0.15, KICK, "snap"],
    [0.2, OPEN, "snap"],
    [0.25, KICK, "snap"],
    [0.29, OPEN, "snap"],
    [0.33, KICK, "snap"],
    [0.38, OPEN, "snap"],
    [0.43, KICK, "snap"],
    [0.48, OPEN, "snap"],
    [1.2, { ...OPEN, crouch: 3 }],
    [1.7, { ...READY, x: -3 }],
  ],
  hits: [
    { t: 0.77, stop: 0.02, push: 0.7, straw: 4, y: -24, flash: 0.03 },
    { t: 0.85, stop: 0.02, push: 0.7, straw: 4, y: -24, flash: 0.03 },
    { t: 0.95, stop: 0.02, push: 0.7, straw: 4, y: -24, flash: 0.03 },
    { t: 1.08, stop: 0.02, push: 0.7, straw: 4, y: -24, flash: 0.03 },
    { t: 1.2, stop: 0.07, shake: 0.14, amp: 1, push: 1.4, straw: 9, y: -24 },
  ],
};

export function create(o) {
  const C = fit(o.palette, 8), R = new Rng(o.seed);
  const ps = new Particles({ rng: R, ground: () => 0, sparks: [WHITE, C[6], C[5], C[4]] }), lights = new Lights();
  // each bolt leaves the hand on its own heading, then homes in harder and faster until it lands
  const fan = [-1.05, 0.7, -0.5, 1.1, -1.4];
  const bolts = fan.map((a, i) => {
    a += R.range(-0.12, 0.12);
    const sp = R.range(130, 165);
    return { t0: 0.05 + i * 0.1, x: HX, y: HY, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, trail: [], hit: -1, on: false, tx: TX + R.range(-3, 3), ty: TY + R.range(-6, 6), tw: R.range(0, TAU), acc: 0 };
  });
  const pops = [];
  let t = 0;

  function ribbon(p, b) {
    const pts = b.trail, n = pts.length, fade = b.hit < 0 ? 1 : 1 - clamp((t - b.hit) / 0.16);
    if (n < 2 || fade <= 0) return;
    for (let i = 0; i < n - 1; i++) {
      const [x0, y0] = pts[i], [x1, y1] = pts[i + 1], L = Math.hypot(x1 - x0, y1 - y0) || 1, nx = -(y1 - y0) / L, ny = (x1 - x0) / L;
      for (let d = 0; d < L; d += 0.5) {
        const u = (i + d / L) / (n - 1), x = x0 + ((x1 - x0) * d) / L, y = y0 + ((y1 - y0) * d) / L, a = (1 - u) * 1.7 * fade;
        // the body: a capsule that tapers down the tail, white along its middle near the head, cooling outward
        const w = 2.6 * Math.pow(1 - u, 0.8) + 0.3;
        for (let q = -w; q <= w; q += 0.5) {
          const v = Math.abs(q) / w;
          p.dot(x + nx * q, y + ny * q, v < 0.35 ? (u < 0.25 ? WHITE : C[6]) : v < 0.7 ? (u < 0.4 ? C[6] : C[5]) : u < 0.5 ? C[5] : C[4], a * (v < 0.7 ? 1 : 0.75));
        }
        // two strands twisting round it: bright where they come round the front, dim behind
        for (const s of [0, Math.PI]) {
          const ph = u * 10 - t * 26 + b.tw + s, off = Math.sin(ph) * (w + 1.4);
          if (Math.cos(ph) > -0.2) p.dot(x + nx * off, y + ny * off, Math.cos(ph) > 0.4 ? (u < 0.35 ? WHITE : C[6]) : C[4], a);
        }
      }
      if (i % 3 === 0) p.glow(x0, y0, 9 * (1 - i / n) + 3, C[5], 0.3 * (1 - i / n) * fade);
    }
  }

  function head(p, b) {
    const x = b.x, y = b.y;
    for (let i = 0; i < 4; i++) {
      const a = t * 24 + (i * TAU) / 4 + b.tw, l = 5.5 + 1.5 * Math.sin(t * 50 + i);
      p.line(x + Math.cos(a) * 3.2, y + Math.sin(a) * 3.2, x + Math.cos(a) * l, y + Math.sin(a) * l, C[6]);
    }
    p.circle(x, y, 3.8, C[4]);
    p.circle(x, y, 3, C[5]);
    p.circle(x, y, 2.1, C[6]);
    p.circle(x, y, 1.2, WHITE);
    p.glow(x, y, 24, C[5], 0.6);
    p.glow(x, y, 7, WHITE, 0.4);
  }

  function pop(p, q, x, y) {
    if (q < 0.16) {
      const r = 9 * (1 - q / 0.16) + 1.5;
      p.circle(x, y, r + 1.5, C[5]);
      p.circle(x, y, r, WHITE);
    }
    if (q < 0.4) {
      const l = 15 * (1 - q / 0.4) + 3;
      for (let d = -l; d <= l; d++) {
        const a = Math.abs(d) / l, c = a < 0.3 ? WHITE : a < 0.65 ? C[6] : C[5];
        p.dot(x + d, y, c, 1.15 - a);
        p.dot(x, y + d * 0.7, c, 1.15 - a);
      }
    }
    const rr = 3 + 18 * ease.outCubic(q);
    p.ring(x, y, rr + 0.5, Math.max(1, 3 * (1 - q)), q < 0.3 ? WHITE : C[6], 1.2 - q);
  }

  // the lock: four brackets close on the target and pulse as each bolt lands
  function lock(p) {
    const k = smooth(0, 0.22, t) * (1 - smooth(1.15, 1.45, t));
    if (k <= 0) return;
    let kick = 0;
    for (const q of pops) kick = Math.max(kick, Math.exp(-(((t - q.t) / 0.06) ** 2)));
    const r = 9 + 10 * (1 - ease.outCubic(smooth(0, 0.22, t))) + 3 * kick, spin = t * 1.5;
    for (let i = 0; i < 4; i++) {
      const a0 = spin + (i * TAU) / 4 - 0.38;
      for (let a = a0; a <= a0 + 0.76; a += 0.06) p.dot(TX + Math.cos(a) * r, TY + Math.sin(a) * r, kick > 0.4 ? WHITE : C[5], k);
    }
    p.glow(TX, TY, 12, C[4], 0.2 * k);
  }

  return {
    update(dt) {
      t += dt;
      for (const b of bolts) {
        if (t < b.t0 || b.hit >= 0) continue;
        if (!b.on) {
          b.on = true;
          lights.add(HX, HY, 28, C[5], 0.7, 0.14);
          for (let i = 0; i < 4; i++) ps.spawn(P.MOTE, HX, HY, Math.cos(Math.atan2(b.vy, b.vx) + R.range(-0.6, 0.6)) * R.range(60, 140), Math.sin(Math.atan2(b.vy, b.vx) + R.range(-0.6, 0.6)) * R.range(60, 140), R.range(0.12, 0.25), C[6], 0.6);
        }
        const age = t - b.t0, dx = b.tx - b.x, dy = b.ty - b.y, d = Math.hypot(dx, dy) || 1;
        const sp = 150 + 560 * age * age, steer = Math.min(1, (1.4 + 15 * age) * dt);
        b.vx += ((dx / d) * sp - b.vx) * steer;
        b.vy += ((dy / d) * sp - b.vy) * steer;
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        b.trail.unshift([b.x, b.y]);
        if (b.trail.length > TRAIL) b.trail.pop();
        if ((b.acc += dt) > 0.012) {
          b.acc = 0;
          if (R.chance(0.6)) ps.spawn(P.MOTE, b.x, b.y, -b.vx * 0.08 + R.range(-25, 25), -b.vy * 0.08 + R.range(-25, 25), R.range(0.2, 0.4), R.chance(0.5) ? C[6] : C[5], 0.55);
        }
        if (d < 3 || age > 1.3) {
          b.hit = t;
          pops.push({ t, x: b.x, y: b.y });
          lights.add(b.x, b.y, 70, C[5], 0.9, 0.3);
          lights.add(b.x, b.y, 24, WHITE, 0.85, 0.09);
          for (let i = 0; i < 16; i++) {
            const a = R.range(0, TAU), v = R.range(80, 230);
            ps.spawn(P.SPARK, b.x, b.y, Math.cos(a) * v, Math.sin(a) * v - 40, R.range(0.15, 0.45));
          }
          for (let i = 0; i < 7; i++) {
            const a = R.range(-Math.PI, 0.3), v = R.range(40, 140);
            ps.spawn(i % 2 ? P.STAR : P.MOTE, b.x, b.y, Math.cos(a) * v, Math.sin(a) * v, R.range(0.25, 0.48), R.pick([WHITE, C[6], C[5]]), R.range(0.8, 1.6));
          }
        }
      }
      ps.update(dt);
      lights.update(dt);
    },
    drawBack(p) {
      // the floor catches the light of each pop
      for (const q of pops) {
        const k = 1 - clamp((t - q.t) / 0.5);
        if (k > 0) p.glow(q.x, -1, 22, C[5], 0.25 * k * k);
      }
    },
    draw(p) {
      lock(p);
      for (const b of bolts) if (b.on) ribbon(p, b);
      for (const b of bolts) if (b.on && b.hit < 0) head(p, b);
      for (const q of pops) {
        const k = (t - q.t) / 0.35;
        if (k < 1) pop(p, k, q.x, q.y);
      }
      if (t < 0.55) sparkle(p, HX, HY, 3 + 2 * Math.sin(t * 40), C[6], C[5], 0.45 * (1 - t / 0.55));
      ps.draw(p);
      lights.draw(p);
    },
  };
}

// The orb (a glassy bubble that thickens towards its rim, a hot core, a double rim, a highlight arc and spot,
// motes orbiting in front and behind) is adapted from Sprite Fusion's open-source energy orb
// (https://www.spritefusion.com/pixel-art-vfx/energy), MIT License, Copyright (c) 2026 Hugo Duprez.
import { PAL, fit, cycle, sparkle, TAU, WHITE } from "../../core/index.js";
import { mote } from "./_lib.js";

const D = 2.4, RAD = 17, Y0 = -52;

export const meta = {
  name: "Arcane orb",
  desc: "A floating orb of smoky violet glass with a swirl turning round a white-hot heart, two tilted rings of light orbiting behind and in front.",
  tags: ["arcane", "orb", "sphere", "magic", "floating", "loop"],
  size: [136, 112],
  origin: [68, 104],
  duration: D,
  loop: true,
  fps: 30,
  bg: "ground",
  options: { palette: PAL.arcane, seed: 6 },
};

// two rings, each a circle tilted in depth (sy) and rolled in the picture (rot), beads running round it
const RINGS = [
  { r: 31, sy: 0.24, rot: 0.36, beads: 3, turn: 2, c: 0 },
  { r: 27, sy: 0.3, rot: -0.55, beads: 2, turn: -3, c: 1 },
];

function setup(t) {
  const ph = t / D;
  return { ph, cx: 0, cy: Y0 + Math.sin(ph * TAU) * 2 };
}

// one ring's points on the near (z > 0) or far side; beads brighter, with light
function ring(p, C, s, R, near) {
  const { ph, cx, cy } = s, rot = R.rot + 0.12 * Math.sin(ph * TAU + R.c), cr = Math.cos(rot), sr = Math.sin(rot), n = Math.ceil(R.r * TAU * 1.5);
  const pos = (g) => {
    const lx = Math.cos(g) * R.r, ly = Math.sin(g) * R.r * R.sy;
    return [cx + lx * cr - ly * sr, cy + lx * sr + ly * cr];
  };
  for (let j = 0; j < n; j++) {
    const g = (j / n) * TAU, z = Math.sin(g);
    if (z > 0 !== near) continue;
    const [x, y] = pos(g);
    p.dot(x, y, near ? C[5] : C[4], near ? 0.7 : 0.4);
  }
  for (let b = 0; b < R.beads; b++) {
    const g = ph * TAU * R.turn + (b * TAU) / R.beads;
    for (let k = 0; k < 7; k++) {
      // a bead and its trail along the ring
      const gg = g - Math.sign(R.turn) * k * 0.07, z = Math.sin(gg);
      if (z > 0 !== near) continue;
      const [x, y] = pos(gg);
      p.dot(x, y, k === 0 ? WHITE : k < 3 ? C[6] : C[5], k < 4 ? 1 : 1 - (k - 3) / 4);
      if (k === 0) p.glow(x, y, near ? 7 : 5, C[6], near ? 0.5 : 0.25);
    }
  }
}

// the orb itself: smoky glass, the swirl, the heart, the rim, the highlights
function orb(p, C, s) {
  const { ph, cx, cy } = s;
  // the glass: translucent, thicker towards the rim
  p.disc(cx, cy, RAD, (d) => (d > 0.82 ? C[2] : C[1]), (d) => 0.32 + 0.5 * d * d);
  // the swirl: two bright arms and two faint ones turning round the heart, twice a loop
  // the swirl: two bright arms with a lilac edge, and two faint ones between, turning twice a loop
  for (const [s0, main] of [[0, 1], [Math.PI, 1], [Math.PI / 2, 0], [(3 * Math.PI) / 2, 0]])
    for (let u = 0.08; u <= 0.85; u += 0.012) {
      const a = ph * TAU * 2 + s0 + u * 3.4, r = u * RAD * 0.92, x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r, fade = u < 0.6 ? 1 : 1 - (u - 0.6) / 0.25;
      if (!main) {
        p.dot(x, y, C[4], fade * 0.8);
        continue;
      }
