    const x = cx + x0 * Math.cos(tilt), y = cy + x0 * Math.sin(tilt) + z * rr * 0.28, dir = i % 2 ? 1 : -1;
    p.dot(x, y, near ? WHITE : C[5]);
    p.dot(x - dir, y, near ? C[6] : C[4], near ? 1 : 0.6);
    if (near) p.dot(x - 2 * dir, y, C[4], 0.6), p.glow(x, y, 5, C[6], 0.35);
