const N = 14, IN = 0.05, GO = 0.66, END = 0.8;

export function create(o) {
  const C = fit(o.palette, 7), R = new Rng(o.seed), INK = C[0];
  const ps = new Particles({ rng: R, sparks: [C[6], C[5], C[4], C[3]] });
  // the star's spikes: long and short in turn, each its own length, boiling a little every few frames
  const spikes = Array.from({ length: N * 2 }, (_, i) => ({ r: i % 2 ? R.range(0.5, 0.6) : R.range(0.85, 1.05), j: R.next() * 100 }));
  const lines = Array.from({ length: 16 }, (_, i) => ({ a: ((i + R.range(0.2, 0.8)) / 16) * TAU, r: R.range(0.92, 1.08), L: R.range(10, 17), t0: R.range(0, 0.06) }));
  let t = 0, popped = false, burst = false;
  return {
    update(dt) {
      t += dt;
      if (!burst && t >= IN) {
        burst = true;
        for (let i = 0; i < 22; i++) {
          const a = R.range(0, TAU), sp = R.range(180, 360);
          ps.spawn(P.SPARK, Math.cos(a) * 14, Math.sin(a) * 10, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.12, 0.3));
        }
      }
      // it snaps away into a scatter of little stars
      if (!popped && t >= GO) {
        popped = true;
        for (let i = 0; i < 14; i++) {
          const a = R.range(0, TAU), sp = R.range(60, 150);
          ps.spawn(P.STAR, Math.cos(a) * 26, Math.sin(a) * 18, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.25, 0.42), R.pick([C[6], C[5], C[4]]), R.range(1.2, 2.4));
        }
      }
      ps.update(dt);
      cull(ps, -meta.origin[0] + 3, -meta.origin[1] + 3, meta.size[0] - meta.origin[0] - 3, meta.size[1] - meta.origin[1] - 3);
    },
    draw(p) {
      const k = clamp(t / IN);
      // the slam: it punches in past full size, shudders and settles; then it squeezes and snaps away
      const s = t < IN ? 0.25 + 0.95 * ease.outCubic(k) : t < GO ? 1 + 0.18 * Math.exp(-(t - IN) * 18) * Math.cos((t - IN) * 40) : 1 - ease.inBack(clamp((t - GO) / (END - GO)), 2);
      const shake = t < 0.3 ? (1 - t / 0.3) * 2.2 : 0, sx = Math.round(Math.sin(t * 97) * shake), sy = Math.round(Math.cos(t * 83) * shake);
      if (s > 0.02) {
        // the burst star, in one pass: its edge at each angle runs straight from spike tip to notch. An inked edge, a
        // yellow body with halftone dots on its shaded side, an inked orange heart and a yellow core
        const boil = Math.floor(t * 12), outer = 50 * s, rot = -0.1 + (t > GO ? (t - GO) * 3 : 0), M = N * 2;
        const rad = spikes.map((q, i) => q.r * (1 + (rand(i, boil, 7) - 0.5) * 0.08));
        p.shade(sx - outer - 4, sy - outer - 4, sx + outer + 4, sy + outer + 4, (x, y) => {
          const dx = x - sx, dy = (y - sy) / 0.82, d = Math.hypot(dx, dy);
          let u = (((Math.atan2(dy, dx) - rot) / TAU) % 1 + 1) % 1 * M;
          const i = Math.floor(u) % M, f = u - Math.floor(u), r = rad[i] + (rad[(i + 1) % M] - rad[i]) * f, e = d / r;
          if (e > outer + 2.5) return;
          if (e > outer) return INK;
          if (e > outer * 0.66 + 2) return dx * 0.6 + dy * 0.8 > outer * 0.25 && (Math.floor(x) + Math.floor(y) * 2) % 4 === 0 && Math.floor(y) % 2 === 0 ? C[4] : C[5];
          if (e > outer * 0.66) return INK;
          return e > outer * 0.44 ? C[3] : C[4];
        });
        p.glow(sx, sy, outer * 1.3, C[5], 0.3 * Math.min(1, s));
      }
      // action lines flying out, and a ring of impact
      for (const q of lines) {
        const u = (t - IN - q.t0) / 0.32;
        if (u <= 0 || u >= 1) continue;
        const r0 = (46 + 22 * ease.outCubic(u)) * q.r, L = q.L * 0.7 * (1 - u), ca = Math.cos(q.a), sa = Math.sin(q.a) * 0.82;
        p.line(ca * r0, sa * r0, ca * (r0 + L), sa * (r0 + L), (v) => (v < 0.5 ? WHITE : C[5]));
      }
      const ru = (t - IN) / 0.24;
      if (ru > 0 && ru < 1) p.ring(0, 0, 30 + 34 * ease.outCubic(ru), Math.max(1, 2.5 * (1 - ru)), ru < 0.4 ? WHITE : C[5], 1.1 - ru);
      // the word: letters dropping in one after another, inked, with a deep red extrusion, then a squash as it goes
      const word = String(o.text ?? "POW!"), scale = 3, widths = [...word].map((ch) => p.measure(ch, { font: "big", scale })[0]);
      let x = -(widths.reduce((a, w) => a + w + scale, -scale)) / 2;
      [...word].forEach((ch, i) => {
        const u = (t - IN - 0.04 - i * 0.05) / 0.12, away = clamp((t - GO) / (END - GO - 0.04));
        if (u > 0 && away < 1) {
          const drop = (1 - ease.outBack(clamp(u), 2.4)) * -14, y = Math.round(-11 + drop - i * 1.5 + sy + away * 6);
          const lx = Math.round(x + sx), a = 1 - away;
          // a thick ink edge, a deep red extrusion, a white face going warm toward its foot
          for (let d = 4; d >= 1; d--) p.text(ch, lx + d, y + d, d >= 3 ? INK : C[1], { font: "big", scale, a, outline: d === 4 ? INK : undefined });
          for (const [ox, oy] of [[-2, 0], [2, 0], [0, -2], [0, 2], [-1, -1], [1, -1], [-1, 1], [1, 1]]) p.text(ch, lx + ox, y + oy, INK, { font: "big", scale, a });
          p.text(ch, lx, y, (gx, gy) => (gy < 4 ? C[6] : gy < 6 ? C[5] : C[4]), { font: "big", scale, a });
        }
        x += widths[i] + scale;
      });
      ps.draw(p);
      if (t > IN && t < IN + 0.12) sparkle(p, sx + 34, sy - 22, 6 * (1 - (t - IN) / 0.12), C[6], C[5], 0.6);
    },
  };
}

// The earth recipe (grit thrown in a fan, rocks that bounce and kick up dust, a dust column and dust rolling out along
// the floor) is adapted from Sprite Fusion's open-source explosion (https://www.spritefusion.com/pixel-art-vfx/explosion),
// MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Bits, Lights, P, PF, B, Rng, fit, band, smooth, ease, TAU, WHITE, hex, mix, rgb } from "../../core/index.js";
import { drawDirt, crater, rock, dome, pool, cull, fadeEdges } from "./_lib.js";

export const meta = {
  name: "Dirt explosion",
  desc: "A buried charge goes off: a flash under the floor, a V of dirt clods and grit thrown high, a brown dust plume that billows and settles, and a crater left behind.",
  tags: ["explosion", "dirt", "earth", "dust", "debris", "ground", "one-shot"],
  size: [260, 240],
  origin: [130, 206],
  duration: 3.6,
  loop: false,
  fps: 30,
  bg: "ground",
  options: {
    palette: ["#1c1610", "#33281c", "#4f3f2c", "#6e5a40", "#927a58", "#b89f78", "#dcc8a2"],
    fire: ["#4a1712", "#c9281f", "#f2561d", "#ff8a2a", "#ffc23d", "#ffe26b", "#fff3a6", "#ffffff"],
    seed: 3,
  },
};

export function create(o) {
  const E = fit(o.palette, 7), F = fit(o.fire, 8), R = new Rng(o.seed), floor = () => 0;
  const [W, H] = meta.size, [OX, OY] = meta.origin, X0 = -OX + 3, X1 = W - OX - 3, Y0 = -OY + 3, Y1 = H - OY - 3;
  const clod = { light: E[5], body: E[3], shade: E[2] }, DUST = mix(E[4], rgb(150, 140, 150), 0.2), SOIL = mix(E[3], rgb(90, 80, 90), 0.2), DARK = mix(E[2], rgb(60, 52, 60), 0.3);
  const ps = new Particles({ rng: R, ground: floor, sparks: [F[6], F[5], F[3], F[2]] }), lights = new Lights();
  const clods = new Bits({ ground: floor });
  let t = 0;

  lights.add(0, -10, 56, F[4], 0.7, 0.22);
  lights.add(0, -4, 26, WHITE, 0.6, 0.06);
  // the charge: a few sparks out of the hole
  for (let i = 0; i < 14; i++) {
    const a = -Math.PI / 2 + R.range(-0.7, 0.7), sp = R.range(160, 320);
    ps.spawn(P.SPARK, 0, -2, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.15, 0.35));
  }
  // the fountain: grit in a V, clods thrown high, a few pebbles
  for (let i = 0; i < 300; i++) {
    const side = R.sign(), a = -Math.PI / 2 + side * R.range(0.05, 0.62), sp = R.range(150, 470) * (1 - 0.3 * Math.abs(a + Math.PI / 2));
    ps.spawn(P.GRIT, R.range(-4, 4), -1, Math.cos(a) * sp, Math.sin(a) * sp, R.range(1.2, 2.2), R.pick([E[1], E[2], E[2], E[3], E[3], E[4], E[5]]), R.chance(0.45) ? 2 : 1, R.range(0, 0.06));
  }
  for (let i = 0; i < 30; i++) {
    const side = R.sign(), a = -Math.PI / 2 + side * R.range(0.1, 0.6), sp = R.range(200, 430);
    clods.add({ kind: B.CHUNK, x: R.range(-5, 5), y: -2, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, g: 1, drag: 0.35, bounce: 0.25, life: R.range(2.2, 3), a: R.range(0, TAU), va: R.range(-12, 12), s: i < 12 ? R.range(2.6, 3.8) : R.range(1.4, 2.4) });
  }
  // the dust: a plume punched straight up, two lobes riding the V, and a skirt rolling out along the floor
  for (let i = 0; i < 22; i++)
    ps.spawn(P.SMOKE, R.range(-7, 7), -R.range(2, 12), R.range(-25, 25), -R.range(70, 180), R.range(1.8, 2.6), R.chance(0.6) ? SOIL : DUST, R.range(9, 14), R.range(0, 0.14), PF.BIG);
  for (let i = 0; i < 14; i++) {
    const side = R.sign(), a = -Math.PI / 2 + side * R.range(0.35, 0.6), sp = R.range(110, 210);
    ps.spawn(P.SMOKE, side * R.range(2, 8), -R.range(2, 8), Math.cos(a) * sp, Math.sin(a) * sp, R.range(1.6, 2.4), R.chance(0.5) ? SOIL : DUST, R.range(8, 12), R.range(0.02, 0.1), PF.BIG);
  }
  for (let i = 0; i < 16; i++) {
    const s = R.sign();
    ps.spawn(P.SMOKE, s * R.range(4, 16), -R.range(1, 5), s * R.range(70, 200), -R.range(2, 12), R.range(1.4, 2.2), DUST, R.range(6, 9), R.range(0.02, 0.1), PF.BIG);
  }
  // dark soil thrown up with it, heavier and lower
  for (let i = 0; i < 8; i++) ps.spawn(P.SMOKE, R.range(-8, 8), -R.range(2, 8), R.range(-40, 40), -R.range(40, 110), R.range(1.2, 1.8), DARK, R.range(6, 9), R.range(0, 0.05));

  return {
    update(dt) {
      t += dt;
      for (const b of clods.list) b.pvy = b.vy;
      clods.update(dt);
      // clods thud down: a puff of dust and a spray of crumbs where they land, the big ones break up
      for (let i = clods.list.length - 1; i >= 0; i--) {
        const b = clods.list[i];
        if (b.x < X0 + 4 || b.x > X1 - 4) {
          clods.list.splice(i, 1);
          continue;
        }
        const landed = (b.pvy > 0 && b.vy <= 0) || (b.rest && !b.thud);
        if (!landed || b.pvy < 80) {
          if (b.rest) b.thud = true;
          continue;
        }
        b.thud = b.rest;
        for (let j = 0; j < 2 + Math.round(b.s); j++) ps.spawn(P.DUST, b.x + R.range(-2, 2), -0.5, R.sign() * R.range(15, 55), -R.range(4, 22), R.range(0.35, 0.7), DUST, R.range(1.6, 1.2 + b.s));
        for (let j = 0; j < Math.round(b.s * 3); j++) ps.spawn(P.GRIT, b.x, -1, R.range(-70, 70), -R.range(40, 140), R.range(0.8, 1.4), R.pick([E[2], E[3], E[4]]), 1);
        if (b.s > 2.2 && b.pvy > 200) b.s *= 0.6;
      }
      ps.update(dt);
      cull(ps, X0, Y0, X1, Y1);
      fadeEdges(ps, X0, X1, 24, Y1);
      lights.update(dt);
    },
    drawBack(p) {
      crater(p, E, 0, 28, ease.outCubic(Math.min(1, t / 0.12)), 1 - smooth(meta.duration - 0.7, meta.duration - 0.1, t));
      const k = t / 0.45;
      if (k < 1) band(p, 0, 0.5, 90 * ease.outCubic(k), 0.16, Math.max(1, 3 * (1 - k)), 1.1 - k, [E[2], E[4], E[5], E[6]], (g) => Math.sin(g) < 0);
      drawDirt(p, ps, "back");
    },
    draw(p) {
      const k = t / 0.45;
      if (k < 1) band(p, 0, 0.5, 90 * ease.outCubic(k), 0.16, Math.max(1, 3 * (1 - k)), 1.1 - k, [E[2], E[4], E[5], E[6]], (g) => Math.sin(g) >= 0);
      // the flash out of the ground: a squat dome of white-hot air for a frame or two
      if (t < 0.09) dome(p, F, 0, 15 * (1 - t * 3), 1 - t / 0.09);
      for (const b of clods.list) rock(p, b, clod, F);
      drawDirt(p, ps, "front");
      pool(p, 0, 1, 60, 10, F[3], 0.5 * Math.max(0, 1 - t / 0.3));
      lights.draw(p);
    },
  };
}

// The flare, the twinkling crosses and the glitter are adapted from Sprite Fusion's open-source sparkle
// (https://www.spritefusion.com/pixel-art-vfx/sparkle), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, sparkle, ease, TAU, WHITE, hex, mix } from "../../core/index.js";

export const meta = {
  name: "Firework burst",
  desc: "A shell climbs, slows and bursts into a sphere of coloured trailing stars round a gold core; they droop, crackle into white pops and fade, leaving glitter.",
  tags: ["firework", "celebration", "sparkle", "sky", "burst", "one-shot"],
  size: [240, 248],
  origin: [120, 100],
  duration: 3.6,
  loop: false,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#3d0a33", "#701560", "#b0228f", "#f53cd1", "#ff86e6", "#ffd2f6", "#ffffff"],
    core: ["#4a2c08", "#86520c", "#c48412", "#f0b424", "#ffe066", "#fff6c4", "#ffffff"],
    seed: 9,
  },
};

const RISE = 0.42, Y0 = 72, DRAG = 2.6, G = 88, TRAIL = 0.34, TURN = 0.22;

export function create(o) {
  const C = fit(o.palette, 7), K = fit(o.core, 7), R = new Rng(o.seed);
  const ps = new Particles({ rng: R, sparks: [K[6], K[5], K[4], K[3]] }), lights = new Lights();
  const stars = [], pops = [];
  let t = 0, burst = false;

  // a shell of stars thrown over a sphere: seen side-on, the ones flying at us or away look slower
  // the outer stars burn gold for a beat, then turn to their color
  const shell = (n, speed, ramp, life, first) => {
    for (let i = 0; i < n; i++) {
      const z = R.range(-1, 1), a = R.range(0, TAU), s = Math.sqrt(1 - z * z), v = speed * R.range(0.93, 1.05);
      stars.push({ x: 0, y: 0, vx: Math.cos(a) * s * v, vy: Math.sin(a) * s * v, life: R.range(life[0], life[1]), age: 0, ramp, first, big: R.chance(0.2), pts: [], acc: R.next(), seed: R.range(0, 100) });
    }
  };

  return {
    update(dt) {
      t += dt;
      // the shell climbs, slowing, shedding a fizz of gold sparks
      if (t < RISE) {
        const y = Y0 * (1 - ease.outCubic(t / RISE));
        if (R.chance(50 * dt)) ps.spawn(P.SPARK, R.range(-0.5, 0.5), y + 2, R.range(-25, 25), R.range(20, 70), R.range(0.15, 0.35));
        if (R.chance(14 * dt)) ps.spawn(P.VAPOUR, R.range(-1, 1), y + 3, R.range(-3, 3), R.range(5, 15), R.range(0.5, 0.8), hex("#4a4458"), R.range(1.5, 2.5));
      }
      if (!burst && t >= RISE) {
        burst = true;
        lights.add(0, 0, 110, C[4], 0.6, 1.5);
        lights.add(0, 0, 30, WHITE, 0.5, 0.07);
        shell(66, 236, C, [1.35, 1.9], K);
        shell(26, 120, K, [1.0, 1.4], K);
        // the burst charge's smoke, drifting where the shell broke
        for (let i = 0; i < 7; i++) {
          const a = R.range(0, TAU), d = R.range(0, 8);
          ps.spawn(P.VAPOUR, Math.cos(a) * d, Math.sin(a) * d, Math.cos(a) * R.range(10, 30), Math.sin(a) * R.range(10, 30), R.range(2.2, 3), hex("#4a4458"), R.range(6, 11));
        }
        for (let i = 0; i < 24; i++) {
          const a = R.range(0, TAU), sp = R.range(40, 140);
          ps.spawn(P.SPARK, 0, 0, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.15, 0.35));
        }
      }
      for (let i = stars.length - 1; i >= 0; i--) {
        const s = stars[i];
        s.age += dt;
        const k = s.age / s.life;
        if (k >= 1) {
          // the star crackles out in a few white pops
          for (let j = 0; j < 2 + (s.big ? 1 : 0); j++) pops.push({ x: s.x + R.range(-3, 3), y: s.y + R.range(-3, 3), t0: t + R.range(0, 0.18), life: R.range(0.06, 0.12), c: R.chance(0.6) ? WHITE : s.ramp[5] });
          stars.splice(i, 1);
          continue;
        }
        s.vx -= s.vx * DRAG * dt;
        s.vy -= s.vy * DRAG * dt - G * dt;
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        s.pts.push(s.x, s.y, t);
        while (s.pts.length > 3 && t - s.pts[2] > TRAIL) s.pts.splice(0, 3);
        // glitter shed along the way: specks that hang, twinkle and fall
        for (s.acc += dt * (k < 0.25 ? 4 : 11); s.acc > 1; s.acc--) ps.spawn(P.STAR, s.x, s.y, s.vx * 0.15 + R.range(-6, 6), s.vy * 0.15 + R.range(0, 10), R.range(0.35, 0.8), R.chance(0.5) ? K[5] : WHITE, R.chance(0.15) ? R.range(1, 1.6) : 0.5);
      }
      for (let i = pops.length - 1; i >= 0; i--) if (t > pops[i].t0 + pops[i].life) pops.splice(i, 1);
      ps.update(dt);
      lights.update(dt);
    },
    drawBack(p) {
      ps.draw(p, "back");
    },
    draw(p) {
      if (t < RISE) {
        // the shell: a hot dot with a short tail
        const u = t / RISE, y = Y0 * (1 - ease.outCubic(u));
        p.line(0, y, 0, y + 3 + 6 * (1 - u), (q) => (q < 0.3 ? K[5] : K[3]));
        p.px(0, y, WHITE);
        p.glow(0, y, 7, K[4], 0.5);
      }
      for (const s of stars) {
        const k = s.age / s.life, P2 = s.pts, n = P2.length / 3;
        // the trail: a 1 px line from the head back along where it has been, cooling and dithering out; the part
        // laid while the star burned gold stays gold
        for (let j = n - 1; j > 0; j--) {
          const u = (t - P2[j * 3 + 2]) / TRAIL;
          if (u >= 1) break;
          const ramp = s.age - (t - P2[j * 3 + 2]) < TURN ? s.first : s.ramp;
          const c = u < 0.3 ? ramp[5] : u < 0.6 ? ramp[4] : ramp[3];
          p.line(P2[j * 3], P2[j * 3 + 1], P2[j * 3 - 3], P2[j * 3 - 2], c, Math.pow(1 - u, 0.8) * (1.3 - k * 0.6));
        }
        // the head: white-hot, then its color; late on it flickers before it crackles out
        if (k > 0.72 && Math.sin(t * 60 + s.seed) < -0.2) continue;
        // white only on the burst frame; the glow comes in as the stars spread, so the heart never blooms into a blob
        const ramp = s.age < TURN ? s.first : s.ramp, head = s.age < 0.04 ? WHITE : k < 0.55 ? ramp[s.age < TURN ? 5 : 6] : ramp[5];
        p.px(s.x, s.y, head);
        if (s.big && k < 0.6 && s.age > 0.06) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(s.x + dx, s.y + dy, ramp[5]);
        p.glow(s.x, s.y, s.big ? 7 : 5, ramp[4], (s.big ? 0.7 : 0.5) * (1 - k * 0.6) * Math.min(1, s.age / 0.2));
      }
      for (const q of pops) {
        const u = (t - q.t0) / q.life;
        if (u < 0 || u > 1) continue;
        sparkle(p, q.x, q.y, 2.6 * Math.sin(Math.PI * u), q.c, mix(q.c, C[3], 0.5), 0.5);
      }
      // the burst: a flare and a white heart, the sky lit up behind it
      const b = t - RISE;
      if (b >= 0 && b < 0.28) {
        const u = b / 0.28, L = 32 * Math.pow(1 - u, 1.3);
        flareRays(p, 0, 0, L, u * 0.6, C, K);
        if (b < 0.07) p.circle(0, 0, 2.6 - b * 20, WHITE);
      }
      ps.draw(p, "front");
      lights.draw(p);
    },
  };
}

// an 8-ray flare: long rays on the axes with a white core and tinted ends, short gold diagonals, turning slowly
function flareRays(p, x, y, L, ang, C, K) {
  if (L < 1) return;
  for (let i = 0; i < 8; i++) {
    const diag = i % 2 === 1, an = ang + (i * TAU) / 8, len = diag ? L * 0.42 : L, ca = Math.cos(an), sa = Math.sin(an);
    for (let d = 0; d <= len; d += 0.5) {
      const u = d / len;
      p.dot(x + ca * d, y + sa * d, diag ? (u < 0.5 ? K[5] : K[4]) : u < 0.3 ? WHITE : u < 0.65 ? C[5] : C[4], u < 0.7 ? 1 : 1 - (u - 0.7) / 0.35);
    }
  }
  p.glow(x, y, 4 + L * 1.2, C[4], 0.3);
  p.glow(x, y, 2 + L * 0.3, WHITE, 0.25);
}

// The flare, the twinkling glitter and the crackle are adapted from Sprite Fusion's open-source sparkle
// (https://www.spritefusion.com/pixel-art-vfx/sparkle), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, sparkle, clamp, ease, TAU, WHITE, hex, mix } from "../../core/index.js";
import { cull } from "./_lib.js";

export const meta = {
  name: "Firework rocket",
  desc: "A rocket fizzes off the ground on a sparkling gold trail, coasts, and bursts into a palm: heavy gold fronds arc out, droop on glittering trails and crackle at the tips.",
  tags: ["firework", "rocket", "celebration", "sparkle", "sky", "one-shot"],
  size: [300, 300],
  origin: [150, 288],
  duration: 3.8,
  loop: false,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#2a1406", "#6a3a0c", "#b8701a", "#f0a830", "#ffd860", "#fff2b0", "#ffffff"],
    tips: ["#0c2a3a", "#1a5a78", "#36a2c8", "#7cd8f0", "#c8f4ff", "#ffffff"],
    seed: 12,
  },
};

const FLY = 1.05, HIGH = 192, DRAG = 1.35, G = 105, TRAIL = 1.15;

export function create(o) {
  const C = fit(o.palette, 7), T = fit(o.tips, 6), R = new Rng(o.seed);
  const ps = new Particles({ rng: R, sparks: [C[6], C[5], C[4], C[3]] }), lights = new Lights();
  const fronds = [], pops = [];
  const at = (t) => [Math.sin(t * 8) * 1.6 * (t / FLY), -8 - HIGH * ease.outQuad(clamp(t / FLY))];
  let t = 0, burst = false, bx = 0, by = 0, acc = 0;
  lights.add(0, -14, 24, C[4], 0.7, 0.35);
  // ignition: a puff of smoke and a spray of sparks off the ground
  for (let i = 0; i < 18; i++) {
    const a = -Math.PI / 2 + R.range(-1.2, 1.2), sp = R.range(60, 180);
    ps.spawn(P.SPARK, 0, -2, Math.cos(a) * sp, Math.sin(a) * sp * 0.6, R.range(0.15, 0.4));
  }
  for (let i = 0; i < 5; i++) ps.spawn(P.VAPOUR, R.range(-3, 3), -2, R.range(-20, 20), -R.range(2, 10), R.range(0.6, 1), hex("#5a5468"), R.range(3, 5));
  return {
    update(dt) {
      t += dt;
      if (t < FLY) {
        // the climb: a hot tail spitting gold sparks, glitter left hanging, a thread of smoke
        const [x, y] = at(t), [x2, y2] = at(Math.max(0, t - 0.02)), vy = (y - y2) / 0.02, vx = (x - x2) / 0.02;
        for (acc += dt * 90; acc > 1; acc--) {
          const a = Math.PI / 2 + R.range(-0.45, 0.45), sp = R.range(30, 110);
          ps.spawn(P.SPARK, x, y + 4, Math.cos(a) * sp + vx * 0.2, Math.sin(a) * sp + vy * 0.15, R.range(0.15, 0.4));
          if (R.chance(0.25)) ps.spawn(P.STAR, x + R.range(-1.5, 1.5), y + R.range(2, 6), R.range(-6, 6), R.range(5, 20), R.range(0.4, 0.9), R.chance(0.5) ? C[5] : WHITE, R.chance(0.15) ? 1.2 : 0.5);
          if (R.chance(0.18)) ps.spawn(P.VAPOUR, x, y + 5, R.range(-4, 4), R.range(4, 12), R.range(0.6, 1.1), hex("#4a4458"), R.range(1.2, 2.2));
        }
      } else if (!burst) {
        burst = true;
        [bx, by] = at(FLY);
        lights.add(bx, by, 82, C[4], 0.8, 1.6);
        lights.add(bx, by, 40, WHITE, 0.6, 0.08);
        // the palm: heavy comets thrown up and out, a few low ones to the sides
        for (let i = 0; i < 9; i++) {
          const a = -Math.PI / 2 + ((i - 4) / 4) * 1.4 + R.range(-0.1, 0.1), sp = R.range(180, 210) * (1 - 0.12 * Math.abs(i - 4) / 4);
          fronds.push({ x: bx, y: by, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, age: 0, life: R.range(1.8, 2.15), pts: [], acc: R.next(), seed: R.range(0, 100) });
        }
        for (let i = 0; i < 6; i++) ps.spawn(P.VAPOUR, bx + R.range(-4, 4), by + R.range(-4, 4), R.range(-20, 20), R.range(-15, 15), R.range(1.8, 2.6), hex("#4a4458"), R.range(6, 10));
        for (let i = 0; i < 30; i++) {
          const a = R.range(0, TAU), sp = R.range(40, 160);
          ps.spawn(P.SPARK, bx, by, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.15, 0.35));
        }
      }
      for (let i = fronds.length - 1; i >= 0; i--) {
        const f = fronds[i];
        f.age += dt;
        const k = f.age / f.life;
        if (k >= 1) {
          for (let j = 0; j < 4; j++) pops.push({ x: f.x + R.range(-5, 5), y: f.y + R.range(-5, 5), t0: t + R.range(0, 0.2), life: R.range(0.06, 0.12), c: R.chance(0.5) ? WHITE : T[3] });
          fronds.splice(i, 1);
          continue;
        }
        f.vx -= f.vx * DRAG * dt;
        f.vy -= f.vy * DRAG * dt - G * dt;
        f.x += f.vx * dt;
        f.y += f.vy * dt;
        f.pts.push(f.x, f.y, t);
        while (f.pts.length > 3 && t - f.pts[2] > TRAIL) f.pts.splice(0, 3);
        // glitter shed all along: specks that hang, twinkle and drift down
        for (f.acc += dt * 34; f.acc > 1; f.acc--) ps.spawn(P.STAR, f.x + R.range(-1, 1), f.y + R.range(-1, 1), f.vx * 0.1 + R.range(-5, 5), R.range(0, 14), R.range(0.5, 1.1), R.chance(0.6) ? C[5] : WHITE, R.chance(0.12) ? R.range(1, 1.5) : 0.5);
      }
      for (let i = pops.length - 1; i >= 0; i--) if (t > pops[i].t0 + pops[i].life) pops.splice(i, 1);
      ps.update(dt);
      cull(ps, -meta.origin[0] + 2, -meta.origin[1] + 2, meta.size[0] - meta.origin[0] - 2, meta.size[1] - meta.origin[1] - 2);
      lights.update(dt);
    },
    drawBack(p) {
      ps.draw(p, "back");
    },
    draw(p) {
      if (t < FLY) {
        // the rocket: a little tube on a stick, a white-hot tail flickering under it
        const [x, y] = at(t);
        p.line(x, y + 4, x, y + 12, hex("#5a4030"));
        p.rect(x - 1, y - 3, 3, 7, hex("#b8303a"));
        p.px(x - 1, y - 3, hex("#e86070"));
        p.px(x, y - 4, hex("#d8d0c0"));
        const fl = 2 + (Math.sin(t * 70) > 0 ? 1 : 0);
        p.line(x, y + 4, x, y + 4 + fl, (u) => (u < 0.4 ? WHITE : C[5]));
        p.glow(x, y + 5, 9, C[4], 0.6);
      }
      for (const f of fronds) {
        const k = f.age / f.life, P2 = f.pts, n = P2.length / 3;
        // the frond: a thick gold trail, hot near the head, cooling and dithering out behind
        for (let j = n - 1; j > 0; j--) {
          const u = (t - P2[j * 3 + 2]) / TRAIL;
          if (u >= 1) break;
          const c = u < 0.08 ? C[6] : u < 0.25 ? C[5] : u < 0.5 ? C[4] : u < 0.75 ? C[3] : C[2], a = Math.pow(1 - u, 0.6) * (1.25 - k * 0.45);
          p.line(P2[j * 3], P2[j * 3 + 1], P2[j * 3 - 3], P2[j * 3 - 2], c, a);
          if (u < 0.7) p.line(P2[j * 3] + 1, P2[j * 3 + 1], P2[j * 3 - 3] + 1, P2[j * 3 - 2], u < 0.25 ? C[5] : u < 0.5 ? C[3] : C[2], a * 0.85);
          if (u < 0.35) p.line(P2[j * 3], P2[j * 3 + 1] + 1, P2[j * 3 - 3], P2[j * 3 - 2] + 1, C[3], a * 0.6);
        }
        if (k > 0.8 && Math.sin(t * 55 + f.seed) < 0) continue;
        p.rect(f.x - 0.5, f.y - 0.5, 2, 2, k < 0.5 ? WHITE : C[6]);
        if (k < 0.6) for (const [dx, dy] of [[-1, 0], [2, 0], [0, -1], [0, 2]]) p.px(f.x + dx, f.y + dy, C[5]);
        p.glow(f.x, f.y, 10, C[4], 0.6 * (1 - k * 0.5));
      }
      for (const q of pops) {
        const u = (t - q.t0) / q.life;
        if (u < 0 || u > 1) continue;
        sparkle(p, q.x, q.y, 2.8 * Math.sin(Math.PI * u), q.c, T[2], 0.5);
      }
      // the burst: a white heart for two frames, a flare turning
      const b = t - FLY;
      if (b >= 0 && b < 0.26) {
        const u = b / 0.26, L = 30 * Math.pow(1 - u, 1.3);
        for (let i = 0; i < 8; i++) {
          const diag = i % 2 === 1, an = u * 0.5 + (i * TAU) / 8, len = diag ? L * 0.45 : L, ca = Math.cos(an), sa = Math.sin(an);
          for (let d = 0; d <= len; d += 0.5) {
            const v = d / len;
            p.dot(bx + ca * d, by + sa * d, v < 0.3 ? WHITE : v < 0.65 ? C[5] : C[4], v < 0.7 ? 1 : 1 - (v - 0.7) / 0.35);
          }
        }
        if (b < 0.07) p.circle(bx, by, 2.5, WHITE);
        p.glow(bx, by, 4 + L * 1.2, C[4], 0.35);
      }
      ps.draw(p, "front");
      lights.draw(p);
    },
  };
}

// The blast (fire puffs that cool into smoke, sparks, grit, scorch, rings, lights) is adapted from Sprite Fusion's
// open-source explosion (https://www.spritefusion.com/pixel-art-vfx/explosion), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Bits, Lights, P, PF, B, Rng, fit, band, flare, clamp, smooth, ease, TAU, WHITE, hex, mix, scale, rgb } from "../../core/index.js";
import { fireRamp, heatRamp, drawPs, cull, fadeEdges, scorch, pool, OUTLINE } from "./_lib.js";

export const meta = {
  name: "Grenade",
  desc: "A grenade is lobbed in, bounces, rolls to a stop with its fuse fizzing, shudders, then blows: a white flash, shrapnel streaks, sparks, a small fireball and a scorch.",
  tags: ["explosion", "grenade", "shrapnel", "fire", "smoke", "ground", "one-shot"],
  size: [300, 200],
  origin: [160, 170],
  duration: 4.2,
  loop: false,
  fps: 30,
  bg: "ground",
  options: {
    palette: ["#4a1712", "#c9281f", "#f2561d", "#ff8a2a", "#ffc23d", "#ffe26b", "#fff3a6", "#ffffff"],
    body: ["#141a10", "#2c3a1e", "#4a5c30", "#6e8446", "#9ab06a"],
    seed: 6,
  },
};

const BLOW = 1.62, RB = 6.2;

export function create(o) {
  const F = fit(o.palette, 8), FR = fireRamp(F), HR = heatRamp(FR), G = fit(o.body, 5), R = new Rng(o.seed), floor = () => 0;
  const [W, H] = meta.size, [OX, OY] = meta.origin, X0 = -OX + 3, X1 = W - OX - 3, Y0 = -OY + 3, Y1 = H - OY - 3;
  const ps = new Particles({ rng: R, ground: floor, sparks: [F[6], F[5], F[3], F[2]] }), lights = new Lights(), bits = new Bits({ ground: floor });
  const DUST = hex("#7d7280"), METAL = [hex("#3a3c46"), hex("#6a6e7c"), hex("#a8acb8")];
  // the grenade: lobbed from the left, it bounces, rolls and settles
  const g = { x: -140, y: -70, vx: 168, vy: -150, a: 0, va: -9, rest: false };
  let t = 0, blown = false, bx = 0;

  const blast = () => {
    blown = true;
    bx = g.x;
    const y = -5;
    lights.add(bx, y - 10, 70, mix(F[3], F[6], 0.45), 0.85, 0.5);
    lights.add(bx, y, 30, WHITE, 0.7, 0.07);
    // shrapnel: hot streaks flying straight and far, sparks that fall and bounce
    for (let i = 0; i < 38; i++) {
      const a = R.range(-Math.PI + 0.04, -0.04), sp = R.range(380, 640);
      ps.spawn(P.MOTE, bx, y, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.12, 0.26), R.pick([F[7], F[6], F[5]]), R.range(0.6, 0.9));
    }
    for (let i = 0; i < 60; i++) {
      const a = R.range(0, TAU), sp = R.range(140, 360);
      ps.spawn(P.SPARK, bx, y, Math.cos(a) * sp, Math.sin(a) * sp - 60, R.range(0.2, 0.55));
    }
    // a small fireball that cools into smoke
    for (let i = 0; i < 4; i++) ps.spawn(P.FIRE, bx + R.range(-2, 2), y + R.range(-2, 2), R.range(-15, 15), R.range(-30, -8), R.range(0.16, 0.26), 0, R.range(6, 8));
    for (let i = 0; i < 16; i++) {
      const a = R.range(-Math.PI - 0.2, 0.2), d = R.range(0, 6), sp = R.range(40, 150);
      ps.spawn(P.FIRE, bx + Math.cos(a) * d, y + Math.sin(a) * d, Math.cos(a) * sp, Math.sin(a) * sp * 0.8 - 30, R.range(0.45, 0.9), 0, R.range(3.5, 7), 0, R.chance(0.5) ? PF.SMOKES : 0);
    }
    for (let i = 0; i < 9; i++) {
      const a = R.range(-Math.PI, 0), d = R.range(2, 10);
      ps.spawn(P.SMOKE, bx + Math.cos(a) * d, y + Math.sin(a) * d, Math.cos(a) * 25, -R.range(20, 60), R.range(1.4, 2.1), 0, R.range(6, 10), R.range(0.05, 0.3), PF.BIG);
    }
    for (let i = 0; i < 30; i++) {
      const a = R.range(0, TAU), sp = R.range(30, 120);
      ps.spawn(P.EMBER, bx, y, Math.cos(a) * sp, Math.sin(a) * sp - 50, R.range(0.8, 1.8), F[3]);
    }
    // the casing in pieces, and the floor's grit and dust
    for (let i = 0; i < 12; i++) {
      const a = R.range(-Math.PI + 0.2, -0.2), sp = R.range(150, 330);
      bits.add({ kind: B.SHARD, x: bx, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, g: 1, drag: 0.5, bounce: 0.3, life: R.range(1.4, 2.1), a: R.range(0, TAU), va: R.range(-24, 24), s: R.range(2, 3.5), c: R.pick(METAL) });
    }
    for (let i = 0; i < 70; i++) {
      const u = R.range(-1, 1), a = -Math.PI / 2 + u * 0.8, sp = R.range(100, 300) * (1 - 0.4 * Math.abs(u));
      ps.spawn(P.GRIT, bx + u * 4, -1, Math.cos(a) * sp, Math.sin(a) * sp, R.range(1, 1.8), R.pick([hex("#5a4f6b"), hex("#3e3650"), hex("#776c88")]), R.chance(0.35) ? 2 : 1);
    }
    for (let i = 0; i < 10; i++) {
      const s = R.sign();
      ps.spawn(P.SMOKE, bx + s * R.range(0, 6), -R.range(1, 4), s * R.range(60, 180), -R.range(2, 10), R.range(1, 1.7), DUST, R.range(5, 8), R.range(0, 0.05), PF.BIG);
    }
  };

  return {
    update(dt) {
      t += dt;
      if (!blown) {
        // the lob, the bounces, the roll
        if (!g.rest) {
          g.vy += 900 * dt;
          g.x += g.vx * dt;
          g.y += g.vy * dt;
          if (g.y >= -RB && g.vy > 0) {
            g.y = -RB;
            if (g.vy > 90) {
              // a clink, a puff of dust
              for (let i = 0; i < 4; i++) ps.spawn(P.DUST, g.x + R.range(-2, 2), -0.5, R.sign() * R.range(10, 40), -R.range(4, 16), R.range(0.3, 0.6), DUST, R.range(1.5, 2.6));
              for (let i = 0; i < 3; i++) ps.spawn(P.SPARK, g.x, -1, R.range(-60, 60), -R.range(40, 120), R.range(0.08, 0.16));
              g.vy = -g.vy * 0.36;
              g.vx *= 0.8;
            } else g.vy = 0;
          }
          if (g.y >= -RB - 0.01 && g.vy === 0) {
            g.vx -= g.vx * 2.4 * dt;
            g.va = -g.vx / RB;
            if (Math.abs(g.vx) < 3) (g.rest = true), (g.vx = 0);
          }
          g.a += g.va * dt;
        }
        // the fuse: sparks spitting off its tip, a thread of smoke, faster as it runs down
        const tip = fuse(g), hurry = smooth(BLOW - 0.5, BLOW, t);
        if (R.chance((24 + 50 * hurry) * dt)) ps.spawn(P.SPARK, tip[0], tip[1], R.range(-50, 50), -R.range(30, 110), R.range(0.08, 0.2));
        if (R.chance(9 * dt)) ps.spawn(P.VAPOUR, tip[0], tip[1] - 1, R.range(-4, 4), -R.range(10, 20), R.range(0.5, 0.9), hex("#8a8494"), R.range(1.2, 2));
        if (t >= BLOW) blast();
      }
      bits.update(dt);
      for (let i = bits.list.length - 1; i >= 0; i--) if (bits.list[i].x < X0 + 3 || bits.list[i].x > X1 - 3 || bits.list[i].y < Y0 + 3) bits.list.splice(i, 1);
      ps.update(dt);
      cull(ps, X0, Y0, X1, Y1);
      fadeEdges(ps, X0, X1, 24, Y1);
      lights.update(dt);
    },
    drawBack(p) {
      if (blown) {
        const u = t - BLOW;
        scorch(p, HR, u, 22, 1.6, 1 - smooth(meta.duration - BLOW - 0.8, meta.duration - BLOW - 0.15, u), 2);
        const k = u / 0.4;
        if (k < 1) band(p, bx, 0.5, 70 * ease.outCubic(k), 0.16, Math.max(1, 3.5 * (1 - k)), 1.15 - k, [hex("#4a3f69"), hex("#6e6390"), F[3], F[6]], (g2) => Math.sin(g2) < 0);
      }
      drawPs(p, ps, "back", FR);
    },
    draw(p) {
      if (!blown) {
        // the grenade, shuddering in its last half second, the fuse glowing
        const shake = smooth(BLOW - 0.45, BLOW, t), jx = shake * Math.sin(t * 90) * 0.8;
        drawGrenade(p, G, g.x + jx, g.y, g.a);
        const tip = fuse({ ...g, x: g.x + jx });
        p.px(tip[0], tip[1], Math.sin(t * 50) > 0 ? F[6] : F[5]);
        p.glow(tip[0], tip[1], 6 + 3 * shake, F[4], 0.5 + 0.3 * Math.sin(t * 37));
      } else {
        const u = t - BLOW, k = u / 0.4;
        if (k < 1) band(p, bx, 0.5, 70 * ease.outCubic(k), 0.16, Math.max(1, 3.5 * (1 - k)), 1.15 - k, [hex("#4a3f69"), hex("#6e6390"), F[3], F[6]], (g2) => Math.sin(g2) >= 0);
      }
      bits.draw(p);
      drawPs(p, ps, "front", FR);
      if (blown) {
        const u = t - BLOW;
        // the flash: a hot disc for two frames, a flare, a ring of light
        if (u < 0.07) {
          const k2 = 1 - u / 0.07, r = 11 * (0.8 + 0.2 * k2);
          p.circle(bx, -6, r + 1.2, F[2]);
          p.circle(bx, -6, r, k2 > 0.45 ? F[6] : F[5]);
          p.circle(bx, -6, r * 0.6, k2 > 0.45 ? WHITE : F[6]);
        }
        if (u < 0.2) flare(p, bx, -6, 40 * Math.pow(1 - u / 0.2, 1.4), 1 - u / 0.2, F);
        if (u < 0.3) {
          const k3 = u / 0.3, e = 1 - Math.pow(1 - k3, 3);
          const r = 8 + 40 * e;
          p.ring(bx, -6, r, Math.max(1, 2.5 * (1 - k3) + 0.4), F[5], (v, an) => (Math.sin(an) * r > 9 ? 0 : Math.min(1, (1 - k3) * 1.6)));
        }
        pool(p, bx, 1, 70, 12, F[3], 0.55 * Math.max(0, 1 - u / 0.6));
      }
      lights.draw(p);
    },
  };
}

// where the fuse's tip is: on top of the grenade, turning with it
function fuse(g) {
  const ca = Math.cos(g.a), sa = Math.sin(g.a);
  return [g.x + sa * 10.4, g.y - ca * 10.4];
}

// a pineapple grenade turned by a (about 11 x 15 px): an oval body with grooves, lit from the top left, an
// outline, a metal cap with a ring pin, a lever down its side
function drawGrenade(p, G, x, y, a) {
  const ca = Math.cos(a), sa = Math.sin(a), M = [hex("#2a2c36"), hex("#5e6270"), hex("#9a9eac"), hex("#d0d4de")];
  p.shade(x - 13, y - 13, x + 13, y + 13, (px, py) => {
    const dx = px - x, dy = py - y, u = dx * ca + dy * sa, v = -dx * sa + dy * ca; // u across, v along (cap at v < 0)
    // the cap, its ring, and the lever pressed down the side
    if (v < -5 && v > -10.2 && Math.abs(u) < 2.4) return v < -9.4 || Math.abs(u) > 1.7 ? M[0] : u < -0.6 ? M[3] : M[2];
    if (Math.hypot(u + 3.4, v + 8) < 1.9 && Math.hypot(u + 3.4, v + 8) > 0.9) return M[2];
    if (u > 2.2 && u < 3.6 && v > -8.6 && v < 2) return u > 3 ? M[0] : M[1];
    const e = (u / 5.1) ** 2 + ((v - 0.6) / 6.4) ** 2;
    if (e > 1.2) return;
    if (e > 1) return OUTLINE;
    // grooves cut the body into knobbly segments; light from the top left in world space
    const lit = -(dx * 0.6 + dy * 0.8) / 6, gv = Math.abs(((v + 30) % 3.1) - 1.55) < 0.45, gu = Math.abs(((u + 30) % 3.4) - 1.7) < 0.45;
    const i = Math.max(0, Math.min(4, Math.round(2 + lit * 1.7 - (gv || gu ? 1 : 0) + (e < 0.3 && lit > 0.3 ? 1 : 0))));
    return G[i];
  });
}

// The gathering streaks, the pulse rings and the release (cross flare, rings, light) are adapted from Sprite Fusion's
// open-source energy charge (https://www.spritefusion.com/pixel-art-vfx/energy), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, sparkle, clamp, smooth, ease, TAU, WHITE, hex, mix } from "../../core/index.js";
