import { Particles, Lights, P, PF, Rng, fit, band, clamp, smooth, ease, lerp, TAU, WHITE, hex, mix } from "../../core/index.js";
import { fireRamp, drawPs, draft, cull, fadeEdges, pool, haze, glowDome, Plume, Column } from "./_lib.js";

export const meta = {
  name: "Nuke",
  desc: "A blinding white frame, then a fireball lifts on a thin stem into a wide rolling cap that glows from inside; a white skirt flashes and a dust surge sweeps the floor.",
  tags: ["explosion", "nuke", "mushroom", "cloud", "big", "ground", "one-shot"],
  size: [400, 320],
  origin: [200, 284],
  duration: 9,
