};

const FLASH = 0.05, LIFT = 0.07, SKIRT = [0.55, 1.75];
// the cap's smoke: a lit crescent, two mid tones, a dark underside, the darkest hollow
const CAP = ["#a0918c", "#7c6f6e", "#5f5458", "#40373f", "#271f27"].map(hex);

export function create(o) {
