        ps.spawn(P.EMBER, S.x + Math.cos(a) * (S.ring + S.tube), S.y + Math.sin(a) * S.tube * 0.5, Math.cos(a) * R.range(30, 80), -R.range(10, 50), R.range(1.4, 2.6), F[3]);
