      }
      const k = (t - LIFT) / 0.8;
      if (k > 0 && k < 1) band(p, 0, 0.5, 196 * ease.outCubic(k), 0.16, Math.max(1, 5 * (1 - k)), 1.15 - k, [DUST[2], DUST[0], F[5], F[7]], (g) => Math.sin(g) >= 0);
