      const f = (t - FLASH) / 0.13;
      if (f < 1) {
        const r = 22 + 8 * f;
        p.circle(0, -26, r + 1.5, F[2]);
        p.circle(0, -26, r, f < 0.5 ? F[6] : F[5]);
