function dish(p, B, H, fl) {
  p.ellipse(0, 1, 10, 2.6, (d, a) => (d > 0.82 ? B[0] : Math.sin(a) < -0.2 ? (d > 0.6 ? mix(B[3], H[3], 0.3 * fl) : B[2]) : d > 0.55 ? B[1] : B[2]));
