  const y1 = DRIP.y1;
  p.rect(3, L + 1, 1, y1 - L - 1, X[4]);
  p.rect(4, L + 2, 1, y1 - L - 2, X[3]);
  p.px(5, L + 3, X[0]);
  p.rect(5, L + 4, 1, y1 - L - 4, X[0]);
  p.rect(3, y1, 2, 2, X[4]);
  p.px(5, y1, X[3]);
  p.px(5, y1 + 1, X[2]);
