    for (let i = 0; i < m.w; i++)
      for (let j = 0; j < Math.min(m.h, 9); j++) {
        const c = A.pixels[j * m.w + i];
        // skip empty space and the dark outline, light the first pixel of hair under it
        if (!c || luma(c) < 0.15) continue;
        const x = A.x + i, y = A.y + j;
