const TIP = 0.28; // how far it leans toward us, so the upper facets show
const LIGHT = norm([-0.55, -0.75, -0.45]); // toward the light: upper left, in front
function norm([x, y, z]) {
  const l = Math.hypot(x, y, z) || 1;
