      bits.update(dt);
      panes.update(dt);
      lights.update(dt);
      endBy(t, meta.duration, ps, bits, panes);
    },
    drawBack(p) {
      drawFrost(p);
      ps.draw(p, "back");
    },
    draw(p) {
