        if (snapped && t < SNAP + 0.12) p.line(-W / 2 - 1, ROOT + 1, W / 2 + 1, ROOT + 1, WHITE);
        p.glow(0.5, tp + LEN * 0.5, 20, C[4], 0.28);
        // the drop of meltwater swelling at the tip
        if (t < DRIP) {
          const s = seg(t, 0, DRIP);
          p.dot(0.5, ROOT + LEN + 1, C[6], s);
          if (s > 0.6) p.px(0.5, ROOT + LEN + 2, WHITE);
        }
      }
      panes.draw(p, C);
      bits.draw(p);
      ps.draw(p, "front");
      lights.draw(p);
    },
  };
}

// The pop recipe (a gathering, a white flash with a ring and flares, twinkling motes that linger and fade) is
// adapted from Sprite Fusion's open-source sparkle (https://www.spritefusion.com/pixel-art-vfx/sparkle),
