        p.glow(X - 1, Y, 8, WHITE, 0.5 * pop);
        p.glowLine(X + 1, Y - 16, X + 1, Y + 16, 4, C[4], 0.4 * pop); // light grazing the wall's face
      }
      lights.draw(p);
    },
  };
}

