        if (u < 0.03) star(p, 0, -1, sp, 1, 1, [C[2], C[5], C[4], WHITE], 1, 2);
        else if (u < 0.06) star(p, 0, -1, sp, 1.25, 0.55, [C[1], C[4], C[3], C[5]], 1, 2);
