const FPS = 30, N = 120, P = 4, ZAP = 62;
// where the ball is: a closed, wandering path that dips toward the floor once a loop
const at = (t) => {
  const a = (t / P) * TAU;
  return [38 * Math.sin(a) + 9 * Math.sin(2 * a + 1), -42 + 13 * Math.sin(2 * a + 0.4) + 6 * Math.sin(3 * a + 0.5)];
