    if (sa >= life) continue;
    const a = -Math.PI / 2 + q.range(-1.3, 1.3), sp = q.range(50, 170), [sx, sy, vx, vy] = flight(gx, -1, Math.cos(a) * sp, Math.sin(a) * sp, sa, { floor: 0 });
