      p.blend(cx + off, y, VAP, a * (n === 1 ? 1 : 0.65 - 0.25 * fray) * (0.8 + 0.4 * lit));
    }
  }
}

export function drawBack(p, t, o) {
  const C = fit(o.palette, 8), Sh = fit(o.sheen, 4), W = o.width, pulse = 0.85 + 0.15 * Math.sin((TAU * t * 2) / D);
