        const d = px * nx + py * ny, w = lerp(w0, w1, clamp(u)) + 0.35;
        if (Math.abs(d) > w) continue;
        const side = Math.sign(d) * up, q = Math.abs(d) / w, arc = (i + u) * LS;
        let c = q > 0.8 ? (side > 0 ? C[5] : C[1]) : side > 0 ? (q > 0.35 ? C[4] : C[3]) : q > 0.4 ? C[2] : C[3];
        if (w > 1.6 && Math.abs(((arc + d * 0.8) % 5) - 2.5) < 0.45 && q < 0.8) c = C[2];
        p.px(x, y, c);
      }
  }
}

// thorns along it, alternating sides, hooked back toward the root; leaves on short stalks
function thorns(p, pts, T, C, t, R) {
  for (let i = 2; i < N - 1; i += 2) {
    const [ax, ay] = pts[i], [bx, by] = pts[i + 1], dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy) || 1, side = (i / 2) % 2 ? 1 : -1;
    const nx = (-dy / L) * side, ny = (dx / L) * side, w = width(i / N) / 2, len = 1.8 + 2.4 * (1 - i / N), tx0 = dx / L, ty0 = dy / L;
    const x0 = ax + nx * (w - 0.5), y0 = ay + ny * (w - 0.5), tx = x0 + nx * len - tx0 * len * 0.7, ty = y0 + ny * len - ty0 * len * 0.7;
    if (y0 > 0) continue;
    // a hooked thorn: a broad foot on the stem, a sharp lit point raking back toward the root
    p.tri(x0 - tx0 * 1.6, y0 - ty0 * 1.6, x0 + tx0 * 1.4, y0 + ty0 * 1.4, tx, ty, T[1]);
    p.line(x0 + tx0 * 0.8, y0 + ty0 * 0.8, tx, ty, T[2]);
    p.px(tx, ty, T[3]);
  }
  for (const k of [7, 13, 18]) {
    const [ax, ay] = pts[k], [bx, by] = pts[k + 1], a = Math.atan2(by - ay, bx - ax), side = k % 2 ? 1 : -1;
    if (ay > -2) continue;
    const la = a + side * 1.1 + Math.sin(t * 9 + k) * 0.2, lx = ax + Math.cos(la) * 4, ly = ay + Math.sin(la) * 4;
    drawLeaf(p, lx, ly, 7, 2.2, la, 0.3 + Math.sin(t * 5 + k) * 0.4, [C[1], C[3], C[5], C[6]]);
  }
}

export function create(o) {
  const C = fit(o.palette, 8), T = fit(o.thorn, 4), S = fit(o.soil, 8), R = new Rng(o.seed), floor = () => 0;
  const ps = new Particles({ rng: R, ground: floor, sparks: [C[7], C[6], C[5], C[4]] });
  const drops = new Drops(floor), lights = new Lights(), chips = [], torn = [], spots = [];
  let t = 0, burst = false, cracked = false, sunk = false;
  const dirt = (n, sp) => {
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + R.range(-1.2, 1.2), v = R.range(60, 200) * sp;
      chips.push({ x: R.range(-3, 3), y: -1, vx: Math.cos(a) * v, vy: Math.sin(a) * v, a: R.range(0, TAU), va: R.range(-15, 15), s: R.range(1.4, 2.6), pts: stoneShape(R), life: Math.min(R.range(0.6, 0.9), meta.duration - 0.05 - t) });
    }
    for (let i = 0; i < n * 3; i++) {
      const a = -Math.PI / 2 + R.range(-1, 1), v = R.range(50, 200) * sp;
      ps.spawn(P.GRIT, R.range(-3, 3), -1, Math.cos(a) * v, Math.sin(a) * v, Math.min(R.range(0.5, 0.9), meta.duration - 0.05 - t), R.pick([S[5], S[4], S[3]]), R.chance(0.3) ? 2 : 1);
    }
    for (let i = 0; i < n; i++) ps.spawn(P.DUST, R.range(-4, 4), -R.range(0, 3), R.sign() * R.range(15, 60), -R.range(4, 20), Math.min(R.range(0.4, 0.8), meta.duration - 0.05 - t), S[5], R.range(2, 4));
  };
  return {
    update(dt) {
      t += dt;
      if (!burst) (burst = true), dirt(6, 1);
      if (!cracked && t >= CRACK) {
        cracked = true;
        const a = pose(t), b = pose(t - 0.01), [x, y] = a[N], vx = (x - b[N][0]) / 0.01, vy = (y - b[N][1]) / 0.01, sp = Math.hypot(vx, vy) || 1;
        lights.add(x, y, 22, WHITE, 0.5, 0.08);
        lights.add(x, y, 50, C[5], 0.35, 0.4);
        for (let i = 0; i < 18; i++) {
          const ang = Math.atan2(vy, vx) + R.range(-0.7, 0.7), v = R.range(80, 260);
          drops.add(x, y, Math.cos(ang) * v, Math.sin(ang) * v - R.range(0, 60), R.chance(0.3) ? 2 : 1);
        }
        for (let i = 0; i < 4; i++) torn.push({ x, y, vx: (vx / sp) * R.range(40, 120) + R.range(-30, 30), vy: R.range(-90, -20), a: R.range(0, TAU), va: R.range(-12, 12), fl: R.range(0, TAU), vf: R.range(8, 16), life: R.range(0.65, 0.8), max: 0 });
        for (const l of torn) l.max = l.life;
        for (let i = 0; i < 8; i++) ps.spawn(P.STAR, x + R.range(-6, 6), y + R.range(-6, 6), R.range(-20, 20), R.range(-20, 20), R.range(0.15, 0.35), C[7], R.range(0.6, 1.6));
      }
      if (!sunk && t >= 1.08) (sunk = true), dirt(3, 0.5);
      drops.update(dt, (d) => spots.push({ x: d.x, t0: t, w: d.s * 0.7 + R.range(0.2, 1) }));
      for (let i = chips.length - 1; i >= 0; i--) {
        const c = chips[i];
        if ((c.life -= dt) <= 0) chips.splice(i, 1);
        c.vy += 950 * dt;
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        c.a += c.va * dt;
        if (c.y > 0) (c.y = 0), (c.vy *= -0.3), (c.vx *= 0.6);
      }
      for (let i = torn.length - 1; i >= 0; i--) {
        const l = torn[i];
        if ((l.life -= dt) <= 0) torn.splice(i, 1);
        l.vy += 160 * dt;
        l.vx -= l.vx * 2.5 * dt;
        l.vy -= l.vy * 2 * dt;
        l.x += l.vx * dt + Math.sin(l.fl) * 20 * dt;
        l.y += l.vy * dt;
        l.a += l.va * dt;
        l.fl += l.vf * dt;
      }
      ps.update(dt);
      lights.update(dt);
    },
    drawBack(p) {
      // a hole torn in the floor where it comes up, sap spots where it sprays
      const k = 1 - smooth(1.15, 1.35, t);
      for (let x = -5; x <= 5; x++) p.dot(x, 0, Math.abs(x) < 3 ? S[0] : S[1], k * (1 - Math.abs(x) / 7));
      for (const s of spots) {
        const a = (1 - smooth(0.25, 0.6, t - s.t0)) * (1 - smooth(1.2, 1.35, t));
        for (let x = Math.floor(s.x - s.w); x <= Math.ceil(s.x + s.w); x++) p.dot(x, 0, t - s.t0 < 0.1 ? C[6] : C[4], a);
      }
      ps.draw(p, "back");
    },
    draw(p) {
      const pts = pose(t);
      // the smear: a fan of streaks, each the path one point of the outer vine just swept, the tip's white,
      // the ones further in cooling down the ramp, all fading back along their length
      if (t > LASH + 0.04 && t < CRACK + 0.1) {
        const age = clamp((t - CRACK + 0.02) / 0.12), hist = [];
        for (let k = 0; k < 12; k++) hist.push(pose(t - k * 0.0045));
        for (let k = 0; k < 6; k++) haze(p, [hist[k][N], hist[k + 1][N], hist[k + 1][N - 12], hist[k][N - 12]], k < 2 ? C[6] : C[5], 0.4 * (1 - k / 6) * (1 - age));
        for (let i = N - 12; i <= N; i += 2) {
          const q = (N - i) / 12, col = q < 0.1 ? WHITE : q < 0.3 ? C[7] : q < 0.55 ? C[6] : q < 0.8 ? C[5] : C[4], len = Math.round(11 * (1 - q * 0.6));
          for (let k = 0; k < len; k++) p.line(hist[k][i][0], hist[k][i][1], hist[k + 1][i][0], hist[k + 1][i][1], k < 2 && q < 0.1 ? WHITE : col, (1 - age) * (k < len * 0.5 ? 1 : 2 * (1 - k / len)));
        }
        p.glowLine(hist[0][N][0], hist[0][N][1], hist[6][N][0], hist[6][N][1], 14, C[5], 0.35 * (1 - age));
      }
      vine(p, pts, C);
      thorns(p, pts, T, C, t, null);
      const lk = smooth(LASH, CRACK, t) * (1 - smooth(CRACK, CRACK + 0.35, t));
      if (lk > 0) for (let i = 6; i <= N; i += 6) p.glow(pts[i][0], pts[i][1], 12, C[5], 0.18 * lk);
      // the crack: a white burst of air lines and a glint at the tip
      const e = t - CRACK;
      if (e >= 0 && e < 0.12) {
        const [x, y] = pts[N], k = 1 - e / 0.12;
        for (let j = 0; j < 7; j++) {
          const a = (j / 7) * TAU + 0.3, r0 = 4 + 10 * (1 - k), r1 = r0 + 5 * k;
          p.line(x + Math.cos(a) * r0, y + Math.sin(a) * r0, x + Math.cos(a) * r1, y + Math.sin(a) * r1, k > 0.5 ? WHITE : C[6]);
        }
        p.ring(x, y, 3 + 8 * (1 - k), 1, C[7], k);
        sparkle(p, x, y, 7 * k, C[7], C[5], 0.4);
      }
      for (const c of chips) drawRock(p, c.x, c.y, c.s, c.a, c.pts, S, Math.min(1, c.life / 0.25));
      for (const l of torn) drawLeaf(p, l.x, l.y, 6, 2, l.a, l.fl, [C[1], C[3], C[5], C[6]], Math.min(1, l.life / 0.3));
      drops.draw(p, C);
      ps.draw(p, "front");
      lights.draw(p);
    },
  };
}

// The collection pop (white squash, a ring snapping out, star sparks) and the glints follow Sprite Fusion's
// open-source pickup (https://www.spritefusion.com/pixel-art-vfx/pickup), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, flare, clamp, smooth, ease, rand, TAU, WHITE, hex, mix, scale } from "../../core/index.js";
import { Layer, coin, gemlet, glint, pool, blobShadow } from "./_lib.js";

export const meta = {
  name: "Chest open",
  desc: "A banded chest rattles with gold light leaking from its seam, the lid kicks open, rays fan up, and coins and gems arc out, bounce, glint and get collected.",
  tags: ["pickup", "chest", "treasure", "loot", "reward", "gold", "one-shot"],
  size: [176, 112],
  origin: [88, 96],
  duration: 4.6,
  loop: false,
  fps: 30,
  bg: "ground",
  options: {
    palette: ["#1e1206", "#4a2c08", "#86520c", "#c48412", "#f0b424", "#ffe066", "#fff6c4", "#ffffff"],
    wood: ["#110a10", "#24131a", "#3a1f1f", "#552d24", "#73402c", "#925737", "#b07246"],
    coins: 12,
    seed: 3,
  },
};

// gems that come out with the gold: ruby, emerald, sapphire, amethyst (dark to bright)
const GEMS = [
  ["#2a0612", "#6e0f2a", "#b81c3c", "#f0405a", "#ff8a96", "#ffd2d6"],
  ["#06200f", "#0f4a26", "#1a8040", "#34c060", "#8af0a0", "#d8ffe0"],
  ["#0a1030", "#142a70", "#2050c0", "#3a8cf0", "#8ccaff", "#dcf0ff"],
  ["#1a0a2a", "#3e1466", "#6a28a8", "#a050e0", "#d09cff", "#f0e0ff"],
].map((g) => g.map(hex));

const T_OPEN = 0.8, T_COLLECT = 2.55, T_POOF = 3.3;
const RATTLES = [[0.1, 0.4], [0.32, 0.62], [0.5, 0.8], [0.64, 1]];
// the chest: 24 px wide, a 9 px front face, seen from a little above (tilt sin 0.34) so the open top shows
const HW = 12, FH = 9, CS = 0.94, SN = 0.34, HB = FH / CS, LA = 6, LB = 5.5, STRAPS = [-9, 7];
const L = new Layer(40, 44), IL = new Layer(16, 16);

// the lid as rows of screen pixels: which point of its curved profile each row shows, which side, how lit.
// Points that swing below the rim (behind the back wall) are hidden.
function lidRows(th) {
  const best = new Map(), ct = Math.cos(th), st = Math.sin(th);
  for (let i = 0; i <= 260; i++) {
    const al = (i / 260) * Math.PI, dz = LA + LA * Math.cos(al), dy = LB * Math.sin(al);
    const z = -LA + dz * ct - dy * st, y = HB + dz * st + dy * ct;
    if (y < HB - 0.05) continue;
    let nz = Math.cos(al) / LA, ny = Math.sin(al) / LB;
    const nl = Math.hypot(nz, ny);
    (nz /= nl), (ny /= nl);
    const Nz = nz * ct - ny * st, Ny = nz * st + ny * ct;
    const v = y * CS + (LA - z) * SN, dep = z * CS + y * SN, row = Math.floor(-v);
    const cur = best.get(row);
    if (!cur || dep > cur.dep) best.set(row, { row, al, dep, out: Nz * CS + Ny * SN > 0, lit: Ny * 0.95 + Nz * 0.3 - 0.2 });
  }
  const rows = [...best.values()].sort((a, b) => a.row - b.row);
  // the lit crest: the outside row facing the light most squarely
  let hi = null;
  for (const r of rows) if (r.out && (!hi || r.lit > hi.lit)) hi = r;
  if (hi && hi.lit > 0.5) hi.crest = true;
  // stave seams: the row nearest each seam angle
  for (const s of [Math.PI / 3, (2 * Math.PI) / 3]) {
    let k = null;
    for (const r of rows) if (!k || Math.abs(r.al - s) < Math.abs(k.al - s)) k = r;
    if (k && Math.abs(k.al - s) < 0.4) k.seam = true;
  }
  return rows;
}

const tone = (R, l, steps) => R[steps[l > 0.6 ? 0 : l > 0.25 ? 1 : l > -0.1 ? 2 : l > -0.45 ? 3 : 4]];
const IRON = ["#0e0d16", "#1d1c28", "#2f2e3e", "#474658", "#6a6a7e", "#9898ac"].map(hex);

// the glowing hoard inside the open top: a mound of gold, lit from within
function paintHoard(C, W, g) {
  const heat = (k) => C[clamp(Math.round(k + g * 2.2), 0, 7)];
  for (let y = -13; y <= -10; y++)
    for (let x = -HW; x < HW; x++) {
      const h = rand(x, y, 7), k = h < 0.18 ? 5 : h < 0.55 ? 4 : 3;
      L.set(x, y, y === -13 && Math.abs(x + 0.5) > 9 ? W[2] : heat(k - (y === -13 ? 1 : 0)));
    }
  for (let x = -9; x < 9; x++) {
    const top = -13 - Math.round(2.2 * Math.pow(Math.cos(((x + 0.5) / 10) * (Math.PI / 2)), 1.4));
    for (let y = top; y < -13; y++) L.set(x, y, heat(y === top ? 5 : 4 + (rand(x, y, 3) < 0.3 ? 1 : 0)));
  }
}

// the lid at angle th: wood staves, iron straps, a gold lip and hasp outside; dark wood lit by the hoard inside
function paintLid(C, W, th, g) {
  const rows = lidRows(th), heat = (k) => C[clamp(Math.round(k + g * 2.2), 0, 7)], top = rows.length ? rows[0].row : 0;
  for (const r of rows) {
    const u = r.al;
    for (let x = -HW; x < HW; x++) {
      const strap = STRAPS.some((s) => x === s || x === s + 1), left = STRAPS.some((s) => x === s), side = (x + HW + 0.5) / (2 * HW);
      const corner = x === -HW || x === HW - 1;
      let c;
      if (r.out) {
        if (r.row === top && corner && th < 0.6) continue;
        const l = r.lit + 0.2 - side * 0.35 - (r.row === top ? 0.45 : 0);
        if (u < 0.3 || (u < 0.55 && x >= -2 && x <= 1)) c = tone(C, l + (x >= -2 && x <= 1 ? 0.15 : 0.1), [6, 5, 5, 4, 3]);
        else if (corner) c = x < 0 ? IRON[4] : IRON[2];
        else if (strap) c = tone(IRON, l + (left ? 0.3 : -0.3), [5, 4, 3, 2, 1]);
        else if (r.seam) c = W[0];
        else {
          c = r.crest && side < 0.62 ? W[6] : tone(W, l, [5, 4, 3, 2, 1]);
          if (rand(x >> 1, Math.round(u * 6), 11) < 0.2) c = W[Math.max(0, W.indexOf(c) - 1)];
        }
      } else {
        // the inside of the lid, lit by the hoard from below
        const k = g * Math.pow(u / Math.PI, 1.3);
        if (u < 0.3) c = heat(1);
        else if (r.seam) c = W[0];
        else c = k > 0.6 ? mix(W[4], C[5], 0.3) : k > 0.35 ? W[3] : k > 0.15 ? W[2] : W[1];
        if (corner) c = W[0];
      }
      L.set(x, r.row, c);
    }
  }
}

// the front face: a gold rim, two planks, iron straps and corners with rivets, a gold lock plate and keyhole
function paintFront(C, W, g) {
  for (let y = -FH; y <= -1; y++)
    for (let x = -HW; x < HW; x++) {
      const side = (x + HW + 0.5) / (2 * HW);
      let c;
      if (y === -FH) c = side < 0.3 ? C[6] : side < 0.7 ? C[5] : C[4];
      else if (y === -1) c = W[1];
      else if (y === -5) c = W[0];
      else {
        const top = y === -8 || y === -4, bot = y === -6 || y === -2;
        c = W[top ? (side < 0.45 ? 4 : 3) : bot ? 2 : 3];
        if (!top && rand(x >> 1, y, 5) < 0.2) c = W[bot ? 1 : 2];
      }
      if (x === -HW) c = y === -FH ? C[5] : IRON[4];
      if (x === HW - 1) c = y === -FH ? C[3] : IRON[2];
      for (const s of STRAPS) {
        if (x === s && y > -FH) c = y === -7 || y === -3 ? IRON[5] : IRON[4];
        if (x === s + 1 && y > -FH) c = IRON[2];
      }
      L.set(x, y, c);
    }
  for (let y = -FH; y <= -4; y++)
    for (let x = -2; x <= 1; x++) L.set(x, y, x === 1 || y === -4 ? C[3] : x === -2 && y === -FH ? C[7] : C[5]);
