import { fit, clamp, smooth, ease, rand, cycle, band, flare, TAU, WHITE, hex, mix, scale } from "../../core/index.js";
import { Layer, glint, pool, blobShadow } from "./_lib.js";

export const meta = {
  name: "Loot beam",
  desc: "A dropped sword in a tall pillar of rarity light: a white core thinning to the sky, rings pulsing across the floor, motes streaming up, a glint racing up the shaft.",
  tags: ["pickup", "loot", "beam", "rarity", "drop", "item", "loop"],
  size: [96, 176],
  origin: [48, 162],
  duration: 2.4,
  loop: true,
  fps: 30,
  bg: "ground",
  options: {
