const L = new Layer(44, 44), HOVER = 25, RO = 11.5, RI = 5.2, INK = hex("#1a0e04");
const BEATS = [0.25, 0.75], RAYS = 10, LA = Math.atan2(-0.8, -0.6);

// a beat: it swells fast and settles slowly
const swell = (ph) => {
