        const L = [{ off: 0, a: 0, len: 12 * k, wid: 5 * k, core: 0.55 }, { off: 2, a: 0, len: (24 + jit[0] * 8) * k, wid: 2.2 * k, core: 0.4 }];
        for (let i = 0; i < 6; i++) {
          const a = (i < 3 ? -1 : 1) * (0.4 + (i % 3) * 0.45 + jit[i + 1] * 0.2), down = Math.sin(ANG + a);
