const HOLD = { turn: 1, crouch: 3, lean: 1, fx: -9, fy: -38, bx: 10, by: -38, ffx: -5, fbx: 6 };
const HIT_ = { ...HOLD, x: -2, crouch: 5, lean: -3 };
export const act = {
  poses: [
    [0, HOLD],
    [0.42, HOLD],
    [0.42, HIT_, "snap"],
    [0.7, { ...HOLD, x: -1 }],
    [1.1, HOLD],
    [1.5, HOLD],
