// the pointy-top hex (corner radius 1) under grid point (gx, gy): its axial coords and center, how near its
// edge (1 on it) and how near one of its corners (0 on it)
function cell(gx, gy) {
  const fq = (S3 / 3) * gx - gy / 3, fr = (2 / 3) * gy, fs = -fq - fr;
