  };

  // the floor where the beam stands: a pool of light, ripples where rings land, the slam's shockwave
  const floor = (p, near) => {
    const on = t < SLAM ? smooth(0, SLAM, t) * 0.5 : 1 - smooth(SNAP, SNAP + 0.5, t);
    if (!near && on > 0.01) {
      const rx = W * 1.9 + (t < SLAM ? 0 : 2 * Math.sin(t * 6)), ry = 4;
      for (let y = -4; y <= 4; y++)
