          const d = Math.hypot((x + 0.5) / rx, (y + 0.5) / ry);
          if (d > 1) continue;
          p.dot(x, y, d < 0.35 ? C[7] : d < 0.6 ? C[6] : d < 0.85 ? C[5] : C[4], on * clamp((1.05 - d) * 2.4));
        }
