    if (k >= 0 && k < 1) band(p, 0, 0, 10 + 26 * ease.outCubic(k), 0.16, 2 * (1 - k) + 0.5, 1.1 - k, [C[4], C[5], C[6], WHITE], keep, k < 0.3);
  };

