  // and cooling through the beam's color to its own
  const hero = (p) => {
    if (t >= DONE || t < SCAN0 - 0.2) return;
    const blink = Math.floor(t * 24);
    for (const b of body) {
      const a = t - b.ts;
      if (a < 0) {
        if (b.edge && rand(b.x, b.y, blink) < 0.6) p.dot(b.x, b.y, C[1], 0.8 * smooth(SCAN0 - 0.25, SCAN0 - 0.05, t));
