    for (let x = Math.floor(-w); x <= Math.ceil(w); x++) {
      const inside = r && x >= r[0] && x <= r[1];
      p.dot(x, y, inside ? WHITE : C[6], inside ? 1 : 1 - Math.abs(x + 0.5) / (w + 1));
    }
