          if (r && R.chance(0.7)) for (const [x, s] of [[r[0], -1], [r[1] + 1, 1]]) if (R.chance(0.6)) ps.spawn(P.MOTE, x, y, s * R.range(40, 90), R.range(-20, 10), R.range(0.15, 0.3), R.chance(0.5) ? WHITE : C[6], 0.6);
