    const u = Math.floor((x - cx) / s + SW / 2), v = Math.floor((y - cy) / (s * sq) + SH / 2);
    if (!inSkull(u, v)) return;
    const ch = SKULL[v][u];
    if (white) return ch === "e" || ch === "n" ? C[5] : WHITE;
    const ck = CRACKS.get(v * SW + u);
    if (ck !== undefined && ck < crack) return crack > 0.55 && (u + v) % 2 ? C[6] : K[0];
