    const ex = Math.cos(ea) * R, ey = Y + Math.sin(ea) * R, mx = x0 * 0.2, my = -18 - r.range(0, 12);
    const x = (1 - u) * (1 - u) * x0 + 2 * (1 - u) * u * mx + u * u * ex, y = (1 - u) * (1 - u) * -1 + 2 * (1 - u) * u * my + u * u * ey;
