  for (const gp of GULPS) {
    const u = wrap(t / D - gp) / (0.4 / D);
    if (u >= 1) continue;
    const rr = R + 2 + (VR - R) * (1 - ease.inQuad(u));
    ringFast(p, 0, Y, rr, 1, C[4], 0.35 * (1 - u));
    ringLight(p, 0, Y, rr, 4, C[5], 0.3 * (1 - u));
