      life, max: life, c: b.c, kind, lift: R.range(0.4, 1.4), cool: COOL[R.chance(0.3) ? 1 : R.chance(0.3) ? 2 : 0], own: R.chance(0.2), rest: false, seed: R.range(0, 100),
