        else if (r < 0.46) ps.spawn(P.FIRE, b.x, b.y, R.range(-6, 6), -R.range(14, 30), R.range(0.2, 0.42), 0, R.range(1.2, 2.2), 0, R.chance(0.5) ? PF.SMOKES : 0);
