      const q = (u - 0.88) / 0.12;
      sparkle(p, x, y, Math.round(2 * (1 - q)), C[5], C[4], 0.4 * (1 - q));
      return;
    }
    const R = back ? [C[0], C[1], C[2], C[3]] : [C[0], C[2], C[3], C[4]];
    icon(p, x, y, 4, big ? HEART7 : HEART5, R, k);
    if (!back) p.px(x - (big ? 2 : 1), y - 1, C[6]);
    p.glow(x, y, 6, C[3], (back ? 0.12 : 0.22) * k);
