      y = clamp(y + R.range(-0.9, 0.9), 0, 2.5);
      pts.push([x, y]);
      if (i > 1 && R.chance(0.3)) out.push([[x, y], [x + dir * R.range(1, 2), clamp(y + R.sign() * R.range(0.6, 1.4), 0, 3)]]);
    }
    out.push(pts);
  }
