    const old = u > 0.78 ? 1 : 0, R = old ? [C[0], C[1], C[2], C[3]] : [C[1], C[2], C[3], C[4]];
    icon(p, z.x, z.y, 7, ZS[z.size], R, z.k);
    if (!old) p.px(z.x - 2 - z.size, z.y - 2 - z.size * 0.8, C[5]);
    p.glow(z.x, z.y, 7 + z.size * 3, C[3], (old ? 0.12 : 0.26) * z.k);
  }
}

