    if (y < -1) {
      for (const [lag, al] of [[0.22, 0.35], [0.11, 0.6]]) if (age > lag) p.dot(x, yAt(age - lag), C[4], al);
      p.px(x, y - 1, C[5]);
      p.px(x, y, C[6]);
      p.px(x, y + 1, C[5]);
      p.px(x - 1, y + 1, C[4]);
      p.px(x - 1, y, C[7]);
