export const meta = screenMeta({
  name: "Iris",
  desc: "A lit iris closes onto a warm spotlight where dust drifts, holds as its rim twinkles, snaps shut into a glint, then pops open from a flash with a white-hot rim throwing sparks.",
  tags: ["iris", "circle", "spotlight", "wipe"],
  duration: 2.2,
  options: { palette: ["#1c140c", "#3b2a18", "#6e5233", "#a8875a", "#d9bd8a", "#f3e2bd", "#fff7e8", "#ffffff"], focus: [160, 100], seed: 1 },
});

const D = meta.duration, CLOSE = 0.62, SNAP = 0.9, SHUT = 0.99, POP = 1.2, OPEN = 1.75, RS = 24, RW = 5, GLO = 16;

export function create(o) {
  const C = fit(o.palette, 8), ink = hex(o.color), R = new Rng(o.seed), [fx, fy] = o.focus;
  const R0 = Math.max(...[[0, 0], [W, 0], [0, H], [W, H]].map(([x, y]) => Math.hypot(x - fx, y - fy))) + RW + 2;
  const ps = new Particles({ rng: R, sparks: [WHITE, C[6], C[5], C[4]] }), lights = new Lights();
  // the hole's radius: closing, breathing on the spotlight, snapping shut; then popping open
  const radius = (t) =>
    t < CLOSE ? RS + (R0 - RS) * (1 - ease.inOutCubic(t / CLOSE))
      : t < SNAP ? RS + Math.sin((t - CLOSE) * 22) * 0.8 * (1 - (t - CLOSE) / (SNAP - CLOSE))
        : t < SHUT ? RS * (1 - ease.inCubic((t - SNAP) / (SHUT - SNAP)))
          : t < POP ? 0 : R0 * ease.outQuart(clamp((t - POP) / (OPEN - POP)));
  let t = 0, shut = false, popped = false, prevR = R0;
  const end = D - 0.05;
  return {
    update(dt) {
      t += dt;
      const r = radius(t);
      // dust drifts up through the spotlight while it holds
      if (t > CLOSE - 0.25 && t < SNAP && R.chance(0.25)) {
        const a = R.range(0, TAU), d = Math.sqrt(R.next()) * r * 0.9;
        ps.spawn(P.EMBER, fx + Math.cos(a) * d, fy + Math.sin(a) * d, R.range(-6, 6), -R.range(4, 14), R.range(0.4, 0.8), 0, 1);
      }
      // the rim twinkles as it holds
      if (t > CLOSE - 0.1 && t < SNAP && R.chance(0.3)) {
        const a = R.range(0, TAU);
        ps.spawn(P.STAR, fx + Math.cos(a) * (r + 1), fy + Math.sin(a) * (r + 1), 0, 0, R.range(0.2, 0.4), R.chance(0.5) ? WHITE : C[6], R.range(1, 2.4));
      }
      if (!shut && t >= SHUT) {
        shut = true;
        lights.add(fx, fy, 50, C[5], 0.7, 0.3);
      }
      if (!popped && t >= POP) {
        // pop: a white flash, sparks thrown out of the opening
        popped = true;
        lights.add(fx, fy, 140, C[5], 0.7, 0.45);
        lights.add(fx, fy, 50, WHITE, 0.9, 0.12);
        for (let i = 0; i < 40; i++) {
          const a = R.range(0, TAU), v = R.range(150, 420);
          ps.spawn(P.SPARK, fx + Math.cos(a) * 3, fy + Math.sin(a) * 3, Math.cos(a) * v, Math.sin(a) * v, R.range(0.2, 0.5));
        }
      }
      // as the rim races out it sheds glinting motes that fly on and fade
      if (t > POP && t < OPEN - 0.1) {
        const vr = (r - prevR) / dt;
        for (let k = 0; k < 2; k++) {
          if (!R.chance(0.6)) continue;
          const a = R.range(0, TAU), x = fx + Math.cos(a) * r, y = fy + Math.sin(a) * r;
          if (x < 0 || y < 0 || x >= W || y >= H) continue;
          ps.spawn(P.MOTE, x, y, Math.cos(a) * vr * 0.35, Math.sin(a) * vr * 0.35, Math.min(R.range(0.2, 0.45), end - t), R.chance(0.5) ? C[6] : C[5], 0.7);
        }
      }
      prevR = r;
      ps.update(dt);
      lights.update(dt);
    },
    draw(p0) {
      const p = clipTo(p0), r = radius(t);
      // the rim's heat: warm while it closes, white-hot as it pops, cooling as it opens
      const hot = t >= POP ? 1 - smooth(POP, OPEN, t) : t < SNAP ? 0.45 + 0.25 * smooth(CLOSE - 0.2, CLOSE, t) : 0.7;
      const rw = RW + (t >= POP ? 3 * hot : 0);
      if (t < OPEN + 0.05 && !(t >= SHUT && t < POP && r <= 0)) {
        for (let y = 0; y < H; y++) {
          const dy = y + 0.5 - fy, xo = Math.sqrt(Math.max(0, (r + rw) ** 2 - dy * dy)), xi = Math.abs(dy) < r ? Math.sqrt(r * r - dy * dy) : 0;
          if (xo <= 0) {
            rect(p0, 0, y, W, 1, ink);
            continue;
          }
          const a0 = clamp(Math.floor(fx - xo), 0, W), b1 = clamp(Math.ceil(fx + xo), 0, W);
          if (a0 > 0) rect(p0, 0, y, a0, 1, ink);
          if (b1 < W) rect(p0, b1, y, W - b1, 1, ink);
          // the rim band and the light just inside it
          const g = r > GLO ? Math.sqrt(Math.max(0, (r - GLO) ** 2 - dy * dy)) : 0;
          for (let x = a0; x < b1; x++) {
            const dx = x + 0.5 - fx;
            if (Math.abs(dx) < g) continue;
            const d = Math.hypot(dx, dy) - r;
            if (d >= 0) {
              // a bevel lit from the top left: bright there, a step darker round the far side
              const q = d / rw, lit = 0.5 - 0.5 * (dx * 0.7 + dy * 0.7) / (r + d + 0.01), h = hot * (0.55 + 0.6 * lit);
              p0.px(x, y, q >= 1 ? ink : q < 0.2 ? (h > 0.5 ? WHITE : h > 0.3 ? C[6] : C[5]) : q < 0.4 ? (h > 0.38 ? C[6] : C[5]) : q < 0.65 ? (h > 0.3 ? C[5] : C[4]) : q < 0.85 ? C[3] : C[2]);
              if (q < 0.5) p0.light(x, y, C[5], 0.45 * h * (1 - q * 2));
            } else if (d > -GLO) p0.light(x, y, C[5], (0.18 + 0.3 * hot) * (1 + d / GLO) ** 2);
          }
        }
      } else if (t >= SHUT && t < POP) rect(p0, 0, 0, W, H, ink);
      // the spotlight's pool of light, gathering as the iris closes, hottest at its heart
      if (r > 0 && r < 80 && t < SHUT) {
        const k = 1 - r / 80;
        p.glow(fx, fy, r * 1.15 + 6, C[5], 0.18 + 0.32 * k);
        p.glow(fx, fy, r * 0.6 + 3, C[6], 0.25 * k);
      }
      // light catches the iris as it turns: a glint runs once round the rim while it closes
      if (t > 0.08 && t < SNAP) {
        const a = -2.4 + ((t - 0.08) / (SNAP - 0.08)) * TAU, gx = fx + Math.cos(a) * (r + 1), gy = fy + Math.sin(a) * (r + 1);
        if (gx > 2 && gy > 2 && gx < W - 2 && gy < H - 2) glint(p, gx, gy, 7 + 3 * Math.sin(t * 9), t * 3, C[6], C[5], 0.9);
      }
      // snapping shut: the light collapses into a glint that lingers in the dark
      const s = t - SHUT;
      if (s > -0.06 && s < 0.22) glint(p, fx, fy, 14 * (1 - Math.abs(s + 0.01) / 0.23), s * 4, C[6], C[5]);
      // popping open: a flash at the heart
      const u = t - POP;
      if (u >= 0 && u < 0.18) glint(p, fx, fy, 20 * (1 - u / 0.18), 0.4 - u * 3, C[6], C[5]), p.glow(fx, fy, 60, WHITE, 0.6 * (1 - u / 0.18));
      ps.draw(p);
      lights.draw(p);
    },
  };
}

// The glints and the twinkling pixel dust follow Sprite Fusion's open-source sparkle
// (https://www.spritefusion.com/pixel-art-vfx/sparkle), MIT License, Copyright (c) 2026 Hugo Duprez.
import { PAL, fit, hex, clamp, ease, fbm, rand, WHITE } from "../../core/index.js";
import { W, H, screenMeta, clipTo, glint, rect } from "./_lib.js";

export const meta = screenMeta({
  name: "Pixel dissolve",
  desc: "Clumps of blocks wink in, each drawn in a white outline that fills black and cools, with glints; then they wink out, outlines collapsing, the last small ones sparkling away.",
  tags: ["dissolve", "pixel", "blocks", "glint"],
  duration: 2.2,
  options: { palette: PAL.neon, seed: 1 },
});

const P = 0.17, IN0 = 0.04, IN1 = 0.8, OUT0 = 1.12, OUT1 = 1.85, CELL = 20;

// the blocks: 20 px cells, some whole, some in quarters, some in sixteenths. Each winks in and out at its own
// time read off a clumpy field, so they gather in growing patches: small ones scatter first, big ones fill in
const cache = new Map();
function layout(seed) {
  if (cache.has(seed)) return cache.get(seed);
  const blocks = [];
  for (let cy = 0; cy < H / CELL; cy++)
    for (let cx = 0; cx < W / CELL; cx++) {
      const h = rand(cx, cy, seed), n = h < 0.32 ? 1 : h < 0.74 ? 2 : 4, s = CELL / n;
      for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) blocks.push({ x: cx * CELL + i * s, y: cy * CELL + j * s, s });
    }
  const rank = (key) => {
    const v = blocks.map(key), out = new Float32Array(v.length);
    v.map((_, i) => i).sort((a, b) => v[a] - v[b]).forEach((i, k) => (out[i] = k / (v.length - 1)));
    return out;
  };
  const at = (b, sd) => fbm((b.x + b.s / 2) / 64, (b.y + b.s / 2) / 64, sd, 3);
  const uin = rank((b) => at(b, seed) + 0.22 * rand(b.x, b.y, seed + 1) + (b.s === 20 ? 0.12 : b.s === 5 ? -0.08 : 0));
  const uout = rank((b) => at(b, seed + 7) + 0.22 * rand(b.x, b.y, seed + 2) + (b.s === 20 ? -0.14 : b.s === 5 ? 0.1 : 0));
  blocks.forEach((b, i) => {
    b.tin = IN0 + uin[i] * (IN1 - IN0);
    b.tout = OUT0 + uout[i] * (OUT1 - OUT0);
    b.glint = rand(b.x, b.y, seed + 3) < (b.s >= 10 ? 0.32 : 0.1);
    b.gx = b.x + (rand(b.x, b.y, seed + 4) < 0.5 ? 0 : b.s);
    b.gy = b.y + (rand(b.x, b.y, seed + 5) < 0.5 ? 0 : b.s);
    b.spin = (rand(b.x, b.y, seed + 6) - 0.5) * 3;
    // now and then a big block throws a hero glint
    b.L = b.s === 20 && rand(b.x, b.y, seed + 8) < 0.45 ? 9 + 6 * rand(b.x, b.y, seed + 9) : 2.5 + b.s * 0.32;
  });
  cache.set(seed, blocks);
  return blocks;
}

// a square block, filled, with a 1 px rim
// a mote of pixel dust: a lone pixel, or now and then a little cross
function mote(p, x, y, c, cross) {
  p.px(x, y, c);
  if (cross) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(x + dx, y + dy, c);
}

function square(p, x, y, s, fill, rim) {
  const X = Math.round(x), Y = Math.round(y), S = Math.max(1, Math.round(s));
  if (fill) rect(p, X, Y, S, S, fill);
  if (rim && S > 2) rect(p, X, Y, S, 1, rim), rect(p, X, Y + S - 1, S, 1, rim), rect(p, X, Y, 1, S, rim), rect(p, X + S - 1, Y, 1, S, rim);
}

export function draw(p0, t, o) {
  const C = fit(o.palette, 8), ink = hex(o.color), p = clipTo(p0), blocks = layout(o.seed), glints = [], frame = Math.floor(t * 15);
  for (let n = 0; n < blocks.length; n++) {
    const b = blocks[n], ki = (t - b.tin) / P, ko = (t - b.tout) / P, { x, y, s } = b, cx = x + s / 2, cy = y + s / 2;
    if (ki < 0 || ko >= 1.6) continue;
    if (ko < 0) {
      if (ki >= 1) square(p0, x, y, s, ink);
      else {
        // winking in: a white outline swells to the block, it fills with black, its rim cools down the ramp
        const g = ki < 0.35 ? 0.35 + 0.65 * ease.outBack(ki / 0.35) : 1, h = s * g;
        const rim = ki < 0.45 ? WHITE : ki < 0.6 ? C[6] : ki < 0.75 ? C[5] : ki < 0.9 ? C[4] : C[3];
        square(p, cx - h / 2, cy - h / 2, h, ki > 0.2 ? ink : 0, rim);
        if (ki < 0.3 && s >= 10) for (const [dx, dy] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(cx - 0.5 + dx, cy - 0.5 + dy, dx || dy ? C[6] : WHITE);
        p.glow(cx, cy, s * 0.8 + 4, C[5], 0.45 * (1 - ki));
      }
      if (b.glint && ki > 0.15 && ki < 1.6) glints.push([b, (ki - 0.15) / 1.45, 1]);
      // pixel dust flickers round the fresh block
      if (ki < 1.4 && rand(frame, n, 9) < 0.35) mote(p, x + rand(frame, n, 10) * (s + 6) - 3, y + rand(frame, n, 11) * (s + 6) - 3, rand(frame, n, 12) < 0.5 ? WHITE : C[6], rand(frame, n, 17) < 0.25);
    } else {
      if (ko < 0.35) {
        // winking out: its rim lights up...
        const q = ko / 0.35;
        square(p0, x, y, s, ink, q < 0.4 ? C[4] : q < 0.75 ? C[5] : C[6]);
        p.glow(cx, cy, s * 0.8 + 3, C[4], 0.35 * q);
      } else if (ko < 0.75) {
        // ...the black drops away and the white outline collapses into its heart
        const q = (ko - 0.35) / 0.4, h = s * (1 - ease.inQuad(q) * 0.85);
        square(p, cx - h / 2, cy - h / 2, h, 0, q < 0.5 ? WHITE : C[6]);
        p.glow(cx, cy, s * 0.8 + 4, C[5], 0.45 * (1 - q * 0.5));
      } else if (ko < 1) {
        const q = (ko - 0.75) / 0.25;
        for (const [dx, dy] of [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]) if (!(dx || dy) || q < 0.5) p.px(cx - 0.5 + dx, cy - 0.5 + dy, dx || dy ? C[6] : WHITE);
        p.glow(cx, cy, s * 0.5 + 3, C[5], 0.35 * (1 - q));
      }
      if (b.glint && ko > 0.3) glints.push([b, (ko - 0.3) / 1.3, -1]);
      if (ko > 0.3 && ko < 1.5 && rand(frame, n, 13) < 0.3) mote(p, x + rand(frame, n, 14) * (s + 6) - 3, y + rand(frame, n, 15) * (s + 6) - 3, rand(frame, n, 16) < 0.5 ? WHITE : C[6], rand(frame, n, 18) < 0.25);
    }
  }
  // glints on top: a spinning star on a corner of the block, swelling and fading
  for (const [b, u, dir] of glints) {
    if (u <= 0 || u >= 1) continue;
    const L = b.L * Math.pow(Math.sin(Math.PI * u), 0.7);
    glint(p, b.gx, b.gy, L, b.spin * u * dir + 0.4, C[5], C[4]);
    if (b.L > 8) p.glow(b.gx, b.gy, 18 + L, C[5], 0.25 * Math.sin(Math.PI * u));
  }
}

// The impact flash, cracks racing out from the impact, the white flash before the burst, and the glass
// splinters, glints and cold light of the burst are adapted from Sprite Fusion's open-source ice shatter
// (https://www.spritefusion.com/pixel-art-vfx/ice), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Bits, Lights, P, B, Rng, fit, hex, mix, clamp, smooth, sparkle, flare, TAU, WHITE } from "../../core/index.js";
import { W, H, screenMeta, clipTo, fillConvex, rect } from "./_lib.js";

export const meta = screenMeta({
  name: "Shatter wipe",
  desc: "A dark glass pane drops over the screen and bounces; cracks race out from an impact with a flash, then it bursts into tumbling glass shards with lit edges that fall away.",
  tags: ["shatter", "glass", "break", "shards", "wipe"],
  duration: 2.8,
  options: { palette: ["#0c1430", "#162c5c", "#1f4f94", "#2f7fcc", "#58b4ec", "#9bdcff", "#d8f4ff", "#ffffff"], seed: 2 },
});

const D = meta.duration, LAND = 0.55, GP = (2 * H) / (LAND * LAND), REST = 0.3, CRACK = 1.32, BREAK = 1.62, WAVE = 520;
const LX = -0.6, LY = -0.8; // light comes from the top left
const L3 = [-0.42, -0.56, 0.71]; // and a little from the front, for the faces

// the pane's top edge over time: it falls from above the screen, lands, bounces twice and settles
const BOUNCES = (() => {
  const out = [];
  let t0 = LAND, v = GP * LAND * REST;
  for (let k = 0; k < 3; k++) out.push({ t0, v, T: (2 * v) / GP }), (t0 += (2 * v) / GP), (v *= REST);
  return out;
})();
function paneY(t) {
  if (t < LAND) return -H + 0.5 * GP * t * t;
  for (const b of BOUNCES) if (t < b.t0 + b.T) return -(b.v * (t - b.t0) - 0.5 * GP * (t - b.t0) ** 2);
  return 0;
}

// the break: jagged rays out of the impact crossed by rings, every crack shared by the two cells it splits
function pattern(R) {
  const Ix = W * R.range(0.4, 0.6), Iy = H * R.range(0.36, 0.54), NR = 13, RING = [0, 9, 21, 37, 58, 86, 122, 168, 232];
  const ang = Array.from({ length: NR }, (_, i) => ((i + R.range(-0.3, 0.3)) / NR) * TAU), speed = ang.map(() => R.range(800, 1300));
  const V = ang.map((a) => RING.map((r, j) => {
    if (!j) return [Ix, Iy];
    const rr = r * R.range(0.84, 1.16), aa = a + R.range(-0.07, 0.07);
    return [Ix + Math.cos(aa) * rr, Iy + Math.sin(aa) * rr];
  }));
