    const dx = Bp[0] - A[0], dy = Bp[1] - A[1], L = Math.hypot(dx, dy) || 1, n = L > 18 ? 2 : 1, out = [A];
    for (let k = 1; k <= n; k++) {
      const f = k / (n + 1) + R.range(-0.08, 0.08), off = R.range(-1, 1) * Math.min(3, L * 0.07);
      out.push([A[0] + dx * f - (dy / L) * off, A[1] + dy * f + (dx / L) * off]);
    }
    out.push(Bp);
    return out;
  };
