      if (x1 < 0 || y1 < 0 || x0 >= W || y0 >= H) continue;
      // a shard of what's on screen: centered on the visible part, so it spins about what you see
      cx = (clamp(x0, 0, W) + clamp(x1, 0, W)) / 2;
      cy = (clamp(y0, 0, H) + clamp(y1, 0, H)) / 2;
      const d = Math.hypot(cx - Ix, cy - Iy);
      cells.push({ pts, lp: pts.map(([x, y]) => [x - cx, y - cy]), cx, cy, d, r: Math.hypot(x1 - x0, y1 - y0) / 2, tb: BREAK + d / WAVE + R.range(0, 0.04) });
    }
  return { Ix, Iy, cracks, cells };
}

export function create(o) {
  const C = fit(o.palette, 8), ink = hex(o.color), R = new Rng(o.seed), pat = pattern(R), { Ix, Iy } = pat;
  const ps = new Particles({ rng: R, sparks: [C[7], C[6], C[5], C[4]], haze: C[5] });
  const bits = new Bits(), lights = new Lights();
  let t = 0, bounce = -1, struck = false, burst = false;
  const end = D - 0.05;

  // glass splinters thrown from (x, y): little white-tipped streaks that tumble and fall
  const splinters = (x, y, n, vx, vy, spread, sp0, sp1) => {
    for (let i = 0; i < n; i++) {
      const a = Math.atan2(vy, vx) + R.range(-spread, spread), sp = R.range(sp0, sp1), life = Math.min(R.range(0.6, 1.2), end - t);
      if (life > 0.2) bits.add({ kind: B.SHARD, x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, g: 0.8, drag: 0.6, life, a: R.range(0, TAU), va: R.range(-20, 20), s: R.range(1.5, 3.5), c: R.pick([C[7], C[6], C[5]]) });
    }
  };
  const glint = (x, y, s = R.range(1, 2.4)) => ps.spawn(P.STAR, x, y, R.range(-8, 8), R.range(-10, 4), Math.min(R.range(0.3, 0.6), end - t), R.chance(0.5) ? WHITE : C[6], s);

  return {
    update(dt) {
      t += dt;
      // each landing: chips spring off the bottom edge, glints, a cold flash along it
      while (bounce + 1 < BOUNCES.length && t >= BOUNCES[bounce + 1].t0) {
        const k = BOUNCES[++bounce].v / BOUNCES[0].v;
        if (k < 0.05) continue;
        for (let i = 0; i < 5; i++) lights.add(W * (i + 0.5) / 5, H - 2, 70, C[5], 0.5 * k, 0.35);
        for (let i = 0; i < Math.round(26 * k); i++) splinters(R.range(4, W - 4), H - 1, 1, R.range(-0.4, 0.4), -1, 0.5, 120 * k, 330 * k);
        for (let i = 0; i < Math.round(9 * k); i++) glint(R.range(8, W - 8), H - R.range(2, 10));
      }
      if (!struck && t >= CRACK) {
        // the blow: a white flash at the point of impact, a puff of splinters back off the glass
        struck = true;
        lights.add(Ix, Iy, 90, C[5], 0.8, 0.35);
        lights.add(Ix, Iy, 34, WHITE, 0.9, 0.1);
        splinters(Ix, Iy, 16, 0, -1, Math.PI, 60, 240);
        for (let i = 0; i < 5; i++) ps.spawn(P.VAPOUR, Ix, Iy, R.range(-40, 40), R.range(-40, 30), R.range(0.35, 0.6), C[6], R.range(2, 3.5));
      }
      // while the cracks run, glints chase their tips
      if (t > CRACK && t < BREAK && R.chance(0.12)) {
        const c = pat.cracks[R.int(0, pat.cracks.length - 1)];
        if (c.t0 < t) glint(c.x, c.y, R.range(0.6, 1.6));
      }
      if (!burst && t >= BREAK) {
        // the burst: a cold flash, a spray of splinters and a breath of glass dust out of the impact
        burst = true;
        lights.add(Ix, Iy, 170, C[4], 0.55, 0.5);
        lights.add(Ix, Iy, 60, WHITE, 0.8, 0.14);
        splinters(Ix, Iy, 46, 0, -1, Math.PI, 90, 340);
        for (let i = 0; i < 14; i++) {
          const a = R.range(0, TAU), sp = R.range(30, 110);
          ps.spawn(P.VAPOUR, Ix + Math.cos(a) * 4, Iy + Math.sin(a) * 4, Math.cos(a) * sp, Math.sin(a) * sp, R.range(0.45, 0.8), R.chance(0.6) ? C[6] : C[5], R.range(3, 6));
        }
      }
      // the pane bursts outward from the impact: each shard flies off, tumbling, and falls away from the screen
      for (const s of pat.cells) {
        if (!s.broke && t >= s.tb) {
          s.broke = true;
          const dx = s.cx - Ix, dy = s.cy - Iy, d = Math.hypot(dx, dy) || 1, sp = R.range(40, 130) * (1.15 - Math.min(1, s.d / 260));
          s.vx = (dx / d) * sp + R.range(-15, 15);
          s.vy = (dy / d) * sp * 0.6 - R.range(20, 90);
          s.a = 0;
          s.va = R.range(-2.5, 2.5) * (1 + 20 / (s.r + 10));
          s.phi = 0;
          s.vphi = R.sign() * R.range(3, 9);
          s.psi = R.range(0, TAU);
          s.z = 0;
          s.vz = R.range(0.25, 0.7);
          s.g = R.range(0.85, 1.1);
          s.edgeOn = false;
          splinters(s.cx, s.cy, s.r > 24 ? 4 : 2, s.vx, s.vy, 1.2, 60, 220);
          if (R.chance(0.15)) glint(s.cx + R.range(-4, 4), s.cy + R.range(-4, 4));
        }
        if (!s.broke || s.gone) continue;
        s.vy += 950 * s.g * dt;
        s.vx -= s.vx * 0.3 * dt;
        s.cx += s.vx * dt;
        s.cy += s.vy * dt;
        s.a += s.va * dt;
        s.phi += s.vphi * dt;
        s.z += s.vz * dt;
        // turning edge-on to us it flashes: a glint where the light catches the glass
        const on = Math.abs(Math.cos(s.phi)) < 0.2;
        if (on && !s.edgeOn && t < end - 0.3) glint(s.cx, s.cy, R.range(1.4, 2.6));
        s.edgeOn = on;
        if (s.cy - s.r / (1 + s.z) > H + 2) s.gone = true;
      }
      ps.update(dt);
      bits.update(dt);
      lights.update(dt);
    },
    draw(p0) {
      const p = clipTo(p0);
      if (t < BREAK) {
        // the pane: dark glass, a lit bevel along its falling edge, faint reflections that fade once it settles
        const yb = paneY(t) + H, r1 = Math.min(H, Math.floor(yb));
        if (r1 > 0) {
          rect(p0, 0, 0, W, r1, ink);
          const shine = 1 - smooth(0.98, 1.22, t), y0 = yb - H;
          if (shine > 0) {
            for (const [off, w, a] of [[0, 16, 0.05], [22, 3, 0.1], [30, 1, 0.12]])
              for (let y = 0; y < r1; y++) {
                const xc = W * 0.18 + off + (H - (y - y0)) * 0.7;
                for (let x = Math.max(0, Math.floor(xc - w / 2)); x < Math.min(W, Math.ceil(xc + w / 2)); x++) p0.blend(x + 0.5, y + 0.5, C[6], a * shine);
              }
            const st = shine > 0.66 ? 0 : shine > 0.33 ? 1 : 2;
            for (const [dy, c] of [[1, C[6 - st * 2]], [2, C[4 - st]], [3, C[Math.max(1, 2 - st)]]]) if (r1 - dy >= 0 && r1 - dy < H) rect(p0, 0, r1 - dy, W, 1, c);
            // light runs along the edge as it falls, and spills onto the picture below it
            const gx = W * clamp(t / (LAND + 0.25)) * 1.2 - 20;
            for (let x = 0; x < W; x++) {
              const k = Math.max(0, 1 - Math.abs(x - gx) / 28);
              if (k > 0 && r1 - 1 < H) p0.px(x, r1 - 1, k > 0.5 ? WHITE : C[6]), p0.light(x, r1 - 1, C[6], 0.5 * k);
              for (let d = 0; d < 14 && r1 + d < H; d++) p0.light(x, r1 + d, C[5], 0.3 * shine * (1 - d / 14) ** 2 * (0.6 + 0.8 * k));
            }
            if (t < LAND + 0.25 && gx > 0 && gx < W && r1 - 1 < H) sparkle(p, gx, r1 - 1, 6, C[6], C[4], 0.5);
          }
        }
        // the cracks race out from the impact: white at the tip, cooling to ice, each with its shadow
        if (t >= CRACK) {
          for (const c of pat.cracks) {
            if (c.t0 > t) break;
            const age = t - c.t0;
            if (c.x + 1 < W && c.y + 1 < H) p0.px(c.x + 1, c.y + 1, C[1]);
            p0.px(c.x, c.y, age < 0.04 ? WHITE : age < 0.18 ? C[6] : C[5]);
            if (age < 0.3) p0.light(c.x, c.y, C[5], 0.55 * (1 - age / 0.3));
          }
          const u = (t - CRACK) / 0.22;
          if (u < 1) {
            flare(p, Ix, Iy, 30 * Math.pow(1 - u, 1.5), 1 - u, C);
            p.glow(Ix, Iy, 50, WHITE, 0.7 * (1 - u));
          }
          // a beat before the burst, the cracks flare white
          const w = (t - (BREAK - 0.07)) / 0.07;
          if (w > 0) for (const c of pat.cracks) p0.px(c.x, c.y, WHITE), p0.light(c.x, c.y, C[6], 0.4 * w);
        }
      } else {
        // shards still in place first (the pane breaking up outward), then the falling ones, nearest last
        const fall = pat.cells.filter((s) => s.broke && !s.gone).sort((a, b) => b.z - a.z);
        for (const s of pat.cells) if (!s.broke) drawShard(p, p0, s, C, ink, true);
        for (const s of fall) drawShard(p, p0, s, C, ink, false);
      }
      bits.draw(p);
      ps.draw(p);
      lights.draw(p);
    },
  };
}

// a shard: dark glass that tumbles about an axis in its plane (squashing as it turns, a bright sliver
// edge-on), its edges lit where they face the light, its face catching a cool sheen as it turns to it
function drawShard(p, p0, s, C, ink, still) {
  let pts, face = ink, sliver = false, gl = 0;
  if (still) pts = s.pts;
  else {
    const cp = Math.cos(s.phi), sp = Math.sin(s.phi), ci = Math.cos(s.psi), si = Math.sin(s.psi), ca = Math.cos(s.a), sa = Math.sin(s.a), k = 1 / (1 + s.z);
    pts = s.lp.map(([x, y]) => {
      const u = x * ci + y * si, v = (-x * si + y * ci) * cp, qx = u * ci - v * si, qy = u * si + v * ci;
      return [s.cx + (qx * ca - qy * sa) * k, s.cy + (qx * sa + qy * ca) * k];
    });
    // the face's normal, turned by the tumble and the spin, against the light
    const nx0 = si * sp, ny0 = -ci * sp, nz = cp, nx = nx0 * ca - ny0 * sa, ny = nx0 * sa + ny0 * ca;
    const d = Math.abs(nx * L3[0] + ny * L3[1] + nz * L3[2]);
    gl = Math.pow(d, 6);
    // turning toward edge-on the glass reflects more (a grazing sheen), and a hairline sliver goes bright
    const graze = clamp(1 - Math.abs(cp) / 0.3) ** 2;
    face = mix(mix(ink, C[2], 0.12 + 0.4 * gl), C[3], 0.55 * graze);
    sliver = Math.abs(cp) < 0.2;
    if (Math.abs(cp) * s.r < 1.5) face = C[5];
  }
  fillConvex(p0, pts, face);
  let a2 = 0;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) a2 += pts[j][0] * pts[i][1] - pts[i][0] * pts[j][1];
  const sg = a2 > 0 ? 1 : -1;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const [ax, ay] = pts[j], [bx, by] = pts[i], dx = bx - ax, dy = by - ay, L = Math.hypot(dx, dy);
    if (L < 0.5) continue;
    const mx = (dy / L) * sg, my = (-dx / L) * sg, el = mx * LX + my * LY;
    if (still) {
      // a crack in the pane: lit fracture line, its shadow below
      p.line(ax, ay, bx, by, el > 0 ? C[5] : C[4]);
      continue;
    }
    if (el > 0.2 || sliver) {
      p.line(ax - mx, ay - my, bx - mx, by - my, C[4]);
      p.line(ax, ay, bx, by, gl > 0.5 || sliver ? WHITE : C[6]);
      p.glow((ax + bx) / 2, (ay + by) / 2, Math.min(12, 4 + L * 0.3), C[5], 0.12 + 0.3 * gl);
    } else p.line(ax, ay, bx, by, el > -0.3 ? C[4] : C[2]);
  }
}

// The cut's tapered smear (white at the rim, cooling down the ramp with age), the dotted trace it leaves, the
// tip glint, the sparks off the end and the shavings flung off the line are adapted from Sprite Fusion's
// open-source slash (https://www.spritefusion.com/pixel-art-vfx/slash), MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, hex, clamp, smooth, ease, sparkle, WHITE } from "../../core/index.js";
import { W, H, screenMeta, clipTo, fillConvex, halfPlane, rect } from "./_lib.js";

export const meta = screenMeta({
  name: "Slash wipe",
  desc: "A white-hot blade edge slices across the screen, light ahead of it and sparks spraying back over the cover; a second cut flashes through and the cover splits apart.",
  tags: ["slash", "blade", "cut", "sparks", "wipe"],
  duration: 1.7,
  options: {
    palette: ["#151a3d", "#212f6b", "#2c58aa", "#3a8bd8", "#62c8f4", "#b8c9e8", "#e8f1ff", "#ffffff"],
    sparks: ["#fff3a6", "#ffe26b", "#ff8a2a", "#f2561d"],
    seed: 2,
  },
});

const D = meta.duration, SL = 0.55, CS = 1 / Math.hypot(1, SL), HALO = 18;
const T0 = 0.06, SWEEP = 0.62, E0 = -(H / 2) * SL - 4, E1 = W + (H / 2) * SL + 24;
const CUT = 0.84, CSW = 0.07, CHOLD = 0.05, CTRAIL = 0.12, SLIP = CUT + 0.12, SPLIT = CUT + CSW + CHOLD + CTRAIL;

// the blade edge: x where it crosses row y, and how fast it's moving
const edgeAt = (t) => E0 + (E1 - E0) * ease.outCubic(clamp((t - T0) / SWEEP));
const speedAt = (t) => (t < T0 || t > T0 + SWEEP ? 0 : ((E1 - E0) * 3 * (1 - (t - T0) / SWEEP) ** 2) / SWEEP);
const xAt = (e, y) => e + (H / 2 - y) * SL;

export function create(o) {
  const C = fit(o.palette, 8), ink = hex(o.color), R = new Rng(o.seed), n = C.length;
  const ps = new Particles({ rng: R, sparks: o.sparks }), lights = new Lights();
  // the second cut: a "\\" through the middle, from where it enters the screen to where it leaves
  const th = R.range(0.42, 0.56), ux = Math.cos(th), uy = Math.sin(th), nx = uy, ny = -ux;
  const cx = W / 2 + R.range(-24, 24), cy = H / 2 + R.range(-10, 10);
  // the halves overhang the screen a little, so slipping along the cut never uncovers an edge
  const area = [[-24, -24], [W + 24, -24], [W + 24, H + 24], [-24, H + 24]];
  const ends = [-1, 1].map((s) => {
    // walk out along the cut until it leaves the screen
    let lo = 0, hi = 400;
    for (let k = 0; k < 30; k++) {
      const m = (lo + hi) / 2, x = cx + s * ux * m, y = cy + s * uy * m;
      if (x >= 0 && x <= W && y >= 0 && y <= H) lo = m;
      else hi = m;
    }
    return [cx + s * ux * lo, cy + s * uy * lo];
  });
  const [A, B] = ends, LC = Math.hypot(B[0] - A[0], B[1] - A[1]);
  const halves = [1, -1].map((s) => {
    const pts = halfPlane(area, cx, cy, s * nx, s * ny);
    let mx = 0, my = 0;
    for (const [x, y] of pts) (mx += x / pts.length), (my += y / pts.length);
    return { s, pts, mx, my, spin: s * R.range(0.5, 0.9) };
  });
  let t = 0, acc = 0, entered = false, tipped = false, split = false;
  const end = D - 0.05;

  // where a half of the cover is: it slips along the cut, then the halves fly apart, turning a little
  const placeOf = (hf) => {
    const slip = 5 * ease.outCubic(clamp((t - SLIP) / 0.12)) * (hf.s > 0 ? 1 : -0.4), u = Math.max(0, t - SPLIT);
    const sep = 30 * u + 0.5 * 1500 * u * u, rot = hf.spin * u * u;
    return { dx: ux * slip + hf.s * nx * sep, dy: uy * slip + hf.s * ny * sep, rot, sep };
  };
  const moved = (hf, pl, [x, y]) => {
    const c = Math.cos(pl.rot), s = Math.sin(pl.rot), lx = x - hf.mx, ly = y - hf.my;
    return [hf.mx + lx * c - ly * s + pl.dx, hf.my + lx * s + ly * c + pl.dy];
  };

  return {
    update(dt) {
      t += dt;
      // the blade grinds through: sparks spray back over the cover, shavings flake off, light rides the edge
      const sp = speedAt(t), e = edgeAt(t);
      if (!entered && t >= T0) {
        entered = true;
        lights.add(4, 4, 60, C[5], 0.6, 0.25);
      }
      // in bursts: each a fountain of sparks off one spot where the edge bites
      for (acc += sp * dt * 0.035; acc > 1; acc--) {
        const y = R.range(4, H - 4), x = xAt(e, y) - 1, a0 = Math.PI + R.range(-0.1, 0.6), n = R.int(5, 10);
        if (x < 0 || x >= W) continue;
        for (let i = 0; i < n; i++) {
          const a = a0 + R.range(-0.75, 0.75), v = R.range(0.2, 1) * (140 + 0.22 * sp);
          ps.spawn(P.SPARK, x, y + R.range(-2, 2), Math.cos(a) * v, Math.sin(a) * v, R.range(0.15, 0.4));
          if (R.chance(0.4)) ps.spawn(P.MOTE, x, y, Math.cos(a) * v * 0.45, Math.sin(a) * v * 0.45 - 20, R.range(0.2, 0.5), R.chance(0.5) ? C[6] : C[5], 0.7);
        }
        lights.add(x, y, R.range(30, 46), C[5], 0.35, 0.14);
      }
      // the second cut lands: a glint at its end, sparks thrown on along it, shavings off its length
      if (!tipped && t >= CUT + CSW) {
        tipped = true;
        for (let i = 0; i < 12; i++) {
          const a = Math.atan2(uy, ux) + R.range(-0.5, 0.5), v = R.range(150, 400);
          ps.spawn(P.SPARK, B[0] - ux * 2, B[1] - uy * 2, Math.cos(a) * v, Math.sin(a) * v, R.range(0.12, 0.35));
        }
        for (let i = 0; i < 18; i++) {
          const k = R.range(0.1, 1), x = A[0] + (B[0] - A[0]) * k, y = A[1] + (B[1] - A[1]) * k, s = R.sign(), v = R.range(30, 100);
          ps.spawn(P.MOTE, x, y, s * nx * v + ux * 20, s * ny * v - 10, R.range(0.25, 0.55), R.chance(0.5) ? C[5] : C[4], 0.6);
        }
        for (let i = 0; i < 5; i++) lights.add(A[0] + (B[0] - A[0]) * (i + 0.5) / 5, A[1] + (B[1] - A[1]) * (i + 0.5) / 5, 46, C[5], 0.45, 0.3);
      }
      // and the halves break apart: sparks spray out of the opening seam both ways
      if (!split && t >= SPLIT) {
        split = true;
        for (let i = 0; i < 46; i++) {
          const k = R.range(0, 1), x = A[0] + (B[0] - A[0]) * k, y = A[1] + (B[1] - A[1]) * k, s = R.sign(), v = R.range(80, 320);
          const a = Math.atan2(s * ny, s * nx) + R.range(-0.7, 0.7);
          ps.spawn(P.SPARK, x, y, Math.cos(a) * v, Math.sin(a) * v, Math.min(R.range(0.15, 0.45), end - t));
        }
        for (let i = 0; i < 6; i++) lights.add(A[0] + (B[0] - A[0]) * (i + 0.5) / 6, A[1] + (B[1] - A[1]) * (i + 0.5) / 6, 56, C[5], 0.5, 0.35);
      }
      ps.update(dt);
      lights.update(dt);
    },
    draw(p0) {
      const p = clipTo(p0);
      if (t < CUT + CSW + CHOLD + 0.02 || t < SLIP) {
        // the cover behind the blade, row by row: ink, then the smear cooling from the white-hot edge, light ahead
        const e = edgeAt(t), sp = speedAt(t), Ls = clamp(sp * 0.0065, 1.5, 8), echo = clamp(sp / 900) * 0.6;
        for (let y = 0; y < H; y++) {
          const xe = xAt(e, y + 0.5), ia = clamp(Math.floor(xe - (Ls + 10) / CS), 0, W), ib = clamp(Math.ceil(xe + HALO / CS), 0, W);
          if (ia > 0) rect(p0, 0, y, ia, 1, ink);
          for (let x = ia; x < ib; x++) {
            const d = (xe - (x + 0.5)) * CS;
            if (d < 0) {
              const u = 1 + d / HALO;
              p0.light(x, y, C[5], 0.32 * u * u);
              if (d > -4) p0.light(x, y, WHITE, 0.3 * (1 + d / 4) ** 2);
              continue;
            }
            if (d < 1) p0.px(x, y, WHITE);
            else if (d < 2) p0.px(x, y, C[6]);
            else {
              const q = (d - 2) / Ls;
              p0.px(x, y, q < 0.3 ? C[5] : q < 0.55 ? C[4] : q < 0.8 ? C[3] : q < 1 ? C[2] : ink);
              // a dotted trace a beat behind the edge, while it's moving fast
              if (echo > 0 && Math.abs(d - Ls - 7) < 0.5 && (x + y) % 3 === 0) p0.dot(x, y, C[4], echo);
            }
            if (d < Ls + 2) p0.light(x, y, C[5], 0.3 * (1 - d / (Ls + 2)));
          }
        }
      }
      if (t >= SLIP) {
        // the two halves: dark, their cut edges white-hot and cooling to ice; light pours out of the seam
        const heat = 1 - clamp((t - CUT - 0.05) / 0.5);
        for (const hf of halves) {
          const pl = placeOf(hf), pts = hf.pts.map((q) => moved(hf, pl, q)), a = moved(hf, pl, A), b = moved(hf, pl, B);
          // the cut face of this half: white-hot at the edge, cooling and narrowing to an ice rim
          const c = Math.cos(pl.rot), sn = Math.sin(pl.rot), mx = hf.s * (nx * c - ny * sn), my = hf.s * (nx * sn + ny * c);
          const rim = [heat > 0.55 ? WHITE : heat > 0.25 ? C[6] : C[5], heat > 0.4 ? C[6] : C[4], heat > 0.3 ? C[5] : C[3], heat > 0.3 ? C[4] : ink];
          const deep = clamp(1 + pl.sep * 0.5, 1, 4); // the cut face shows more as the halves part
          fillConvex(p0, pts, (x, y) => {
            const d = (x - a[0]) * mx + (y - a[1]) * my;
            if (d < deep) {
              if (d < 2) p0.light(x, y, C[5], 0.4 * heat * (1 - d / 2));
              return rim[Math.max(0, Math.floor(d))];
            }
            return ink;
          });
          if (heat > 0)
            for (let i = 0; i < 8; i++) {
              const k = (i + 0.5) / 8;
              p.glow(a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, 12 + pl.sep * 0.15, C[5], 0.3 * heat);
            }
        }
      }
      // the second cut: a smear that rips along the line, thickest just behind its head, white at its core,
      // cooling down the ramp, its tail dissolving; a dotted trace where it's gone; light riding its head
      const u = t - CUT;
      if (u >= 0 && u < CSW + CHOLD + CTRAIL + 0.25) {
