    if (inStar(px, py)) return !inStar(px + 1, py) || !inStar(px - 1, py) || !inStar(px, py + 1) || !inStar(px, py - 1) ? G[2] : dx + dy < 0 ? G[7] : G[6];
    return l > 0.4 ? G[5] : l > -0.2 ? G[4] : G[3];
