  };

  return {
    update(dt) {
      t += dt;
      if (!hit && t >= HIT) {
        hit = true;
        lights.add(0, 0, 70, C[5], 0.7, 0.4);
        lights.add(-20, 0, 34, WHITE, 0.8, 0.1);
        for (let i = 0; i < 26; i++) {
