      // the ribbon unrolls from the middle, and rolls back up at the end
      const l = L * (t < ROLL ? ease.outCubic(seg(t, 0, OPEN)) : 1 - ease.inCubic(seg(t, ROLL, ROLL + 0.26)));
      const tails = seg(t, OPEN - 0.02, OPEN + 0.12) * (t < ROLL ? 1 : 0);
      const sh = seg(t, 1.2, 1.5), shine = sh > 0 && sh < 1 ? -L - 10 + (2 * L + 20) * sh : null;
      ribbon(p, Rb, G, l, ease.outBack(tails, 2), t);
      if (shine !== null)
        for (let y = -BH + 1; y < BH; y++) {
          const x = shine + (y + BH) * 0.6;
          if (Math.abs(x) < l - 2) (p.px(x, y, Rb[6]), p.px(x + 1, y, Rb[5]));
        }
      // the words type on, each letter popping in white, clipped by the ribbon as it rolls away
      const items = [];
      glyphs.forEach((Lt, i) => {
        const u = t - (TYPE + i * STEP), x = TX + Lt.x * TS + jx;
        if (u < 0 || Math.abs(x + Lt.w) > l - 3) return;
        const s = u < 0.035 ? 2.6 : TS;
        items.push({ g: Lt.g, x: x - ((s - TS) * Lt.w) / 2, y: TY + jy - ((s - TS) * 5) / 2, sx: s, sy: s, flash: u < 0.07 ? 1 : 0 });
      });
      drawWord(p, items, { fill: [G[4], G[5], G[6], G[7]], edge: WHITE, under: G[3], outline: Rb[0], shadow: Rb[1] });
      // the seal: drops in big and faint, stamps with a squash and a flash, ticks, pops at the end
      const dk = seg(t, STAMP - 0.12, STAMP), pk = t - POPSEAL;
      if (dk > 0 && pk < 0.08) {
        const fall = 1 - ease.inQuad(dk), sq = Math.exp(-(t - STAMP) * 30) * (t >= STAMP ? 1 : 0);
        let s = 1 + 0.8 * fall, sx = s * (1 + 0.2 * sq), sy = s * (1 - 0.2 * sq);
        if (pk > 0) (sx = sy = 1 + 0.3 * (pk / 0.08));
        const white = (t >= STAMP && t < STAMP + 0.05) || pk > 0;
        if (dk < 1) p.ellipse(SX, SY + 12, 10 * (1 - 0.3 * fall), 2, Rb[0], 0.5 * dk);
        seal(p, G, SX + jx, SY - 14 * fall + jy, 11, sx, sy, white, seg(t, STAMP + 0.08, STAMP + 0.24));
        p.glow(SX, SY, 22, G[5], 0.3 + (white ? 0.4 : 0));
      }
      const rk = (t - STAMP) / 0.3;
      const rr = 12 + 13 * ease.outCubic(rk);
      if (rk > 0 && rk < 1) p.ellipse(SX, SY, rr * 1.15, rr, rk < 0.3 ? WHITE : G[5], (d) => (d > 1 - 1.4 / rr ? 1.2 - rk : 0));
      // stars pop round the banner one after another
      for (const s of sats) {
        const u = (t - s.t0) / s.dur;
        if (u > 0 && u < 1) sparkle(p, s.x, s.y, s.L * Math.pow(Math.sin(u * Math.PI), 0.7), G[6], G[5], 0.5);
      }
      ps.draw(p);
      p.glow(0, 0, 76, G[4], 0.2 * seg(t, 0.2, 0.5) * (1 - seg(t, ROLL, ROLL + 0.2)));
      lights.draw(p);
    },
  };
}

// The bubble shading (a lit rim top-left, a shaded rim bottom-right, a see-through body, a highlight and a
// refraction fleck, 2x2 and 1 px forms when small) and the surface line are adapted from Sprite Fusion's
// open-source bubbles (https://www.spritefusion.com/pixel-art-vfx/bubbles), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, cycle, clamp, smooth, rand, TAU, WHITE } from "../../core/index.js";
import { WATER, rock } from "./_lib.js";

export const meta = {
  name: "Bubbles",
  desc: "Bubbles stream up from a vent of pebbles, wobbling and swelling as they rise, flare as they cross shafts of light from the surface, then dome up and pop there.",
  tags: ["water", "bubbles", "underwater", "vent", "ambient", "loop"],
  size: [104, 112],
  origin: [52, 104],
  duration: 4,
  loop: true,
  fps: 30,
  bg: "ground",
  options: { palette: WATER, seed: 4 },
};

const D = meta.duration, TOP = -92, HALF = 48;

// the surface: a wavy lit line, a darker band under it
const surfaceY = (x, ph) => TOP + Math.sin(x * 0.13 + ph * TAU * 2) * 1.1 + Math.sin(x * 0.051 - ph * TAU) * 1.3;
// light shafts slanting down from the surface, drifting: how much of one a point is in
const shaft = (x, y, ph) => {
  const u = x + (y - TOP) * 0.32, s = Math.sin(u * 0.16 + ph * TAU) * 0.6 + Math.sin(u * 0.07 - ph * TAU + 1) * 0.4;
  return Math.max(0, s - 0.35) / 0.65;
};

// one bubble at (x, y), radius r, squash q: tiny ones a pixel or a shaded 2x2, bigger ones a lit rim round a
// see-through body with a highlight and a fleck of light refracted through it
function bubble(p, C, x, y, r, q, lit) {
  if (r < 0.9) return p.px(x, y, lit > 0.3 ? WHITE : r < 0.7 ? C[5] : C[6]);
  if (r < 1.5) {
    const X = Math.floor(x), Y = Math.floor(y);
    p.px(X, Y, WHITE);
    p.px(X + 1, Y, C[6]);
    p.px(X, Y + 1, C[5]);
    p.px(X + 1, Y + 1, C[4]);
    p.glow(x + 0.5, y + 0.5, 3, C[5], 0.12 + 0.2 * lit);
    return;
  }
  const rx = r * (1 + q), ry = r * (1 - q);
  p.shade(x - rx - 1, y - ry - 1, x + rx + 1, y + ry + 1, (px, py, out) => {
    const dx = (px - x) / rx, dy = (py - y) / ry, d = Math.hypot(dx, dy) * r;
    if (d > r + 0.5) return;
    const l = (-dx - dy) / Math.SQRT2 / Math.max(0.01, d / r);
    if (d > r - 0.6) out.c = l > 0.45 ? C[6] : l < -0.55 ? C[3] : C[4];
    else p.blend(px, py, C[5], 0.16 + 0.2 * lit);
  });
  p.px(Math.round(x - rx * 0.45), Math.round(y - ry * 0.45), WHITE);
  if (r >= 2.5) p.px(Math.round(x - rx * 0.45) + 1, Math.round(y - ry * 0.45), C[6]);
  if (r >= 2) p.px(Math.round(x + rx * 0.5), Math.round(y + ry * 0.5), C[6]);
  p.glow(x, y, r * 2.4 + 2, C[5], 0.12 + 0.3 * lit);
}

// the bubbles, from the vent's three mouths: each rises faster the bigger it is, swells as the pressure drops,
// wobbles side to side, and pops at the surface
const MOUTHS = [-5, 1, 6];
function each(t, S, fn) {
  cycle(t, D, 46, S, (g) => g.range(2.2, 3.4), (age, life, r, i) => {
    const m = MOUTHS[i % 3], r0 = r.next() < 0.7 ? r.range(0.5, 1.4) : r.range(1.6, 2.6), vy = 30 + 9 * r0 + r.range(-4, 4);
    const wf = r.range(3, 6), wa = 0.8 + r0 * 1.2, ph0 = r.range(0, TAU), drift = r.range(-4, 4);
    const y = -2 - vy * age, k = clamp(-y / -TOP), x = m + drift * k + Math.sin(age * wf + ph0) * wa * k;
    fn({ x, y, r: r0 * (1 + 0.45 * k), q: 0.12 * Math.sin(age * wf * 2 + ph0) * Math.min(1, r0 / 2), i, age, vy });
  });
}

export function drawBack(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D;
  // the water: deeper toward the floor, light falling through it in shafts
  for (let Y = TOP - 2; Y < 0; Y++)
    for (let X = -HALF; X < HALF; X++) {
      const x = X + 0.5, y = Y + 0.5, sy = surfaceY(x, ph);
      if (y < sy) continue;
      const e = 1 - smooth(HALF - 14, HALF, Math.abs(x)), depth = (y - TOP) / -TOP;
      p.blend(x, y, C[1], (0.22 + 0.22 * depth) * e);
      const s = shaft(x, y, ph) * (1 - depth * 0.7) * e;
      if (s > 0.05) p.light(x, y, C[4], 0.2 * s);
    }
  // where the shafts reach the floor, caustic light dances on it
  for (let X = -HALF; X < HALF; X++) {
    const x = X + 0.5, e = 1 - smooth(HALF - 14, HALF, Math.abs(x)), s = shaft(x, -2, ph);
    const c = Math.max(0, 1 - Math.abs(Math.sin(x * 0.42 + Math.sin(x * 0.11 + ph * TAU * 2) * 2.2)) * 2.4);
    if (s * c * e > 0.05) {
      p.light(x, -1, C[5], 0.5 * s * c * e);
      p.light(x, -2, C[4], 0.25 * s * c * e);
      p.light(x, 0, C[4], 0.3 * s * c * e);
    }
  }
  // the vent: a little heap of pebbles round a dark mouth
  const ST = rock();
  for (const [x, y, rr] of [[-9, -1.5, 2.4], [-4, -1, 1.8], [3.5, -1.2, 2.2], [9, -1.4, 2.6], [0, -0.6, 1.4], [-12.5, -0.8, 1.6]])
    p.shade(x - rr - 1, y - rr - 1, x + rr + 1, y + rr + 1, (px, py, out) => {
      const dx = px - x, dy = py - y, d = Math.hypot(dx * 1.1, dy);
      if (d > rr + 0.7 || py > 0) return;
      out.c = d > rr ? ST[0] : dx + dy < -rr * 0.6 ? ST[5] : dx + dy < rr * 0.3 ? ST[3] : ST[2];
    });
  for (const m of MOUTHS) p.px(m, -1, ST[0]);
}

export function draw(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, S = o.seed;
  // specks drifting in the water, flaring in the light
  cycle(t, D, 26, S + 7, D, (age, life, r) => {
    const x = r.range(-HALF + 6, HALF - 6) + Math.sin((age / D) * TAU + r.range(0, TAU)) * 3, y = TOP + 6 + ((r.range(0, 86) + age * 4) % 86);
    const s = shaft(x, y, ph), tw = Math.sin((age / D) * TAU * 3 + r.range(0, TAU));
    if (tw < -0.3 && s < 0.2) return;
    p.px(x, y, s > 0.4 ? WHITE : tw > 0.6 ? C[5] : C[4]);
    if (s > 0.4) p.glow(x, y, 3, C[5], 0.25 * s);
  });
  // the bubbles; when one reaches the surface it domes up, then pops with a ring and a couple of flecks
  each(t, S, (b) => {
    const sy = surfaceY(b.x, ph);
    if (b.y > sy + b.r) bubble(p, C, b.x, b.y, b.r, b.q, shaft(b.x, b.y, ph));
    else {
      const since = (sy + b.r - b.y) / b.vy;
      if (since < 0.12 && b.r >= 1.4) {
        for (let a = Math.PI; a <= TAU + 0.01; a += 0.4 / b.r) p.px(b.x + Math.cos(a) * b.r, sy + Math.sin(a) * b.r * 0.9, C[6]);
        p.px(b.x - b.r * 0.4, sy - b.r * 0.6, WHITE);
      } else if (since < (b.r >= 1.4 ? 0.32 : 0.2)) {
        const k = clamp((since - (b.r >= 1.4 ? 0.12 : 0)) / 0.2), w = Math.max(1, b.r + 1 + k * 4);
        for (let a = 0; a < Math.PI; a += 0.5 / w) if (Math.sin(a) > 0.15) p.dot(b.x + Math.cos(a) * w, sy + Math.sin(a) * w * 0.3, k < 0.4 ? WHITE : C[5], 1.2 - k);
        if (b.r >= 1.4 && k < 0.6) {
          p.px(b.x - 2, sy - 2 - k * 4, C[6]);
          p.px(b.x + 2, sy - 3 - k * 5, C[6]);
        }
      }
    }
  });
  // the surface: a lit line with glints running along it, a darker band under it
  for (let X = -HALF; X < HALF; X++) {
    const x = X + 0.5, y = surfaceY(x, ph), e = 1 - smooth(HALF - 12, HALF, Math.abs(x));
    const glint = Math.sin(x * 0.37 - ph * TAU * 3) * Math.sin(x * 0.13 + ph * TAU) > 0.55;
    p.dot(X, y, glint ? WHITE : C[5], e * 1.3);
    p.dot(X, y + 1, C[3], e * 1.3);
    if ((X & 3) === 0) p.glow(x, y + 1, 7, C[5], (glint ? 0.22 : 0.1) * e);
  }
}

// The bead swelling at the tip and the falling drop's tail follow Sprite Fusion's open-source blood
// (https://www.spritefusion.com/pixel-art-vfx/blood), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, smooth, ease, TAU, WHITE } from "../../core/index.js";
import { WATER, bead, ring, rock } from "./_lib.js";

export const meta = {
  name: "Drip",
  desc: "A bead swells under a wet stone tip and catches the light, pinches off, falls stretched by its speed and plinks into a puddle with a crown, a ring and a tiny rebound.",
  tags: ["water", "drip", "drop", "puddle", "cave", "ambient", "loop"],
  size: [72, 88],
  origin: [36, 78],
  duration: 1.6,
  loop: true,
  fps: 30,
  bg: "ground",
  options: { palette: WATER, height: 62, source: true, seed: 1 },
};

const D = meta.duration, SY = 0.28, G = 760, LET = 0.78, PRX = 20;

// the stone the water gathers on: a lump of ceiling rock tapering to a dripstone point, lit on its left, a dark
// rim, a wet streak running down to the point
function dripstone(p, H) {
  const ST = rock(), top = -H - 14;
  p.shade(-24, top, 22, -H + 0.5, (x, y, out) => {
    // a ragged underside of ceiling rock that hangs down into a short dripstone, its point at x = 0
    const under = top + 7 + Math.sin(x * 0.45) * 1.2 + Math.sin(x * 1.3 + 1) * 0.6 - Math.abs(x + 4) * 0.12, cone = -H - Math.abs(x) * 1.25;
    const bottom = Math.max(under, Math.min(cone, -H)), span = x < 0 ? 24 : 22;
    if (y > bottom || Math.abs(x) > span - Math.max(0, top + 3 - y) * 4) return;
    const rim = y > bottom - 1 || Math.abs(x) > span - 1, lx = (x + 24) / 46, v = (y - top) / 14;
    out.c = rim ? ST[0] : v < 0.25 ? ST[1] : y > under && Math.abs(x) < 6 ? (x < 0 ? ST[4] : ST[2]) : lx < 0.3 ? ST[4] : lx < 0.62 ? ST[3] : ST[2];
    if (!rim && Math.abs(x - 9 - (y - top) * 0.4) < 0.5 && v > 0.3 && v < 0.7) out.c = ST[0];
  });
  // a wet streak down to the point, catching the light
  for (let y = -H - 7; y < -H; y++) p.px(-1, y, y > -H - 3 ? C_WET[1] : C_WET[0]);
  p.px(-1, -H - 2, WHITE);
}
const C_WET = ["#5d6a86", "#9fb6d6"].map((h) => parseInt(h.slice(1, 3), 16) | (parseInt(h.slice(3, 5), 16) << 8) | (parseInt(h.slice(5, 7), 16) << 16) | 0xff000000);

// the puddle: dark see-through water with a lit far edge, the drop's light in it
function puddle(p, C) {
  const ry = PRX * SY;
  for (let Y = Math.floor(-ry); Y < ry; Y++)
    for (let X = -PRX; X < PRX; X++) {
      const x = X + 0.5, y = Y + 0.5, d = (x / PRX) ** 2 + (y / ry) ** 2;
      if (d > 1) continue;
      p.blend(x, y, C[1], 0.72 * Math.min(1, (1 - d) * 5));
    }
  // the far edge catches the light in one fine line
  for (let X = -PRX + 3; X < PRX - 3; X++) {
    const x = X + 0.5, y = -Math.sqrt(1 - (x / PRX) ** 2) * ry;
    p.dot(x, y + 0.5, Math.abs(x) < PRX * 0.5 ? C[4] : C[3], 0.95);
  }
}

export function drawBack(p, t, o) {
  const C = fit(o.palette, 8);
  puddle(p, C);
  const u = t - landAt(o.height);
  if (u >= 0) ring(p, 0, 0, 2 + 17 * ease.outCubic(u / 0.75), SY, 1.1 * (1 - u / 0.75), C, { n: 2, gap: 2.5, half: -1, seed: 1, wob: 0.4 });
  const v = t - landAt(o.height) - REBOUND - BACK;
  if (v >= 0) ring(p, 0, 0, 1.5 + 9 * ease.outCubic(v / 0.5), SY, 0.9 * (1 - v / 0.5), C, { n: 1, half: -1, seed: 2 });
}

const landAt = (H) => LET + Math.sqrt((2 * H) / G);
const REBOUND = 0.06, BACK = 0.2;

export function draw(p, t, o) {
  const C = fit(o.palette, 8), H = o.height, land = landAt(H);
  if (o.source) dripstone(p, H);
  // the bead swells at the tip, wobbling, and catches the light; its neck stretches before it lets go
  if (t < LET) {
    const k = t / LET, r = 0.7 + 2.3 * ease.inQuad(k), wob = 0.15 * Math.sin(t * 26) * k, neck = smooth(0.82, 1, k) * 2.5;
    const cy = -H + r + neck;
    if (neck > 0.2) p.line(0, -H, 0, cy - r, C[5]);
    p.ellipse(0, cy, r * (1 - wob), r * (1 + wob) + 0.3 * k, (d, a) => (d > 0.72 ? (Math.cos(a) < 0 && Math.sin(a) < 0.3 ? C[5] : C[3]) : d < 0.35 && Math.cos(a) > 0 ? C[6] : C[4]));
    if (r > 1) p.px(-r * 0.4, cy - r * 0.45, WHITE);
    p.glow(0, cy, 4 + r * 2, C[5], 0.14 + 0.14 * k);
  } else {
    // a little of it springs back up the tip after it lets go
    const s = (t - LET) / 0.15;
    if (s < 1) p.ellipse(0, -H + 0.8, 1.2 * (1 - s * 0.6), 1 + Math.sin(s * Math.PI) * 0.8, C[4]);
  }
  // the fall, stretched by its speed
  const f = t - LET;
  if (f > 0 && t < land) {
    const y = -H + 3 + 0.5 * G * f * f, vy = G * f;
    bead(p, 0, y, 0, vy, 3, C);
    p.glow(0, y, 6, C[5], 0.2);
  }
  // the plink: a white fleck, a little crown thrown up, the near half of the ring, light
  const u = t - land;
  if (u >= 0) {
    ring(p, 0, 0, 2 + 17 * ease.outCubic(u / 0.75), SY, 1.1 * (1 - u / 0.75), C, { n: 2, gap: 2.5, half: 1, hot: u < 0.08, seed: 1, wob: 0.4, glint: u < 0.5 ? 1 - u * 2 : 0 });
    if (u < 0.06) {
      p.px(0, 0, WHITE);
      p.px(-1, 0, C[6]);
      p.px(1, 0, C[6]);
      p.glow(0, -1, 10, C[5], 0.5 * (1 - u / 0.06));
    }
    // the crown: three flecks thrown out and back
    for (const [vx, vh] of [[-26, 70], [24, 64], [-6, 90]]) {
      const h = vh * u - 0.5 * G * u * u;
      if (h > 0 && u < 0.3) p.px(vx * u, -h, u < 0.1 ? WHITE : C[6]);
    }
    // the rebound: a bead pops up out of the middle and drops back
    const r = u - REBOUND, h = 52 * r - 0.5 * G * 0.5 * r * r * 2;
    if (r > 0 && h > 0) {
      p.line(0, -1, 0, -h + 1, C[5]);
      p.circle(0, -h, 1.1, C[6]);
      p.px(0, -h - 1, WHITE);
    }
    const v = u - REBOUND - BACK;
    if (v >= 0) ring(p, 0, 0, 1.5 + 9 * ease.outCubic(v / 0.5), SY, 0.9 * (1 - v / 0.5), C, { n: 1, half: 1, seed: 2, hot: v < 0.06 });
    p.glow(0, 0, 18, C[4], 0.22 * (1 - clamp(u / 0.6)));
  }
  // the tip and the drop shimmer in the puddle
  const sh = Math.sin(t * 20) > 0 ? 0 : 1;
  p.px(-1 + sh, 2, C[4]);
  if (f > 0 && t < land) {
    const ry = 2 + 0.5 * G * f * f * 0.04;
    p.px(sh, Math.min(4, ry), C[5]);
  }
  // the wet light under the tip and in the puddle
  p.glow(0, -H + 2, 8, C[5], 0.16);
  p.glow(0, 0, 26, C[3], 0.14);
}

// The basin's caustic light (two warped sine nets, light where they cross zero) is adapted from Sprite Fusion's
// open-source bubbles (https://www.spritefusion.com/pixel-art-vfx/bubbles), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, cycle, tileNoise, clamp, smooth, rand, TAU, WHITE } from "../../core/index.js";
import { WATER, bead, ring, rock } from "./_lib.js";

export const meta = {
  name: "Fountain",
  desc: "A stone basin; a jet rises from its spout and blooms into glassy arcs that break into beads, fall back and plink into the water with rings.",
  tags: ["water", "fountain", "jet", "basin", "prop", "ambient", "loop"],
  size: [120, 104],
  origin: [60, 96],
  duration: 2,
  loop: true,
  fps: 30,
  bg: "ground",
  options: { palette: WATER, seed: 3 },
};

const D = meta.duration, SY = 0.34, G = 600, RIM = 10, RX = 36, IN = 29.5, JET = 54, ARCS = 12;
// the basin stands on the floor: its base ellipse touches y = 0 at the front; heights are measured from that plane
const BY = -RX * SY, LEVEL = RIM - 1.2;

// the arcs: water thrown out of the top of the jet in every direction, each a parabola back down to the basin
const arcs = (S) =>
  Array.from({ length: ARCS }, (_, i) => {
    const a = ((i + 0.5) / ARCS) * TAU + rand(i, S) * 0.25, vr = 38 + 14 * rand(i, S + 1), vh = 30 + 26 * rand(i, S + 2);
    const tl = (vh + Math.sqrt(vh * vh + 2 * G * (JET - LEVEL))) / G;
    return { a, vr, vh, tl, ca: Math.cos(a), sa: Math.sin(a) };
  });
// a point along an arc tau seconds into its flight: screen x, y and the height above the floor
const along = (q, tau) => {
  const r = q.vr * tau, h = JET + q.vh * tau - 0.5 * G * tau * tau;
  return [q.ca * r, BY + q.sa * r * SY - h, h];
};

// the stone basin: a wide rim lit toward the light with a dark line round both edges, a wall of stone blocks
// below its near side (lit left, shaded right) standing on the floor
const inEll = (x, y, rx, cy) => (x / rx) ** 2 + ((y - cy) / (rx * SY)) ** 2 <= 1;
function basin(p, ST, half) {
  const cy = BY - RIM, ry = RX * SY;
  p.shade(-RX - 1, cy - ry - 1, RX + 1, 1, (x, y, out) => {
    if (inEll(x, y, RX, cy)) {
      if (inEll(x, y, IN, cy)) return;
      const near = y > cy;
      if (near !== half > 0) return;
      const outer = !inEll(x, y - 1, RX, cy) || !inEll(x, y + 1, RX, cy) || !inEll(x - 1, y, RX, cy) || !inEll(x + 1, y, RX, cy);
      const inner = inEll(x, y - 1, IN, cy) || inEll(x, y + 1, IN, cy) || inEll(x - 1, y, IN, cy) || inEll(x + 1, y, IN, cy);
      const a = Math.atan2((y - cy) / ry, x / RX), lit = -Math.cos(a) * 0.65 - Math.sin(a) * 0.45;
      out.c = outer ? ST[0] : inner ? (y < cy ? ST[2] : ST[1]) : lit > 0.4 ? ST[5] : lit > -0.05 ? ST[4] : lit > -0.45 ? ST[3] : ST[2];
      return;
    }
    // the wall, under the near half of the rim
    if (half < 0 || Math.abs(x) >= RX) return;
    const dx = x / RX, top = cy + Math.sqrt(1 - dx * dx) * ry, base = top + RIM;
    if (y < top || y > base) return;
    const u = Math.asin(clamp(dx)) * RX * 0.62, block = ((((u + 40) / 9) % 1) + 1) % 1, row = y - top, course = row > RIM * 0.5 ? 1 : 0;
    const joint = (((((u + 40 + course * 4.5) / 9) % 1) + 1) % 1) < 0.1;
    out.c = y > base - 1 || Math.abs(x) > RX - 1 || row < 1 ? ST[0] : joint || Math.abs(row - RIM * 0.5) < 0.5 ? ST[1] : dx < -0.4 ? ST[4] : dx < 0.3 ? ST[3] : ST[2];
    if (row >= 1 && row < 2 && !joint) out.c = dx < 0 ? ST[2] : ST[1];
  });
}

// the water in the basin: dark and see-through, a lit band at the far side, caustic light swimming in it
function pool(p, C, ph) {
  const rx = IN, ry = rx * SY, cy = BY - LEVEL, T = ph * TAU;
  for (let Y = Math.floor(cy - ry); Y < cy + ry; Y++)
    for (let X = -Math.ceil(rx); X < rx; X++) {
      const x = X + 0.5, y = Y + 0.5, dx = x / rx, dy = (y - cy) / ry, d = dx * dx + dy * dy;
      if (d > 1) continue;
      p.blend(x, y, dy < -0.55 ? C[3] : C[1], dy < -0.55 ? 0.8 : 0.85);
      const u = x * 0.25 + 1.6 * Math.sin(y * 0.6 + T), w = y * 0.7 + 1.6 * Math.sin(x * 0.14 - T * 2);
      const f = Math.max(0, 1 - Math.abs(Math.sin(u) + Math.sin(w)) * 2.6) * (1 - d);
      if (f > 0.35) p.light(x, y, C[5], 0.3 * f);
    }
}

export function drawBack(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, S = o.seed, ST = rock(), Q = arcs(S);
  basin(p, ST, -1);
  pool(p, C, ph);
  // the arcs on the far side, dimmer, behind the jet
  for (const q of Q) if (q.sa < 0) arc(p, C, q, ph, true);
}

// one arc: a glassy stream that thins as it falls and breaks into beads at the end; beads slide down it
function arc(p, C, q, ph, back) {
  let prev = null;
  for (let tau = 0; tau <= q.tl; tau += 0.012) {
    const [x, y] = along(q, tau), u = tau / q.tl;
    if (prev && u < 0.66) p.line(prev[0], prev[1], x, y, back ? (u < 0.25 ? C[5] : C[4]) : u < 0.2 ? WHITE : u < 0.45 ? C[6] : C[5]);
    prev = [x, y];
  }
  // the beads it breaks into, sliding down at the water's own speed
  for (let k = 0; k < 6; k++) {
    const u = ((ph * 2 + k / 6) % 1) * 0.42 + 0.58, tau = u * q.tl, [x, y] = along(q, tau), vy = (q.vh - G * tau) * -1 + q.sa * q.vr * SY;
    bead(p, x, y, q.ca * q.vr, vy, back ? 1 : k % 3 === 0 ? 2 : 1, back ? [C[0], C[1], C[2], C[2], C[3], C[4], C[5], C[5]] : C);
  }
  // and the ones sliding along the stream itself catch the light
  const g = ((ph * 4 + q.a) % 1) * 0.6, [gx, gy] = along(q, g * q.tl);
  p.px(gx, gy, WHITE);
  if (!back) p.glow(gx, gy, 3, C[5], 0.3);
}

export function draw(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, S = o.seed, ST = rock(), Q = arcs(S), T = ph * TAU;
  // the spout: a little stone stem in the middle of the basin
  p.shade(-3.5, BY - 16, 3.5, BY - LEVEL + 0.5, (x, y, out) => {
    const w = y < BY - 14 ? 3.4 : 2.2;
    if (Math.abs(x) > w) return;
    out.c = Math.abs(x) > w - 0.8 || y < BY - 15.5 ? ST[0] : x < -0.6 ? ST[4] : x < 0.8 ? ST[3] : ST[2];
  });
  // the jet: a glassy column, white down its middle, wobbling a little at the top
  p.shade(-3, BY - JET - 1, 3, BY - 16, (x, y, out) => {
    const v = (BY - 16 - y) / (JET - 16), sway = Math.sin(T * 2 + v * 5) * 0.5 * v, w = 1.3 + 0.5 * v + 0.3 * Math.sin(T * 3 + y * 0.4), q = (x - sway) / w;
    if (Math.abs(q) > 1) return;
    const n = tileNoise(x * 0.9, y * 0.15 + ph * 16, 0, 16, S);
    out.c = q < -0.4 ? C[6] : q < 0.35 ? (n > -0.3 ? WHITE : C[6]) : C[5];
  });
  // the bloom where it opens out at the top
  p.circle(0, BY - JET - 1, 2.4, C[6]);
  p.circle(-0.4, BY - JET - 1.5, 1.4, WHITE);
  p.glow(0, BY - JET, 22, C[5], 0.46 + 0.06 * Math.sin(T * 4));
  p.glow(0, BY - JET - 1, 8, WHITE, 0.3);
  // glints wink along the arcs
  cycle(t, D, 10, S + 30, (g) => g.range(0.2, 0.35), (age, life, r) => {
    const q = Q[Math.floor(r.next() * ARCS)], [x, y] = along(q, r.range(0.1, 0.7) * q.tl), k = Math.sin((Math.PI * age) / life);
    if (q.sa < -0.3) return;
    p.px(x, y, WHITE);
    if (k > 0.6) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(x + dx, y + dy, C[6]);
    p.glow(x, y, 5, C[5], 0.4 * k);
  });
  // foam where the jet leaves the spout
  for (let i = 0; i < 4; i++) p.px(Math.sin(T * 3 + i * 1.7) * 2.5, BY - 16 - (i % 2), i % 2 ? C[6] : WHITE);
  // the arcs on the near side, in front of the jet
  for (const q of Q) if (q.sa >= 0) arc(p, C, q, ph, false);
  // where they come down: near halves of the rings, flecks and tiny crowns thrown up, light on the water
  Q.forEach((q, i) => {
    const f = (ph * 2 + rand(i, S + 9)) % 1, [x, y] = along(q, q.tl);
    ring(p, x, y, 2 + f * 8, SY, 0.8 * Math.pow(1 - f, 1.3), C, { n: 1, half: 1, seed: i });
    const g = (ph * 6 + rand(i, S + 10)) % 1;
    if (g < 0.15) p.px(x, y - 1, WHITE);
    if (g < 0.3 && q.sa > -0.2) p.line(x, y - 1, x + (rand(i, S + 11) - 0.5) * 2, y - 1 - 3 * (1 - g / 0.3), C[6]);
    p.glow(x, y, 6, C[5], 0.18 * (1 - g));
  });
  basin(p, ST, 1);
  // a fine mist hangs round the bloom
  cycle(t, D, 16, S + 20, (g) => g.range(0.8, 1.4), (age, life, r) => {
    const k = age / life, a = r.range(0, TAU), rr = r.range(4, 20) + k * 6, x = Math.cos(a) * rr, y = BY - JET + r.range(-4, 16) + k * 10;
    if (k > 0.75 && r.next() < (k - 0.75) * 4) return;
    p.px(x, y, r.next() < 0.4 ? WHITE : C[6]);
  });
  // light: the jet, and the basin water lit from above
  p.glowLine(0, BY - 16, 0, BY - JET, 10, C[5], 0.18);
  p.glow(0, BY - LEVEL - 2, 46, C[4], 0.26 + 0.03 * Math.sin(T * 2));
  p.glow(0, BY - LEVEL - 20, 30, C[5], 0.12);
}

// The column (a banded white core, strands running through it, light down its length) and the slam with its
// floor ring follow Sprite Fusion's open-source holy-light (https://www.spritefusion.com/pixel-art-vfx/holy-light),
// MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, clamp, smooth, ease, noise, noise2, rand, TAU, WHITE } from "../../core/index.js";
import { WATER, Drops, Ripples, Mist, ring, lace, billow } from "./_lib.js";

export const meta = {
  name: "Geyser",
  desc: "A pool heaves and burbles faster and faster, then blasts a white column of water skyward with a churning foam head; it rains back down in drops and steam, slumps and sputters out.",
  tags: ["water", "geyser", "eruption", "steam", "column", "nature", "one-shot"],
  size: [184, 168],
  origin: [92, 146],
  duration: 5,
  loop: false,
  fps: 30,
  bg: "ground",
  options: { palette: WATER, height: 100, seed: 4 },
};

const SY = 0.22, G = 820, ERUPT = 1.15, FALL = 2.6, GONE = 3.3;
// small spurts while it builds, and the sputters after: [time, height]
const SPURTS = [[0.46, 7], [0.72, 12], [0.92, 9], [1.04, 15], [GONE + 0.15, 15], [GONE + 0.55, 8]];

export function create(o) {
  const C = fit(o.palette, 8), R = new Rng(o.seed), HMAX = o.height, S = o.seed;
  const ps = new Particles({ rng: R }), mist = new Mist(), lights = new Lights(), rings = new Ripples({ sy: SY });
  const plinks = [], pops = [];
  const V0 = Math.sqrt(2 * G * HMAX);
  let t = 0;
  const poolR = (tt) => (12 + 7 * smooth(0, 1, tt) + 15 * ease.outCubic(clamp((tt - ERUPT) / 1.2))) * (1 - 0.25 * smooth(GONE, 4.6, tt));
  const poolK = (tt) => smooth(0, 0.2, tt) * (1 - smooth(4.0, 4.85, tt));
  const drops = new Drops({
    sy: SY,
    g: G,
    onLand: (d) => {
      const inPool = Math.hypot(d.x, d.z) < poolR(t);
      rings.add(d.x, d.z, 0.6, (inPool ? 2.5 : 1.5) + d.s * 1.6, 0.32 + d.s * 0.1, { n: 1, k: inPool ? 0.95 : 0.7, hot: 0.05 });
      plinks.push({ x: d.x, y: d.z * SY, s: d.s, age: 0 });
      if (d.s > 1 && !d.small)
        for (let i = 0; i < 2; i++) {
          const a = R.range(0, TAU), v = R.range(8, 28);
          drops.add({ x: d.x, z: d.z, h: 0.5, vx: Math.cos(a) * v, vz: Math.sin(a) * v, vh: R.range(45, 95), s: 1, small: true, life: 1 });
        }
    },
  });
  // how tall the column stands: a fast blast, surging while it holds, slumping when the pressure goes
  const top = (tt) => {
    if (tt < ERUPT || tt > GONE) return 0;
    return HMAX * ease.outCubic(clamp((tt - ERUPT) / 0.3)) * (0.93 + 0.07 * noise(tt * 2.2, S)) * (1 - ease.inQuad(clamp((tt - FALL) / (GONE - FALL))));
  };
  const head = (tt) => smooth(ERUPT + 0.08, ERUPT + 0.3, tt) * (1 - smooth(FALL + 0.1, FALL + 0.45, tt));
  const spurt = (tt) => {
    let h = 0;
    for (const [s0, hs] of SPURTS) h = Math.max(h, hs * Math.sin(Math.PI * clamp((tt - s0) / 0.2)));
    return h;
  };
  const done = new Set(), once = (key, at) => !done.has(key) && t >= at && done.add(key);
  const emit = (rate, dt) => R.chance(Math.min(1, rate * dt));

  // the column: a white core banded out to blue edges, shadowed on the right; 1 px strands whose streaks run up
  // in jet time (fast and long low down, bunching where the water slows near the top); it spreads as it rises,
  // its sides ragged and running, a sway through it, light all the way up
  function column(p, H, thin) {
    if (H < 1) return;
    const tau = (h) => (V0 - Math.sqrt(Math.max(0, V0 * V0 - 2 * G * Math.min(h, HMAX * 0.96)))) / G;
    p.shade(-22, -H - 2, 22, 0, (x, y, out) => {
      const h = -y, v = h / H, sway = noise(t * 1.6 + h * 0.025, S + 5) * 2.5 * v;
      const rag = noise2(h * 0.2 - t * 11, x < sway ? 3 : 7, S + 6) * (0.5 + 1.8 * v);
      const w = (3.6 + 7.5 * Math.pow(v, 1.8)) * thin + rag, q = (x - sway) / Math.max(1, w), aq = Math.abs(q);
      if (aq > 1) return;
      const X = Math.floor(x), streak = noise2(X * 1.618 + 0.3, (tau(h) - t) * 14, S), body = noise2(Math.floor((x + 40) / 2) * 2.3, (tau(h) - t) * 5, S + 1);
      let lvl = aq < 0.42 ? 0 : aq < 0.7 ? 1 : aq < 0.9 ? 2 : 3;
      if (q > 0.38) lvl++;
      if (streak > 0.28) lvl--;
      if (body < -0.4) lvl++;
      out.c = [WHITE, C[6], C[5], C[4], C[3]][clamp(lvl, 0, 4)];
    });
    p.glowLine(0, 0, 0, -H, 16 + 8 * thin, C[5], 0.12 * thin);
  }

  // the head: water boiling over at the top and falling back round the column in an umbrella of streaks, foam
  // billows churning in it, shadowed underneath, lit on top
  function foamHead(p, H, k, back) {
    if (k <= 0.01 || H < 4) return;
    if (back) {
      // the umbrella: streaks pouring off the rim of the head, running down and thinning out
      for (let i = 0; i < 16; i++) {
        const side = i % 2 ? 1 : -1, x0 = side * (5 + 9 * rand(i, S + 20)) * k, len = (14 + 26 * rand(i, S + 21)) * k, speed = 70 + 50 * rand(i, S + 22);
        for (let j = 0; j < 3; j++) {
          const f = (t * speed / len + j / 3 + rand(i, S + 23)) % 1, y0 = -H + 2 + f * len, x = x0 + side * f * f * 6, L = 1 + 4 * f * (1 - f) * 2;
          if (f < 0.85) p.line(x, y0, x + side * 0.6, y0 + L, f < 0.4 ? C[6] : f < 0.7 ? C[5] : C[4]);
        }
      }
    }
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * TAU + t * (i % 2 ? 1.3 : -1.1), z = Math.sin(a);
      if (z < 0 !== back) continue;
      const rho = (3 + 7 * rand(i, S)) * k, x = Math.cos(a) * rho * 1.25 + noise(t * 3 + i, S + 8) * 2.5;
      const y = -H + z * rho * 0.45 + (rho / 10) * 4 - 4 * (1 - rho / (10 * k)) + noise(t * 3 + i + 50, S + 9) * 2.5, r = (2 + 2.6 * rand(i, S + 2) + 0.7 * Math.sin(t * 7 + i)) * k;
      if (back) billow(p, x, y, r, [C[0], C[1], C[2], C[3], C[3], C[4], C[5], C[5]]);
      else {
        p.circle(x + r * 0.15, y + r * 0.25, r, C[4]);
        p.circle(x, y, r * 0.82, rho > 6 * k ? C[5] : C[6]);
        p.circle(x - r * 0.25, y - r * 0.3, r * 0.5, WHITE);
      }
    }
    if (!back) p.glow(0, -H - 2, 38, C[5], 0.34 * k);
  }

  return {
    update(dt) {
      t += dt;
      const H = top(t), hk = head(t), k = t / ERUPT;
      // building: bubbles burst on the heaving mound, faster and faster, steam starts to lift
      if (t < ERUPT && emit(1.5 + 9 * k * k, dt)) {
        const a = R.range(0, TAU), r = R.range(0, 7), x = Math.cos(a) * r, z = Math.sin(a) * r;
        pops.push({ x, y: z * SY - R.range(1, 3), age: 0, r: R.range(1, 2) });
        rings.add(x, z, 1, R.range(5, 9), 0.55, { n: 1, k: 0.85 });
        for (let i = 0; i < R.int(1, 3); i++) drops.add({ x, z, h: 2, vx: R.range(-25, 25), vz: R.range(-15, 15), vh: R.range(50, 120), s: 1, small: true, life: 1 });
      }
      if (t < ERUPT && emit(3 + 7 * k, dt)) mist.add(R.range(-8, 8), -R.range(1, 5), R.range(-10, 10), -R.range(6, 18), 2, R.range(5, 9), R.range(0.9, 1.5), C[6], 0.22);
      for (const [s0, hs] of SPURTS)
        if (once("spurt" + s0, s0 + 0.08))
          for (let i = 0; i < 3 + Math.round(hs / 4); i++) {
            const a = R.range(0, TAU), v = R.range(10, 40);
            drops.add({ x: 0, z: 0, h: hs * 0.8, vx: Math.cos(a) * v, vz: Math.sin(a) * v, vh: R.range(20, 90), s: R.chance(0.3) ? 2 : 1 });
          }
      if (once("erupt", ERUPT)) {
        // the blast: light, a ring thrown across the ground, water flung high, steam rolling out
        lights.add(0, -26, 64, C[5], 0.85, 0.6);
        lights.add(0, -4, 28, WHITE, 0.75, 0.1);
        rings.add(0, 0, 6, 40, 1.2, { n: 2, gap: 3, k: 1.2, hot: 0.12, glint: 1 });
        for (let i = 0; i < 44; i++) {
          const a = R.range(0, TAU), v = R.range(30, 120);
          drops.add({ x: Math.cos(a) * 3, z: Math.sin(a) * 3, h: R.range(2, 10), vx: Math.cos(a) * v, vz: Math.sin(a) * v, vh: R.range(180, 400), s: R.chance(0.15) ? 3 : R.chance(0.35) ? 2 : 1, delay: R.range(0, 0.12) });
        }
        for (let i = 0; i < 12; i++) {
          const s = i % 2 ? 1 : -1;
          mist.add(s * R.range(3, 9), -R.range(1, 6), s * R.range(30, 80), -R.range(4, 18), 3, R.range(9, 14), R.range(1.2, 1.9), R.chance(0.5) ? C[6] : WHITE, 0.3, R.range(0, 0.15));
        }
        for (let i = 0; i < 14; i++) ps.spawn(P.STAR, R.range(-16, 16), -R.range(8, 80), R.range(-10, 10), -6, R.range(0.3, 0.7), R.chance(0.5) ? WHITE : C[6], R.range(1, 2.6), R.range(0.05, 0.5));
      }
      // holding: the head sheds drops that rain back down, spray hangs off the column, steam pours off the top
      if (hk > 0) {
        if (emit(60 * hk, dt)) {
          const a = R.range(0, TAU), v = R.range(10, 60);
          drops.add({ x: R.range(-9, 9), z: R.range(-4, 4), h: H + R.range(-8, 3), vx: Math.cos(a) * v, vz: Math.sin(a) * v, vh: R.range(-40, 60), s: R.chance(0.08) ? 3 : R.chance(0.3) ? 2 : 1 });
        }
        if (emit(9 * hk, dt)) mist.add(R.range(-8, 8), -H + R.range(-6, 2), R.range(-34, 34), -R.range(14, 34), 3, R.range(8, 13), R.range(0.9, 1.4), R.chance(0.6) ? C[6] : WHITE, 0.2);
        if (emit(5 * hk, dt)) mist.add(R.sign() * R.range(3, 9), -R.range(1, 6), R.sign() * R.range(20, 50), -R.range(2, 10), 3, R.range(8, 12), R.range(1, 1.6), C[6], 0.22);
        if (emit(40 * hk, dt)) {
          const s = R.sign(), hh = R.range(8, H * 0.95);
          ps.spawn(P.FLAKE, s * (3 + 6 * Math.pow(hh / H, 1.8)), -hh, s * R.range(10, 45), R.range(-20, 10), R.range(0.6, 1.2), R.chance(0.5) ? WHITE : C[6], R.range(0.6, 1.3));
        }
        if (emit(4 * hk, dt)) rings.add(R.range(-2, 2), R.range(-2, 2), 4, poolR(t) * R.range(0.7, 1), 0.9, { n: 1, k: 0.8 });
        if (emit(7 * hk, dt)) ps.spawn(P.STAR, R.range(-14, 14), -R.range(10, H + 8), R.range(-6, 6), -4, R.range(0.25, 0.55), R.chance(0.4) ? WHITE : C[6], R.range(0.8, 2.2), 0);
      }
      if (once("collapse", FALL + 0.12)) {
        // the head falls apart: a heavy rain of drops all at once
        for (let i = 0; i < 40; i++) {
          const a = R.range(0, TAU), v = R.range(15, 80);
          drops.add({ x: R.range(-6, 6), z: R.range(-3, 3), h: top(t) + R.range(-8, 4), vx: Math.cos(a) * v, vz: Math.sin(a) * v, vh: R.range(-40, 60), s: R.chance(0.12) ? 3 : R.chance(0.35) ? 2 : 1, delay: R.range(0, 0.25) });
        }
        for (let i = 0; i < 6; i++) mist.add(R.range(-8, 8), -top(t) + R.range(-6, 6), R.range(-34, 34), -R.range(10, 26), 4, R.range(9, 13), R.range(0.8, 1.2), C[6], 0.18);
      }
      for (let i = pops.length - 1; i >= 0; i--) if ((pops[i].age += dt) > 0.12) pops.splice(i, 1);
      for (let i = plinks.length - 1; i >= 0; i--) if ((plinks[i].age += dt) > 0.14) plinks.splice(i, 1);
      drops.update(dt);
      rings.update(dt);
      mist.update(dt);
      ps.update(dt);
      lights.update(dt);
    },
    drawBack(p) {
      // the pool: dark see-through water, a lit far rim
      const pr = poolR(t), pk = poolK(t);
      if (pk > 0)
        p.each(-pr, -pr * SY, pr, pr * SY, (x, y, sx, sy) => {
          const d = (x / pr) ** 2 + (y / (pr * SY)) ** 2;
          if (d > 1) return;
          p.blendPx(sx, sy, d < 0.15 ? C[2] : C[1], 0.6 * pk * Math.min(1, (1 - d) * 4));
          if (y < 0 && d > 0.78 && d < 0.95) p.blendPx(sx, sy, C[4], 0.7 * pk);
        });
      rings.draw(p, C, -1);
      const u = (t - ERUPT) / 0.4;
