const ageOf = (t, t0) => (((t - t0) % D) + D) % D;
// a ring's radius and strength at age a
const ringR = (a) => 3 + 34 * Math.pow(a / 1.8, 0.7);
const ringK = (a) => (a < 1.8 ? 1.3 * Math.pow(1 - a / 1.8, 1.3) * Math.min(1, a / 0.06) : 0);
