}

// the river sliding out of the notch between the boulders, seen from just above: flow lines sliding to the edge
function river(p, C, ph, H, W, S) {
  const top = -H - 6;
  p.shade(-W - 3, top, W + 3, -H, (x, y, out) => {
    const back = top + 1.5 + tileNoise(x * 0.3, 4, 0, 0, S + 62) * 1.5, v = (y - back) / (-H - back), hw = W + 2 - (1 - v) * 3;
    if (y < back || Math.abs(x) > hw) return;
    const n = tileNoise(x * 0.32, (y - top) * 0.7 - ph * 8, 0, 8, S + 3);
    out.c = n > 0.66 ? C[6] : n > 0.4 ? C[5] : v < 0.5 ? C[3] : C[4];
  });
}

// the curl over the edge: glassy blue as it rolls, a hard white line along the bend; its light on the stone
function curl(p, C, ph, H, W, S) {
  for (let x = -W; x <= W; x++) {
    const g = tileNoise(x * 0.45, ph * 4, 0, 4, S + 4);
    p.px(x, -H - 1, C[4]);
    p.px(x, -H, WHITE);
    p.px(x, -H + 1, g > 0.2 ? C[6] : C[5]);
  }
  p.glowLine(-W, -H, W, -H, 6, C[6], 0.18);
  p.glow(0, -H, 34, C[5], 0.2);
  // glints run along it
  cycle(ph * D, D, 4, S + 5, 0.36, (age, life, r) => {
    const k = Math.sin((Math.PI * age) / life), x = r.range(-W, W);
    if (k > 0.5) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(x + dx, -H + dy, C[6]);
    p.glow(x, -H, 6, C[5], 0.4 * k);
  });
}

// the pool: dark see-through water, a lit far rim, caustic light swimming in it, the falls' reflection
function pool(p, C, ph, W, S) {
  const [RX, RY] = POOL, cy = 2;
  const T = ph * TAU, cols = [];
  for (let X = -RX; X < RX; X++) {
    const x = X + 0.5;
    cols.push([Math.sin(x * 0.11 - T * 2), Math.sin(T + x * 0.05) * 1.4 + x * 0.13]);
  }
  for (let Y = Math.floor(cy - RY); Y < cy + RY; Y++) {
    const y = Y + 0.5, dy = (y - cy) / RY, sy = Math.sin(y * 0.5 + T);
    for (let X = -RX; X < RX; X++) {
      const x = X + 0.5, dx = x / RX, d = dx * dx + dy * dy;
      if (d > 1) continue;
      p.blend(x, y, d < 0.12 ? C[2] : C[1], 0.62 * Math.min(1, (1 - d) * 4));
      // caustics: two warped sine nets, light where either crosses zero
      const [cx1, cx2] = cols[X + RX], u = x * 0.2 + 1.8 * sy, w = y * 0.55 + 1.8 * cx1;
      const f = (Math.max(0, 1 - Math.abs(Math.sin(u) + Math.sin(w)) * 2.6) + 0.6 * Math.max(0, 1 - Math.abs(Math.sin(cx2 + y * 0.3)) * 3)) * (1 - d);
      if (f > 0.5) p.light(x, y, C[5], 0.18 * f);
    }
  }
  // a few glints sit on the far shore
  for (let i = 0; i < 7; i++) {
    const a = Math.PI * (1.12 + 0.76 * ((i + 0.5) / 7)), x = Math.cos(a) * RX * 0.96, y = cy + Math.sin(a) * RY * 0.96, g = Math.sin(ph * TAU * 2 + i * 2.4);
    if (g > 0.2) p.px(x, y, g > 0.8 ? C[6] : C[4]);
  }
  // the falls mirrored in the water, broken by the chop
  p.shade(-W - 3, 3, W + 3, 10, (x, y, out) => {
    const n = tileNoise(x * 0.9, (y - 3) * 0.35 + ph * 6, 0, 6, S + 6), k = 1 - (y - 3) / 7;
    if (Math.abs(x) > W + 2 - (y - 3) * 0.4 || n < 0.25 + (1 - k) * 0.4) return;
    out.c = n > 0.6 && k > 0.6 ? C[6] : C[5];
  });
}

// the foot: a churning white band, billows rolling out of it, spray thrown clear landing with rings
function foam(p, C, t, ph, W, S) {
  const R = W + 10;
  p.shade(-R, -13, R, 3, (x, y, out) => {
    const ax = Math.abs(x), lump = tileNoise(x * 0.22, ph * 6, 0, 6, S + 7) * 3 + tileNoise(x * 0.55 + 9, ph * 12, 0, 12, S + 8) * 1.5;
    const top = -8 + lump + Math.pow(ax / R, 2) * 7;
    if (ax > R - Math.max(0, -y - 1) * 0.6 || y < top) return;
    // the churn in lumps: each boil lit on top, shadowed under, darker where it meets the pool
    const n = tileNoise(x * 0.5, (y - top) * 0.5 - ph * 10, 0, 10, S + 9), boil = tileNoise(x * 0.42 + 3, y * 0.42 - ph * 8, 0, 8, S + 12), u = y - top;
    if (y > 1) out.c = n > 0 ? C[5] : C[4];
    else if (u < 1.2) out.c = WHITE;
    else if (boil < -0.3) out.c = u > 4 ? C[4] : C[5];
    else if (boil < -0.05) out.c = C[6];
    else out.c = n > -0.2 ? WHITE : C[6];
  });
  cycle(t, D, 30, S + 10, 0.7, (age, life, r) => {
    const k = age / life, side = r.sign(), x0 = r.range(-W, W) * 0.9, sp = r.range(2, 8), up = r.range(2, 8);
    const x = x0 + side * ease.outCubic(k) * sp, y = -r.range(2, 5) - ease.outCubic(k) * up, rad = r.range(1.4, 3) * Math.pow(Math.sin(Math.PI * k), 0.7);
    if (rad > 0.6) billow(p, x, y, rad, C);
  });
  // spray: beads thrown clear of the churn, landing in the pool with a ring
  cycle(t, D, 18, S + 11, 1, (age, life, r) => {
    const side = r.sign(), x0 = side * r.range(2, W + 4), vx = side * r.range(12, 60), vy = -r.range(70, 150), z = r.range(-3, 9), s = r.next() < 0.3 ? 2 : 1;
    const land = z * SY, tl = (-vy + Math.sqrt(vy * vy + 2 * G * (land + 5))) / G;
    if (age < tl) bead(p, x0 + vx * age, -5 + vy * age + 0.5 * G * age * age, vx, vy + G * age, s, C);
    else if (age < tl + 0.35) ring(p, x0 + vx * tl, land, 1 + (age - tl) * 12, SY, 1 - (age - tl) / 0.35, C, { n: 1 });
  });
}

// mist: soft puffs rolled out of the churn that drift sideways along the pool, swell and thin, with a cool light
function mist(p, C, t, S, n, seed) {
  cycle(t, D, n, S + seed, (g) => g.range(1.8, 2.8), (age, life, r) => {
    const k = age / life, side = r.sign(), drift = ease.outCubic(k);
    const x = side * (r.range(3, 12) + drift * r.range(24, 48)), y = -r.range(2, 7) - k * r.range(3, 12);
    const rad = r.range(4, 6) + k * r.range(5, 9), a = r.range(0.2, 0.3) * Math.min(1, k / 0.12) * Math.pow(1 - k, 1.7);
    p.disc(x, y, rad, C[6], (d) => a * (1 - d * d));
    if (a > 0.05) p.glow(x, y, rad * 1.2, C[4], 0.35 * a);
  });
}

export function drawBack(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, W = o.width;
  pool(p, C, ph, W, o.seed);
  for (let i = 0; i < 3; i++) {
    const f = (ph + i / 3) % 1;
    ring(p, 0, 1, W + 6 + f * 38, SY, 0.95 * Math.pow(1 - f, 1.5), C, { n: 1, half: -1, seed: i + 1 });
  }
  mist(p, C, t, o.seed, 7, 20);
}

export function draw(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, H = o.height, W = o.width, S = o.seed, T = ph * TAU;
  for (let i = 0; i < 3; i++) {
    const f = (ph + i / 3) % 1;
    ring(p, 0, 1, W + 6 + f * 38, SY, 0.95 * Math.pow(1 - f, 1.5), C, { n: 1, half: 1, seed: i + 1, glint: f < 0.4 ? 1 - f * 2.5 : 0 });
  }
  river(p, C, ph, H, W, S);
  if (o.ledge) outcrop(p, C, ph, H, W, S);
  sheet(p, C, ph, H, W, S);
  curl(p, C, ph, H, W, S);
  foam(p, C, t, ph, W, S);
  mist(p, C, t, S, 5, 21);
  // glints wink on the falling water and in the spray
  cycle(t, D, 12, S + 50, (g) => g.range(0.2, 0.4), (age, life, r) => {
    const k = Math.sin((Math.PI * age) / life), low = r.next() < 0.45, d = low ? H - r.range(4, 16) : r.range(12, H - 16);
    const x = low ? r.range(-W - 10, W + 10) : r.range(-0.8, 0.8) * halfW(W, d, H), y = -H + d - (age / life) * (low ? 6 : -10);
    p.px(x, y, WHITE);
    if (k > 0.55) for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) p.px(x + dx, y + dy, C[6]);
    if (k > 0.85 && r.next() < 0.5) for (const [dx, dy] of [[2, 0], [-2, 0], [0, 2], [0, -2]]) p.px(x + dx, y + dy, C[5]);
    p.glow(x, y, 5, C[5], 0.35 * k);
  });
  // fine spray hangs in the air off the foot, drifting up and out
  cycle(t, D, 34, S + 51, (g) => g.range(0.9, 1.6), (age, life, r) => {
    const k = age / life, side = r.sign(), x = side * (r.range(0, W + 6) + k * r.range(6, 22)) + Math.sin(age * 5 + r.range(0, TAU)) * 1.2, y = -r.range(3, 10) - k * r.range(10, 34);
    if (k > 0.7 && r.next() < (k - 0.7) * 3.3) return;
    p.px(x, y, k < 0.4 && r.next() < 0.5 ? WHITE : C[6]);
  });
  // light: down the sheet, a pool of it where the water lands, on the water around
  p.glowLine(0, -H + 6, 0, -8, 26, C[4], 0.12);
  p.glow(0, -5, 40, C[5], 0.32 + 0.05 * Math.sin(T * 2));
  p.glow(0, 4, 50, C[3], 0.14);
}

// The lip's crescent (a thick arc, white on its outer rim, cooling to deep blue underneath, with light along it)
// follows Sprite Fusion's open-source slash (https://www.spritefusion.com/pixel-art-vfx/slash),
// MIT License, Copyright (c) 2026 Hugo Duprez.
import { Particles, Lights, P, Rng, fit, sparkle, clamp, smooth, ease, noise, noise2, TAU, WHITE } from "../../core/index.js";
import { WATER, Drops, Ripples, Mist, billow } from "./_lib.js";

export const meta = {
  name: "Wave crash",
  desc: "A swell rolls in and steepens, its lip throws forward and curls over a dark barrel, then crashes into a burst of white foam and spray that surges on and fades to lace.",
  tags: ["water", "wave", "crash", "surf", "foam", "spray", "one-shot"],
  size: [224, 104],
  origin: [112, 86],
  duration: 3.2,
  loop: false,
  fps: 30,
  bg: "ground",
  options: { palette: WATER, seed: 6 },
};

const SY = 0.22, G = 820, CRASH = 1.2, LIP0 = 0.62, EDGE = 110;

// the swell: where its crest is, how tall, how steep its face, as it rolls in, crashes and runs on as whitewater
const crestX = (t) => (t < CRASH ? -80 + 72 * ease.inOutSine(t / CRASH) : -8 + 30 * ease.outCubic(clamp((t - CRASH) / 1.4)));
const crestH = (t) => (t < CRASH ? 5 + 33 * ease.inOutSine(clamp(t / (CRASH * 0.92))) : 38 * (1 - ease.outCubic(clamp((t - CRASH) / 0.45))) + 5 * (1 - smooth(CRASH, CRASH + 1.6, t)));
const faceW = (t) => (t < CRASH ? 24 - 16 * smooth(0.3, CRASH, t) : 8 + 14 * smooth(CRASH, CRASH + 0.6, t));
// the lip: thrown forward off the crest and falling, until its tip hits the water at CRASH
const lipK = (t) => clamp((t - LIP0) / (CRASH - LIP0));

export function create(o) {
  const C = fit(o.palette, 8), R = new Rng(o.seed), S = o.seed;
  const ps = new Particles({ rng: R }), mist = new Mist(), lights = new Lights(), rings = new Ripples({ sy: SY }), puffs = [], plinks = [];
  const drops = new Drops({
    sy: SY,
    g: G,
    onLand: (d) => {
      rings.add(d.x, d.z, 0.6, 2 + d.s * 1.8, 0.3 + d.s * 0.1, { n: 1, k: 0.9, hot: 0.05 });
      plinks.push({ x: d.x, y: d.z * SY, age: 0 });
    },
  });
  let t = 0, crashed = false;
  const height = (x, tt) => {
    const xc = crestX(tt), A = crestH(tt), dx = x - xc;
    return A * Math.exp(-((dx / (dx < 0 ? 30 : faceW(tt))) ** 2));
  };
  // a point on the lip at s (0 at the crest, 1 at its tip), and its thickness there
  const lip = (s, tt) => {
    const k = lipK(tt), xc = crestX(tt), A = crestH(tt);
    return [xc + 1 + s * 30 * Math.pow(k, 0.8), -A - 4 * s * (1 - s) * (1 + 4 * k) + s * s * A * ease.inQuad(k) * 0.98, (11 - 8.5 * s) * (0.5 + 0.5 * k)];
  };
  const puff = (x, y, vx, vy, r0, r1, life, delay = 0) => puffs.push({ x, y, vx, vy, r0, r1, life, max: life, delay });

  // the swell's body, column by column: deep blue down its back and base with wind lines, a lit rim along its
  // surface, white water at the crest, a lit window high on its face where the light comes through, and streaks of
  // foam drawn up the face
  function body(p, fade) {
    const xc = crestX(t), A = crestH(t);
    for (let X = -EDGE; X < EDGE; X++) {
      const x = X + 0.5, h = height(x, t), edge = 1 - smooth(EDGE - 24, EDGE, Math.abs(x));
      if (h < 0.6 || edge <= 0) continue;
      const face = x > xc, near = Math.exp(-(((x - xc) / 9) ** 2)), a = fade * edge * 1.4;
      for (let Y = Math.floor(-h); Y < 0; Y++) {
        const y = Y + 0.5, u = (y + h) / h, depth = y + h;
        let c;
        if (depth < 1) c = near > 0.5 && A > 14 && noise(x * 0.6 + t * 9, S) > -0.35 ? WHITE : face ? C[5] : C[6];
        else if (depth < 2.4 && near > 0.35 && A > 14) c = noise2(x * 0.5, y * 0.5 + t * 6, S + 1) > -0.1 ? WHITE : C[6];
        else {
          // face and back shade differently; blend the two across the crest so there's no seam
          const win = near * (1 - u) * 1.6, up = noise2((x * 0.9 - y * 0.35) * 0.8, y * 0.12 + t * 5, S + 2), wind = noise2(x * 0.18 - t * 2, y * 0.9, S + 3);
          const fi = up > 0.55 && u < 0.85 ? 6 : win > 0.8 ? 5 : win > 0.45 || up > 0.3 ? 4 : win > 0.2 || up > 0.05 ? 3 : u < 0.6 ? 2 : 1;
          const bi = u < 0.14 ? 4 : wind > 0.55 ? 4 : wind > 0.25 || u < 0.32 ? 3 : u < 0.7 ? 2 : 1;
          c = C[Math.round(bi + (fi - bi) * smooth(xc - 5, xc + 5, x))];
        }
        p.dot(X, Y, c, a);
      }
    }
  }

  // the lip: a thick arc thrown off the crest, white along its outer edge, tinted through, dark underneath
  function curl(p) {
    const k = lipK(t);
    if (k <= 0 || t >= CRASH) return;
    const cells = new Map();
    for (let s = 0; s <= 1; s += 0.012) {
      const [x, y, w] = lip(s, t), [x2, y2] = lip(Math.min(1, s + 0.012), t), tx = x2 - x, ty = y2 - y, l = Math.hypot(tx, ty) || 1, nx = ty / l, ny = -tx / l;
      for (let q = 0; q <= 1; q += 0.5 / Math.max(1, w)) {
        const px = x + nx * (q - 0.5) * w, py = y + ny * (q - 0.5) * w, key = Math.floor(py) * 1024 + Math.floor(px);
        // q 0 is the outer (upper) rim, 1 the underside
        const c = q < 0.18 ? WHITE : q < 0.36 ? (s > 0.8 ? WHITE : C[6]) : q < 0.56 ? C[5] : q < 0.76 ? C[4] : C[3];
        const cur = cells.get(key);
        if (!cur || q < cur.q) cells.set(key, { x: px, y: py, c, q });
      }
    }
    for (const c of cells.values()) p.px(c.x, c.y, c.c);
    for (let s = 0; s <= 1; s += 0.125) {
      const [x, y, w] = lip(s, t);
      p.glow(x, y, 6 + w, C[5], 0.24 * k);
    }
    // the tip glints as it throws
    const [tx, ty] = lip(1, t), g = Math.sin(Math.PI * clamp((k - 0.55) / 0.45));
    if (g > 0.05) sparkle(p, tx, ty, 6 * g, C[6], C[5], 0.5 * g);
    // light caught under the barrel
    const [bx, by] = lip(0.6, t);
    p.glow(bx - 3, by + 8, 16, C[4], 0.25 * k);
  }

  // the sea it rolls on: a lit line along the surface, dark water under it, glints sliding along
  function sea(p, fade) {
    for (let X = -EDGE; X < EDGE; X++) {
      const x = X + 0.5, edge = 1 - smooth(EDGE - 30, EDGE, Math.abs(x)), a = fade * edge;
      if (a <= 0.02) continue;
      const g = noise(x * 0.3 - t * 3, S + 4);
      p.dot(X, 0, g > 0.55 ? C[6] : C[4], a * 1.2);
      p.blend(x, 1.5, C[2], 0.6 * a);
      p.blend(x, 2.5, C[1], 0.45 * a);
    }
  }

  return {
    update(dt) {
      t += dt;
      const k = lipK(t);
      // wind tears spray off the crest; the lip's tip sheds drops as it throws
      if (t < CRASH && crestH(t) > 14 && R.chance(0.5)) {
        const xc = crestX(t), A = crestH(t);
        ps.spawn(P.FLAKE, xc + R.range(-4, 3), -A - R.range(0, 2), -R.range(20, 60), -R.range(10, 40), R.range(0.5, 0.9), R.chance(0.5) ? WHITE : C[6], R.range(0.6, 1.3));
      }
      if (k > 0.3 && t < CRASH && R.chance(0.35)) {
        const [x, y] = lip(1, t);
        drops.add({ x, z: R.range(-3, 3), h: -y, vx: R.range(30, 90), vz: R.range(-10, 10), vh: R.range(-20, 40), s: R.chance(0.3) ? 2 : 1 });
      }
      if (!crashed && t >= CRASH) {
        crashed = true;
        const [X0] = lip(1, CRASH - 1e-3);
        lights.add(X0, -20, 56, C[5], 0.8, 0.55);
        lights.add(X0, -4, 22, WHITE, 0.6, 0.1);
        for (let i = 0; i < 46; i++) {
          const a = R.range(-0.9, 0.6) * Math.PI, v = R.range(30, 120);
          drops.add({ x: X0 + R.range(-6, 6), z: R.range(-4, 4), h: R.range(2, 8), vx: Math.cos(a) * v * 0.85 + 18, vz: Math.sin(a) * v * 0.5, vh: R.range(120, 320), s: R.chance(0.15) ? 3 : R.chance(0.35) ? 2 : 1, delay: R.range(0, 0.1) });
        }
        // the spit: a plume shot straight up where the lip lands
        for (let i = 0; i < 14; i++) drops.add({ x: X0 + R.range(-3, 3), z: R.range(-2, 2), h: R.range(2, 6), vx: R.range(-15, 25), vz: R.range(-8, 8), vh: R.range(220, 300), s: R.chance(0.3) ? 2 : 1, delay: R.range(0.04, 0.16) });
        for (let i = 0; i < 34; i++) puff(X0 + R.range(-12, 10), -R.range(2, 12), R.range(-40, 130), -R.range(30, 150), R.range(1, 2), R.range(1.8, 4.2), R.range(0.4, 0.95), R.range(0, 0.14));
        // fine spray hangs in the air over the burst
        for (let i = 0; i < 34; i++) {
          const a = R.range(-Math.PI * 0.95, -Math.PI * 0.05), v = R.range(40, 160);
          ps.spawn(P.FLAKE, X0 + R.range(-8, 8), -R.range(4, 14), Math.cos(a) * v + 25, Math.sin(a) * v, R.range(0.6, 1.3), R.chance(0.5) ? WHITE : C[6], R.range(0.6, 1.4), R.range(0, 0.1));
        }
        for (let i = 0; i < 12; i++) mist.add(X0 + R.range(-10, 14), -R.range(3, 16), R.range(-20, 70), -R.range(6, 24), 3, R.range(9, 15), R.range(1.1, 1.7), R.chance(0.5) ? C[6] : WHITE, 0.26, R.range(0, 0.2));
        for (let i = 0; i < 10; i++) ps.spawn(P.STAR, X0 + R.range(-20, 24), -R.range(6, 40), 0, -5, R.range(0.3, 0.6), C[6], R.range(1, 2.4), R.range(0.05, 0.4));
        rings.add(X0, 0, 6, 40, 1.2, { n: 2, gap: 3, k: 1.1, hot: 0.12 });
      }
      // the whitewater surges on, boiling up foam at its front, then calms
      if (crashed && t < CRASH + 1.1 && R.chance(0.45 * (1 - (t - CRASH) / 1.1))) {
        const x = crestX(t) + R.range(-6, 14);
        puff(x, -R.range(1, 4), R.range(10, 40), -R.range(10, 40), R.range(0.9, 1.8), R.range(1.8, 3.6), R.range(0.4, 0.8));
      }
      if (crashed && t < CRASH + 0.8 && R.chance(0.12)) mist.add(crestX(t) + R.range(-8, 8), -R.range(2, 6), R.range(10, 40), -R.range(3, 10), 3, R.range(7, 11), R.range(0.8, 1.1), C[6], 0.2);
      for (let i = puffs.length - 1; i >= 0; i--) {
        const f = puffs[i];
        if (f.delay > 0) {
          f.delay -= dt;
          continue;
        }
        if ((f.life -= dt) <= 0) {
          puffs.splice(i, 1);
          continue;
        }
        f.vx -= f.vx * 2.5 * dt;
        f.vy += (160 - f.vy * 2.5) * dt;
        f.x += f.vx * dt;
        f.y = Math.min(f.y + f.vy * dt, -1);
      }
      for (let i = plinks.length - 1; i >= 0; i--) if ((plinks[i].age += dt) > 0.12) plinks.splice(i, 1);
      drops.update(dt);
      rings.update(dt);
      mist.update(dt);
      ps.update(dt);
      lights.update(dt);
    },
    drawBack(p) {
      const fade = smooth(0, 0.25, t) * (1 - smooth(meta.duration - 0.7, meta.duration - 0.1, t));
      sea(p, fade);
      rings.draw(p, C, -1);
      drops.draw(p, C, "back");
    },
    draw(p) {
      const fade = smooth(0, 0.25, t) * (1 - smooth(meta.duration - 0.7, meta.duration - 0.1, t));
      body(p, fade);
      curl(p);
      rings.draw(p, C, 1);
      // lace left on the water behind the surge, thinning out
      if (crashed) {
        const k = 1 - smooth(CRASH + 0.4, meta.duration - 0.15, t), x0 = -20, x1 = crestX(t) + 10;
        for (let X = Math.floor(x0); X < x1; X++) {
          const x = X + 0.5, n = 1 - Math.abs(noise2(x * 0.35, t * 0.8, S + 7)) * 4;
          if (n > 1.15 - k * 1.1) p.px(X, 0, n > 1.4 - k ? WHITE : C[6]);
          if (n > 1.4 - k * 0.9) p.px(X, 1, C[5]);
        }
      }
      for (const f of puffs) {
        if (f.delay > 0) continue;
        const g = 1 - f.life / f.max, r = (f.r0 + (f.r1 - f.r0) * ease.outCubic(g)) * (1 - smooth(0.7, 1, g));
        if (r > 0.6) billow(p, f.x, f.y, r, C);
      }
      for (const q of plinks) {
        if (q.age < 0.06) p.px(q.x, q.y, WHITE);
        p.glow(q.x, q.y, 4, C[5], 0.25 * (1 - q.age / 0.12));
      }
      drops.draw(p, C, "front");
      // the crash: a white burst where the lip lands
      const f = (t - CRASH) / 0.08;
      if (f >= 0 && f < 1) {
        const [X0] = lip(1, CRASH - 1e-3);
        p.circle(X0, -3, 8 * (1 - f * 0.4), WHITE);
        p.ellipse(X0, 0, 14, 2.6, (d) => (d < 0.6 ? WHITE : C[6]));
      }
      ps.draw(p);
      mist.draw(p, C[5]);
      lights.draw(p);
      // light: the crest catches it while it stands, the whitewater after
      if (t < CRASH) {
        p.glow(crestX(t) + 4, -crestH(t) + 2, 26, C[4], 0.22 * smooth(0.2, CRASH, t));
        p.glowLine(crestX(t) - 26, -crestH(t) * 0.45, crestX(t), -crestH(t), 10, C[5], 0.14 * smooth(0.2, CRASH, t));
      }
      else p.glow(crestX(t), -10, 34, C[4], 0.26 * (1 - smooth(CRASH, meta.duration - 0.3, t)));
    },
  };
}

// The swirl's texture (streaks laid along a differentially wound flow, light on the brightest pixels) is adapted
// from Sprite Fusion's open-source black hole (https://www.spritefusion.com/pixel-art-vfx/black-hole), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, cycle, clamp, smooth, TAU, WHITE } from "../../core/index.js";
import { WATER } from "./_lib.js";

export const meta = {
  name: "Whirlpool",
  desc: "Seen from above, dark water winds into a vortex: foam arms spiral in, darkening as they're drawn down into a deep eye with a lit far rim, flecks of foam circling in after them.",
  tags: ["water", "whirlpool", "vortex", "maelstrom", "swirl", "top-down", "loop"],
  size: [128, 84],
  origin: [64, 42],
  duration: 3,
  loop: true,
  fps: 30,
  bg: "dark",
  options: { palette: WATER, seed: 5 },
};

const D = meta.duration, R = 60, SY = 0.6, K = 2.4, EYE = 0.16;

// the flow at radius rho (0 eye, 1 rim), angle th: thin streaks of foam laid along a log spiral that turns once a
// loop (a turning log spiral reads as water drawn inward), dashed and brightest where two sets of streaks cross
function foam(rho, th, ph) {
  const s = Math.log(Math.max(rho, 0.02)), a = th + K * s + ph * TAU, b = th + K * 1.35 * s + ph * TAU * 2;
  const one = Math.pow(0.5 + 0.5 * Math.cos(7 * a + 0.9 * Math.sin(3 * a + s * 4)), 26);
  const two = Math.pow(0.5 + 0.5 * Math.cos(11 * b + 1.3), 34) * 0.7;
  // finer streaks crowd in near the eye, where the water runs fastest
  const three = Math.pow(0.5 + 0.5 * Math.cos(17 * (th + K * 0.8 * s + ph * TAU * 3)), 30) * 0.8 * Math.max(0, 1 - (rho - EYE) * 2.2);
  const dash = 0.55 + 0.45 * Math.sin(s * 22 - ph * TAU * 4 + a * 2);
  return (one + two + three) * dash;
}

export function draw(p, t, o) {
  const C = fit(o.palette, 8), ph = t / D, ry = R * SY;
  p.shade(-R, -ry, R, ry, (x, y, out) => {
    const dx = x / R, dy = y / ry, rho = Math.hypot(dx, dy);
    if (rho > 1) return;
    const th = Math.atan2(dy, dx);
    // the eye: a hole down into the dark, its far wall lit, a ring of foam racing round its lip
    if (rho < EYE) {
      const far = -dy / rho;
      // the far wall of the funnel, lit, falling off into the dark below the lip on the near side
      const wall = (rho / EYE - 0.35) / 0.65;
      if (far > 0) out.c = wall > 0.8 ? (far > 0.6 ? C[5] : C[4]) : wall > 0.45 ? C[3] : wall > 0.15 ? C[2] : C[0];
      else out.c = wall > 0.85 && far > -0.5 ? C[2] : C[0];
      return;
    }
    const k = (rho - EYE) / (1 - EYE), fade = 1 - smooth(0.62, 1, k);
    // dark see-through water, darker toward the eye, a faint sheen mid-way
    p.blend(x, y, k < 0.25 ? C[0] : C[1], (0.75 - 0.25 * k) * (1 - smooth(0.8, 1, k)));
    if (k > 0.3 && k < 0.8) p.blend(x, y, C[2], 0.18 * Math.sin(Math.PI * (k - 0.3) / 0.5));
    // the foam ring round the eye
    if (k < 0.035) {
      const g = 0.5 + 0.5 * Math.cos(th * 9 - ph * TAU * 6);
      out.c = g > 0.7 ? WHITE : g > 0.3 ? C[6] : C[4];
      return;
    }
    const I = foam(rho, th, ph) * fade * Math.min(1, (k - 0.08) * 4) * (0.45 + 0.55 * Math.sin(Math.PI * Math.min(1, k * 1.25)));
    if (I > 0.12) {
      out.c = I > 0.75 ? WHITE : I > 0.45 ? C[6] : I > 0.25 ? C[5] : C[4];
      if (I > 0.25) (out.l = C[5]), (out.k = 0.08 + 0.14 * Math.min(1, I));
    }
  });
  // flecks of foam drawn round and in along the arms, each a short streak along its path
  cycle(t, D, 30, o.seed, (g) => g.range(1.2, 2.2), (age, life, r) => {
    const u = age / life, rho = 0.8 - 0.62 * u * u, a0 = r.range(0, TAU), th = a0 - K * Math.log(rho);
    const ang = th - age * (1.5 + 2.2 / rho), x = Math.cos(ang) * rho * R, y = Math.sin(ang) * rho * ry;
    const ang2 = ang + 0.12 / rho, x2 = Math.cos(ang2) * rho * R, y2 = Math.sin(ang2) * rho * ry;
    if (u > 0.85 && r.next() < (u - 0.85) * 6) return;
    p.line(x2, y2, x, y, u < 0.2 ? C[5] : u < 0.6 ? WHITE : C[6]);
  });
  // glints winking on the foam
  cycle(t, D, 8, o.seed + 3, (g) => g.range(0.25, 0.45), (age, life, r) => {
    const rho = r.range(0.35, 0.8), th = r.range(0, TAU) - age * 2.5, k = Math.sin((Math.PI * age) / life);
    const x = Math.cos(th) * rho * R, y = Math.sin(th) * rho * ry;
    if (foam(rho, th, ph) < 0.35) return;
    p.px(x, y, WHITE);
