const D = 10, FLOOR = 1;
const gust = (t) => 22 * Math.sin((TAU * t) / D + 0.4) + 7 * Math.sin((TAU * 2 * t) / D - 1);

export function drawBack(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 6);
