    const hw = 0.55 * Math.sqrt(1 - u * u) * (1 + 0.35 * u);
    if (Math.abs(v) > hw || (u > 0.7 && Math.abs(v) < 0.12)) return;
    out.c = u > 0.45 && v < 0.1 ? tip : u < -0.45 ? face[0] : v < 0 ? face[2] : face[1];
    out.a = a;
  });
}

// a whole blossom: five petals round a gold heart, spinning slowly as it sinks
function blossoms(q, t, S, C) {
  trips(t, D, 7, S * 31, 1, 1, (u, k, m, i) => {
    const R = (c) => rand(S * 31, i, c), y = -190 + (FLOOR + 2 + 190) * Math.min(1, u / 0.9), born = t - u * D;
    if (u > 0.9) return;
    const x = -190 + R(1) * 330 + 14 * u * D * 0.1 + (gust(t) - gust(born)) + 6 * Math.sin(u * TAU * 2 + R(2) * 6), rot = R(3) * TAU + u * D * (R(4) - 0.5) * 2;
    const r = 3.6 + R(5) * 1.2;
    for (let p = 0; p < 5; p++) {
      const an = rot + (p * TAU) / 5;
      petal(q, x + Math.cos(an) * r * 0.75, y + Math.sin(an) * r * 0.75, r * 0.7, an, 1, C, 1);
    }
    q.px(x, y, hex("#ffe08a"));
    q.glow(x, y, 8, C[4], 0.2);
  });
}

// petals already fallen, scattered along the floor; they never move, so they're shaded once and replayed
const SCATTER = new Map();
function scatter(q, S, C) {
  const key = S + C.join();
  let px = SCATTER.get(key);
  if (!px) {
    px = [];
    const rec = {
      shade(x0, y0, x1, y1, fn) {
        const o = { c: 0, a: 1 };
        for (let y = Math.floor(y0); y <= Math.ceil(y1); y++)
          for (let x = Math.floor(x0); x <= Math.ceil(x1); x++) {
            o.c = 0;
            const c = fn(x + 0.5, y + 0.5, o) || o.c;
            if (c) px.push(x + 0.5, y + 0.5, c, o.a);
          }
      },
    };
    for (let i = 0; i < 46; i++) petal(rec, -164 + rand(S, i, 71) * 328, FLOOR + Math.floor(rand(S, i, 72) * 3) * 2, 2.6 + rand(S, i, 73), (rand(S, i, 74) - 0.5) * 1.2, 0.5, C, 1);
    SCATTER.set(key, px);
  }
  for (let i = 0; i < px.length; i += 4) q.dot(px[i], px[i + 1], px[i + 2], px[i + 3]);
}

// Banded volumes with a lit crest (light on the top edge, tones stepping down into the body, Bayer at the steps)
// after Sprite Fusion's open-source fog (https://www.spritefusion.com/pixel-art-vfx/fog), MIT License,
// Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, rand, wrap, mix, TAU, WHITE } from "../../core/index.js";
import { clip, box, bayer } from "./_lib.js";

export const meta = {
  name: "Clouds",
  desc: "Layers of clouds drift past a bright moon at night: silver-lit tops, dark bellies, edges that flare where they cross the moon, forming and thinning as they go.",
  tags: ["weather", "clouds", "moon", "night", "sky", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 180],
  duration: 12,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#0c0c18", "#16172a", "#232540", "#363a5a", "#545a80", "#8088ae", "#bcc4e2", "#f2f4ff"],
    seed: 7,
  },
};

const D = 12, MX = 92, MY = -128, MR = 12;
// far to near: how many clouds, how wide, how tall their puffs, how high, drift speed, how long they live,
// tones [belly, body, upper, top], how see-through
const LAYERS = [
  { n: 7, w: [40, 70], h: [6, 11], y: [-150, -110], v: 3, life: [8, 11], tone: [2, 3, 4, 5], alpha: 0.7 },
  { n: 6, w: [60, 100], h: [9, 15], y: [-120, -70], v: 6, life: [8, 11], tone: [1, 2, 4, 6], alpha: 0.88 },
  { n: 5, w: [90, 140], h: [12, 20], y: [-80, -30], v: 10, life: [9, 12], tone: [1, 2, 3, 6], alpha: 1 },
];

export function draw(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 8);
  moon(q, C);
  LAYERS.forEach((L, j) => {
    for (let i = 0; i < L.n; i++) cloud(q, t, S, C, L, j, i);
  });
  // the moon's light over everything: a halo, brightest close in, catching any cloud that passes
  q.glow(MX, MY, 110, C[4], 0.14);
  q.glow(MX, MY, 40, C[5], 0.25);
  q.glow(MX, MY, 18, C[6], 0.3);
}

function moon(q, C) {
  q.shade(MX - MR - 1, MY - MR - 1, MX + MR + 1, MY + MR + 1, (x, y, out) => {
    const dx = x - MX, dy = y - MY, d = Math.hypot(dx, dy) / MR;
    if (d > 1) return;
    // a pale disc with darker seas, a bright limb on the lit side
    const sea = (dx + 4) ** 2 + (dy + 2) ** 2 < 14 || (dx - 3) ** 2 + (dy - 4) ** 2 < 9 || (dx - 5) ** 2 + (dy + 5) ** 2 < 4;
    out.c = d > 0.86 ? (dx + dy < 0 ? C[6] : WHITE) : sea ? C[5] : d < 0.5 && dx + dy < 0 ? WHITE : C[7];
  });
}

// one cloud: born once a loop, it swells into shape, drifts, and thins away. Its outline is a row of puffs on a
// flat base; shading steps down from a silver top to a dark belly, and edges near the moon flare
function cloud(q, t, S, C, L, j, i) {
  const R = (k) => rand(S, j, i, k), life = L.life[0] + R(1) * (L.life[1] - L.life[0]), age = wrap(t - R(2) * D, D);
  if (age >= life) return;
  const u = age / life, grow = Math.min(1, u * 4) * Math.min(1, (1 - u) * 4), w = (L.w[0] + R(3) * (L.w[1] - L.w[0])) * (0.6 + 0.4 * grow);
  const x0 = -200 + R(4) * 330 + L.v * age, base = L.y[0] + R(5) * (L.y[1] - L.y[0]), H = (L.h[0] + R(6) * (L.h[1] - L.h[0])) * grow;
  if (H < 1.5) return;
  // a row of puffs along the base, and a tier of bigger ones heaped in the middle
  const n = 4 + Math.floor(R(7) * 4), puffs = [];
  for (let k = 0; k < n; k++) {
    const f = (k + 0.5) / n, r = H * (0.5 + 0.35 * Math.sin(Math.PI * f)) * (0.75 + 0.5 * R(10 + k)) * (1 + 0.06 * Math.sin((TAU * t) / D + k + i));
    puffs.push([x0 + w * (f - 0.5) + (R(20 + k) - 0.5) * 6, base - r * 0.3 - R(30 + k) * H * 0.15, r]);
  }
  for (let k = 0; k < 1 + Math.floor(R(8) * 3); k++) {
    const f = 0.3 + R(40 + k) * 0.4, r = H * (0.75 + 0.35 * R(50 + k)) * (1 + 0.05 * Math.sin((TAU * t) / D + k * 2 + i));
    puffs.push([x0 + w * (f - 0.5), base - H * 0.55 - r * 0.2, r]);
  }
  const x1 = x0 - w / 2 - H, x2 = x0 + w / 2 + H, B = box(meta);
  for (let x = Math.max(B.x0, Math.floor(x1)); x <= Math.min(B.x1 - 1, Math.ceil(x2)); x++) {
    const cx = x + 0.5;
    let top = Infinity, top2 = Infinity;
    for (const [px, py, r] of puffs) {
      const dx = cx - px;
      if (dx * dx >= r * r) continue;
      const y = py - Math.sqrt(r * r - dx * dx);
      if (y < top) (top2 = top), (top = y);
      else if (y < top2) top2 = y;
    }
    if (top === Infinity) continue;
    // a belly that's nearly flat, lifting at the ends and rippling a little
    const end = Math.min(cx - x1, x2 - cx) / H, bot = base + 1.5 + Math.sin(cx * 0.21 + i) * 0.8 - (end < 1 ? (1 - end) * 4 : 0);
    if (bot <= top) continue;
    const h = bot - top, inner = top2 - top > 2.5 && top2 < bot - 2 ? Math.floor(top2) : -999;
    for (let y = Math.floor(top); y < bot; y++) {
      const d = y + 0.5 - top, v = d / h, th = bayer(x, y) * 0.12, md = Math.hypot(cx - MX, y - MY);
      let c = d < 1 ? L.tone[3] : v < 0.25 + th ? L.tone[2] : v < 0.62 + th ? L.tone[1] : L.tone[0];
      // the top of a lower puff shows inside the body as a lit line: the cloud's lobes
      if (y === inner) c = Math.max(c, L.tone[2]);
      if (bot - y - 0.5 < 1 && v > 0.5) c = Math.max(0, L.tone[0] - 1);
      // the silver lining: near the moon the edges light right up
      if (md < 46 && (d < 2 || y === inner || v < 0.3)) c = Math.min(7, c + (md < 24 ? 2 : 1));
      const a = L.alpha * Math.min(1, grow * 1.5);
      if (a >= 1) q.px(x, y, C[c]);
      else q.blend(x, y, C[c], a);
      if (d < 1 && md < 46) q.light(x, y, C[6], 0.35 * (1 - md / 46));
    }
  }
}

// The falling leaf (a pendulum swing that speeds through the bottom of each arc, a tilt that follows it, a flip
// by squashing across, a rest on the ground, a litter of fallen leaves) is adapted from Sprite Fusion's
// open-source falling leaves (https://www.spritefusion.com/pixel-art-vfx/falling-leaves), MIT License,
// Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, rand, wrap, mix, TAU, hex } from "../../core/index.js";
import { clip, rows, trips } from "./_lib.js";

export const meta = {
  name: "Falling leaves",
  desc: "Autumn leaves swing down through the air, tilting and flipping to show their pale backs, ride a gust, land flat in the litter and fade.",
  tags: ["weather", "leaves", "autumn", "fall", "wind", "nature", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 170],
  duration: 10,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#4a1d0c", "#8a3a14", "#c8621e", "#f0982e", "#ffcf72", "#fff0c4"],
    reds: ["#40101a", "#7c1c22", "#b8302a", "#e85a3c", "#ff9a72", "#ffd8c4"],
    golds: ["#3e300c", "#7a5c14", "#b8901e", "#e8c23a", "#fff09a", "#fffbe0"],
    seed: 8,
  },
};

const D = 10, FLOOR = 1;
const gust = (t) => 16 * Math.sin((TAU * t) / D - 1.2) + 5 * Math.sin((TAU * 3 * t) / D);
// ∫|cos| from the start of a swing: speeds up through the bottom of each arc, so the drop does too
const Hc = (th) => {
  const k = Math.floor((th + Math.PI / 2) / Math.PI);
  return 2 * k + 1 + Math.sin(th - k * Math.PI);
};

// a leaf's outline in its own frame: u along it (-1 stem .. 1 tip), v across; 0 inside, > 1 outside
const SHAPES = [
  (u, v) => (Math.abs(u) >= 1 ? 9 : (v * v) / (0.36 * (1 - u * u) * (1.15 - 0.3 * u))), // a beech: a long oval, pointed tip
  (u, v) => {
    const r = Math.hypot(u, v * 1.1), a = Math.atan2(v, u);
    return r / (0.62 + 0.38 * Math.abs(Math.cos(2.5 * a)) ** 1.5); // a maple: five lobes
  },
  (u, v) => (Math.abs(u) >= 1 ? 9 : (v * v) / (0.16 * (1 - u * u))), // a willow: long and thin
];

export function drawBack(p, t, o) {
  const q = clip(p, meta), S = o.seed, R3 = ramps(o), C = R3[0];
  // a faint dusk haze, warmer low down, that keeps the sky's stars out of the leaves' way
  const top = hex("#0e0a12"), low = mix(hex("#140c14"), C[0], 0.3);
  rows(p, meta, -170, 9, (y, R) => {
    const k = (y + 170) / 180, c = mix(top, low, k * k);
    R.c.fill(c);
    R.a.fill(0.32 + 0.1 * k);
    R.b.fill(1);
  });
  litter(q, S, R3);
  leaves(q, t, S, R3, false);
}

export function draw(p, t, o) {
  leaves(clip(p, meta), t, o.seed, ramps(o), true);
}

const ramps = (o) => [fit(o.palette, 6), fit(o.reds, 6), fit(o.golds, 6)];

function leaves(q, t, S, R3, front) {
  trips(t, D, 62, S * 19, 2, 3, (u, k, m, i) => {
    const j = wrap(k, m), R = (n) => rand(S * 19, i, j, n), near = R(1) < 0.35;
    if (near !== front) return;
    const dur = D / m, air = 0.72, tf = dur * air, a = Math.min(u * dur, tf), rest = u * dur - tf;
    const w = 1.7 + R(2) * 1.2, ph0 = R(3) * TAU, amp = (near ? 14 : 8) + R(4) * 10, x0 = -180 + R(5) * 340, y0 = -186;
    // the drop speed that lands it on the floor just as its time in the air runs out
    const path = (aa) => 0.45 * aa + (0.9 * (Hc(w * aa + ph0) - Hc(ph0))) / w, vy = (FLOOR - y0) / path(tf);
    const born = t - u * dur, xAt = (aa) => x0 + 7 * aa + Math.sin(w * aa + ph0) * amp + (gust(born + aa) - gust(born)) * (near ? 1 : 0.7);
    const size = (near ? 5.8 : 4.2) + R(6) * 1.6, shape = Math.floor(R(7) * 3), col = R3[Math.floor(R(8) * 3)];
    if (rest > 0) {
      // lying flat in the litter, fading
      const fade = 1 - rest / (dur - tf);
      leaf(q, xAt(tf), FLOOR - 1, size, (R(9) - 0.5) * 0.5, 0.42, shape, col, fade);
      return;
    }
    const x = xAt(a), y = y0 + vy * path(a), tilt = Math.cos(w * a + ph0) * 0.75 + (near ? 0 : 0.3);
    const flip = Math.cos(R(10) * TAU + a * (R(11) < 0.3 ? 5 : 1.2));
    leaf(q, x, y, size, tilt, flip, shape, col, 1);
    // a leaf turned full face to the light catches it for a moment
    if (flip > 0.86) {
      const k = (flip - 0.86) / 0.14, hx = x - Math.cos(tilt) * size * 0.3, hy = y - Math.sin(tilt) * size * 0.3 - 1;
      q.px(hx, hy, col[5]);
      q.glow(hx, hy, 5 + size * 0.5, col[4], 0.22 * k);
    }
  });
}

// draw a leaf: squash it across by `flip` (the sign says which face shows), tilt it, outline it, a midrib down
// the middle, the face lit on one side; the back face is paler and duller
function leaf(q, x, y, size, ang, flip, shape, col, a) {
  // like a card turning: never thinner than a third, and the back shows only past edge-on
  const back = flip < -0.25, fs = 0.35 + 0.65 * Math.abs(flip), c = Math.cos(ang), s = Math.sin(ang);
  const L = size, Wd = size * 0.9, ext = L + 1.5, shapeFn = SHAPES[shape];
  const face = back ? [mix(col[1], hex("#9c8a78"), 0.2), mix(col[2], hex("#c8b49c"), 0.22), mix(col[3], hex("#e0d0b8"), 0.22)] : [col[2], col[3], col[4]];
  const rim = col[0], vein = back ? mix(col[2], hex("#e8dcc8"), 0.5) : col[1];
  q.shade(x - ext, y - ext, x + ext, y + ext, (px, py, out) => {
    const dx = px - x, dy = py - y, lu = (dx * c + dy * s) / L, lv = (-dx * s + dy * c) / (Wd * fs);
    const d = shapeFn(lu, lv);
    if (lu < -1.25 || lu > 1.1) return;
    // the stem pokes out past the base
    if (lu < -0.92 && Math.abs(lv * Wd * fs) < 0.5) return void ((out.c = rim), (out.a = a));
    if (d > 1.32) return;
    out.a = a;
    if (d > 1) out.c = rim;
    else if (Math.abs(lv * Wd * fs) < 0.45 && lu > -0.9 && lu < 0.75) out.c = vein;
    else out.c = lv < -0.15 ? face[2] : lv < 0.35 ? face[1] : face[0];
  });
}

// fallen leaves lying in a band along the floor, overlapping. They never move, so they're shaded once per seed
// and palette and the pixels replayed
const LITTER = new Map();
function litter(q, S, R3) {
  const key = S + R3.flat().join();
  let px = LITTER.get(key);
  if (!px) {
    px = [];
    const rec = {
      shade(x0, y0, x1, y1, fn) {
        const o = { c: 0, a: 1 };
        for (let y = Math.floor(y0); y <= Math.ceil(y1); y++)
          for (let x = Math.floor(x0); x <= Math.ceil(x1); x++) {
            o.c = 0;
            o.a = 1;
            const c = fn(x + 0.5, y + 0.5, o) || o.c;
            if (c) px.push(x + 0.5, y + 0.5, c, o.a);
          }
      },
    };
    for (let i = 0; i < 64; i++) {
      const x = -164 + rand(S, i, 91) * 328, y = FLOOR - 2 + Math.floor(rand(S, i, 92) * 4) * 2, col = R3[Math.floor(rand(S, i, 93) * 3)];
      leaf(rec, x, y, 3.6 + rand(S, i, 94) * 1.8, (rand(S, i, 95) - 0.5) * 0.7, 0.45 + rand(S, i, 96) * 0.25, Math.floor(rand(S, i, 97) * 3), col.map((c) => mix(c, col[0], 0.12)), 1);
    }
    LITTER.set(key, px);
  }
  for (let i = 0; i < px.length; i += 4) q.dot(px[i], px[i + 1], px[i + 2], px[i + 3]);
}

// The firefly (a wandering point that glows up and fades on its own rhythm, close ones drawn with a dark body,
// beating wings and a lantern that throws a big soft light, grass blades swaying underneath) is adapted from
// Sprite Fusion's open-source fireflies (https://www.spritefusion.com/pixel-art-vfx/fireflies), MIT License,
// Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, rand, mix, TAU, WHITE, loopNoise } from "../../core/index.js";
import { clip, rows } from "./_lib.js";

export const meta = {
  name: "Fireflies",
  desc: "Fireflies wander over a meadow at night, each glowing up and fading on its own rhythm, trailing light and lighting the grass tips beneath them.",
  tags: ["weather", "fireflies", "night", "glow", "meadow", "nature", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 170],
  duration: 12,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#2a3a10", "#5a7a1a", "#9ad02a", "#d6ff5a", "#f4ffb8", "#ffffff"],
    grass: ["#070f0b", "#0c1a12", "#13281a", "#1d3a24", "#2b5232", "#3f6e40"],
    seed: 2,
  },
};

const D = 12, cyc = (t, n, ph = 0) => (TAU * n * t) / D + ph;

// a firefly's path and glow, both whole cycles a loop. depth 0 far .. 2 near
function fly(S, i, t) {
  const R = (n) => rand(S, i, n), depth = i < 14 ? 0 : i < 26 ? 1 : 2, k = [0.5, 0.8, 1][depth];
  const cx = -150 + R(1) * 300, cy = -16 - R(2) * (depth === 2 ? 70 : 130);
  const ax = (14 + R(3) * 26) * k, ay = (8 + R(4) * 14) * k, n1 = 1 + Math.floor(R(5) * 2), n2 = 1 + Math.floor(R(6) * 3);
  const pos = (tt) => [
    cx + ax * Math.sin(cyc(tt, n1, R(7) * TAU)) + 10 * k * loopNoise(tt / D, 1.5, i * 3),
    cy + ay * Math.sin(cyc(tt, n2, R(8) * TAU)) + 6 * k * loopNoise(tt / D, 1.5, i * 3 + 1),
  ];
  // its rhythm: a quick rise, a hold, a slow fade, dark; some flash twice
  const per = D / (3 + Math.floor(R(9) * 4)), u = (((t / per + R(10)) % 1) + 1) % 1, two = R(11) < 0.35;
  const pulse = (v) => (v < 0.06 ? v / 0.06 : v < 0.14 ? 1 : v < 0.4 ? 1 - (v - 0.14) / 0.26 : 0);
  const glow = Math.max(pulse(u), two ? pulse(u - 0.22) * 0.8 : 0);
  return { pos, depth, glow, R };
}

export function drawBack(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 6), G = fit(o.grass, 6);
  // a cool night haze, so the sky's stars don't read as fireflies
  rows(p, meta, -170, 9, (y, R) => {
    const k = (y + 170) / 180;
    R.c.fill(mix(G[0], G[1], k));
    R.a.fill(0.48 + 0.14 * k);
    R.b.fill(1);
  });
  const flies = Array.from({ length: 32 }, (_, i) => fly(S, i, t));
  grass(q, t, S, G, C, flies, false);
  for (const f of flies) if (f.depth < 2) firefly(q, t, f, C);
}

export function draw(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 6), G = fit(o.grass, 6);
  const flies = Array.from({ length: 32 }, (_, i) => fly(S, i, t));
  grass(q, t, S, G, C, flies, true);
  for (const f of flies) if (f.depth === 2) firefly(q, t, f, C);
}

function firefly(q, t, f, C) {
  const [x, y] = f.pos(t), g = f.glow, X = Math.round(x), Y = Math.round(y);
  if (f.depth === 0) {
    if (g < 0.08) return;
    q.dot(X, Y, g > 0.6 ? C[4] : C[3], Math.min(1, g * 1.6));
    q.glow(x, y, 6, C[2], 0.45 * g);
    return;
  }
  // a short trail of light where it has just been, while it's lit
  if (g > 0.3)
    for (let j = 1; j <= 4; j++) {
      const [tx, ty] = f.pos(t - j * 0.05);
      q.dot(tx, ty, C[2], (g - 0.3) * (1 - j / 5) * 1.3);
    }
  if (f.depth === 1) {
    q.px(X, Y, g > 0.5 ? C[5] : g > 0.15 ? C[3] : C[1]);
    if (g > 0.4) q.px(X, Y + 1, C[2]);
    q.glow(x, y, 9, C[2], 0.5 * g);
    q.glow(x, y, 3, C[4], 0.5 * g);
    return;
  }
  // a close one: a dark body, wings a blur above it, a lantern at its tail; a glint at the peak
  const [nx] = f.pos(t + 0.05), dir = nx >= x ? 1 : -1, beat = Math.floor(t * 30) % 2;
  q.px(X + dir, Y, C[0]);
  q.px(X + dir * 2, Y, C[0]);
  q.dot(X, Y - 1 - beat, mix(C[1], WHITE, 0.4), 0.7);
  q.dot(X + dir, Y - 1 - beat, mix(C[1], WHITE, 0.4), 0.7);
  q.px(X, Y, g > 0.3 ? C[5] : C[1]);
  q.px(X - dir, Y, g > 0.5 ? C[4] : g > 0.15 ? C[3] : C[1]);
  if (g > 0.6) q.px(X - dir, Y + 1, C[3]);
  if (g > 0.7) for (const [dx, dy] of [[0, -2], [0, 2], [-2, 0], [2, 0]]) q.dot(X - dir + dx, Y + dy, C[3], (g - 0.7) * 3);
  q.glow(x, y, 28, C[2], 0.45 * g);
  q.glow(x, y, 10, C[4], 0.5 * g);
  q.glow(x, y, 4, C[5], 0.5 * g);
}

// the meadow: blades in two rows (the front row drawn over the low fireflies), swaying as the breeze rolls
// across, a few seed heads; blade tips near a lit firefly catch its light
function grass(q, t, S, G, C, flies, front) {
  const lit = flies.filter((f) => f.glow > 0.25 && f.depth > 0).map((f) => [...f.pos(t), f.glow]);
  const n = front ? 150 : 230;
  for (let i = 0; i < n; i++) {
    const R = (k) => rand(S * 3 + (front ? 1 : 0), i, k), x = -162 + (i + R(1)) * (324 / n), h = (front ? 4 : 5) + R(2) * (front ? 8 : 11) + (R(3) < 0.1 ? 6 : 0);
    const base = (front ? 9 : 2) - R(4) * 3, sway = (1.2 + R(5)) * Math.sin(cyc(t, 2, -x * 0.03) + R(6)) + 0.6 * Math.sin(cyc(t, 5, x * 0.07));
    const tone = front ? 1 + Math.floor(R(7) * 3) : 1 + Math.floor(R(7) * 2);
    let tipLight = 0;
    for (const [fx, fy, g] of lit) {
      const d = Math.hypot(fx - (x + sway), fy - (base - h));
      if (d < 28) tipLight = Math.max(tipLight, g * (1 - d / 28));
    }
    for (let r = 0; r < h; r++) {
      const u = r / h, c = u > 0.8 && tipLight > 0.2 ? (tipLight > 0.55 && u > 0.9 ? C[3] : C[2]) : u > 0.7 ? G[Math.min(5, tone + 1)] : G[tone];
      q.px(x + sway * u * u, base - r, c);
    }
    if (R(8) < 0.07) {
      const sx = x + sway, sy = base - h;
      q.px(sx, sy - 1, tipLight > 0.2 ? C[3] : G[5]);
      q.px(sx - 1, sy, G[4]);
      q.px(sx + 1, sy, G[4]);
    }
  }
}

// The banded fog (a baked tiling noise, warped, cut into a few translucent tones with Bayer edges, a lit crest
// wherever a band's top meets thinner fog) is adapted from Sprite Fusion's open-source fog
// (https://www.spritefusion.com/pixel-art-vfx/fog), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, smooth, mix, TAU, WHITE } from "../../core/index.js";
import { rows, field, sample, bayer } from "./_lib.js";

export const meta = {
  name: "Fog",
  desc: "Slow banks of moonlit fog at three depths drift past each other, crests catching the light, while thin streaks of mist slide by in front.",
  tags: ["weather", "fog", "mist", "haze", "night", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 170],
  duration: 12,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#14121e", "#24213a", "#363250", "#4f4a6c", "#6d688b", "#918cab", "#bdb8d4", "#ece8f6"],
    seed: 5,
  },
};

const D = 12, W = 320;
const T = [0.3, 0.5, 0.7], BW = 0.06;
// far to near: where each bank's top thins out (top..base), how far down it reaches, noise scale (the tile it
// scrolls each loop is 256 / sx px wide), tiles a loop, how opaque, tones [thin, body, dense], crest tone
const BANKS = [
  { top: -84, base: -40, bot: -20, sx: 1.6, sy: 2.2, lap: 1, alpha: 0.24, tone: [2, 3, 4], crest: 5, warp: 16, crestFrom: 3 },
  { top: -62, base: -24, bot: -2, sx: 1.0667, sy: 2.5, lap: 1, alpha: 0.3, tone: [2, 3, 4], crest: 5, warp: 22, crestFrom: 2 },
  { top: -42, base: -8, bot: 10, sx: 0.8, sy: 2.8, lap: 1, alpha: 0.36, tone: [2, 3, 5], crest: 6, warp: 28, crestFrom: 1 },
];
const BR = new Float32Array(W);
const P1 = BANKS.map(() => new Float32Array(W)), P2 = BANKS.map(() => new Float32Array(W)), WARP = new Float32Array(W);

export function drawBack(p, t, o) {
  const S = o.seed, C = fit(o.palette, 8);
  bank(p, t, S, C, 0);
  bank(p, t, S, C, 1);
}

export function draw(p, t, o) {
  const S = o.seed, C = fit(o.palette, 8);
  bank(p, t, S, C, 2);
  streaks(p, t, S, C, 1);
}

function bank(p, t, S, C, n) {
  const B = BANKS[n], F = field(S * 7 + n, 256, 128), G = field(S * 7 + 11, 256, 128, [4, 8, 16]);
  const drift = (256 * B.lap * t) / D, boil = (128 * t) / D, prev1 = P1[n], prev2 = P2[n];
  const tones = B.tone.map((i) => C[i]), crest = mix(C[B.crest], WHITE, 0.12 + 0.08 * n);
  prev1.fill(0);
  prev2.fill(0);
  // the fog breathes: its top rises and falls a little along its length
  for (let i = 0; i < W; i++) BR[i] = 2 * Math.sin((TAU * t) / D + (i - 160) * 0.006 + n * 1.7);
  rows(p, meta, B.top - 2, B.bot, (y, R) => {
    const prof = smooth(B.top, B.base, y) * (1 - smooth(B.bot - (B.bot < 10 ? 14 : 4), B.bot + 1, y));
    for (let i = 0; i < W; i += 2) WARP[i] = WARP[i + 1] = sample(G, i * 0.35 + n * 70, y * 0.5 + boil) - 0.5;
    for (let i = 0; i < W; i++) {
      const x = i - 160 + 0.5, w = WARP[i];
      // the noise is pushed hard and clamped so it, not the height, shapes the fog: blobs, not stripes
      const nn = clamp((sample(F, x * B.sx + drift + w * B.warp, (y + BR[i]) * B.sy + w * 8) - 0.5) * 2.6 + 0.5) - 0.5;
      const f = prof <= 0.01 ? 0 : (prof * 0.72 + nn * 0.95) * (0.6 + 0.5 * prof);
      const above = prev2[i];
      prev2[i] = prev1[i];
      prev1[i] = f;
      if (f <= T[0]) continue;
      const th = bayer(i, y) * BW, band = f > T[2] + th ? 2 : f > T[1] + th ? 1 : 0, solid = f > T[2] ? 2 : f > T[1] ? 1 : 0;
      // a lit crest, one pixel thick, where this band's top meets thinner fog
      if (solid >= B.crestFrom && above < T[solid]) {
        R.c[i] = crest;
        R.a[i] = B.alpha * 0.95;
        R.l[i] = C[6];
        R.k[i] = 0.07;
      } else {
        // dense fog scatters the most moonlight: it's the brightest part, with a little glow
        R.c[i] = tones[band];
        R.a[i] = B.alpha * (0.55 + 0.25 * band);
        if (band === 2) (R.l[i] = C[5]), (R.k[i] = 0.03 + 0.02 * n);
      }
      R.b[i] = 1;
    }
  });
}

// thin streaks of mist sliding by faster than the banks, a few behind the near bank and a few in front
function streaks(p, t, S, C, front) {
  // one tile a loop: the back streaks slide at 43 px/s, the front ones at 53
  const F = field(S * 7 + 20 + front, 256, 128), drift = (256 * t) / D, sx = front ? 0.4 : 0.5, y0 = front ? -40 : -96, y1 = front ? 6 : -30;
  rows(p, meta, y0, y1, (y, R) => {
    const env = smooth(y0, y0 + 10, y) * (1 - smooth(y1 - 10, y1, y));
    for (let i = 0; i < W; i++) {
      const x = i - 160 + 0.5, s = (sample(F, x * sx + drift, y * 6.5 + 30) - 0.64) * 3 * env;
      if (s <= 0.05) continue;
      R.c[i] = s > 0.35 ? C[5] : C[4];
      R.a[i] = Math.min(0.4, s);
      R.b[i] = 1;
      R.l[i] = C[5];
      R.k[i] = s * 0.05;
    }
  });
}

// The banded light (posterized steps from a hot core to the edges, fine strands through it, light laid over the top)
// is adapted from Sprite Fusion's open-source holy light (https://www.spritefusion.com/pixel-art-vfx/holy-light),
// MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, rand, mix, TAU, WHITE } from "../../core/index.js";
import { clip, rows } from "./_lib.js";

export const meta = {
  name: "God rays",
  desc: "Shafts of light slant down from high on the left, breathing and swaying, pooling on the floor, as drifting dust motes light up whenever they cross a beam.",
  tags: ["weather", "god rays", "light", "sunbeam", "dust", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 170],
  duration: 10,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#1a1208", "#3a2810", "#7a5a24", "#c89a44", "#f2d27a", "#fff2c4", "#ffffff"],
    seed: 3,
  },
};

const D = 10, W = 320, SX = -230, SY = -300;
// the fan's axis (down and to the right) and its normal; a pixel's place across the fan is its angle from it
const AX = Math.cos(0.94), AY = Math.sin(0.94), NX = -AY, NY = AX;
// the shafts: angle off the axis, half width (radians), strength, breathing (cycles a loop), sway
const SHAFTS = [
  { c: -0.27, h: 0.03, k: 0.65, b: 1, sw: 0.006 },
  { c: -0.17, h: 0.022, k: 0.55, b: 2, sw: 0.005 },
  { c: -0.07, h: 0.05, k: 1, b: 1, sw: 0.008 },
  { c: 0.03, h: 0.018, k: 0.6, b: 3, sw: 0.004 },
  { c: 0.12, h: 0.042, k: 0.85, b: 2, sw: 0.007 },
  { c: 0.23, h: 0.026, k: 0.6, b: 1, sw: 0.005 },
];
const STR = new Float32Array(512);

// light at a point: the shafts it's in, softened at their edges, fading with distance, threaded with strands
function lightAt(x, y, sh) {
  const dx = x - SX, dy = y - SY, r = dx * AX + dy * AY, ang = (dx * NX + dy * NY) / r;
  let e = 0;
  for (const s of sh) {
    const q = Math.abs(ang - s.c) / s.h;
    if (q < 1) e += s.k * (1 - q * q) ** 1.5;
  }
  if (e <= 0) return 0;
  const strand = STR[clamp(Math.floor((ang + 0.36) * 700), 0, 511)], fall = clamp(1.25 - (r - 230) / 420);
  return e * fall * (0.7 + 0.45 * strand);
}

export function drawBack(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 7);
  const sh = shafts(t, S);
  // dark air the light falls through, a dark floor it lands on; each beam posterized into a white-hot core, a
  // gold body and a soft translucent edge, brightest near the sun and fading as it falls
  const L = C.map((c) => mix(C[0], c, 0.75));
  const n = sh.length, SC = new Float32Array(n), SI = new Float32Array(n), SK = new Float32Array(n);
  sh.forEach((s, j) => ((SC[j] = s.c), (SI[j] = 1 / s.h), (SK[j] = s.k)));
  rows(p, meta, -170, 9, (y, R) => {
    const floor = y > 0, dy = y - SY, air = floor ? 0.8 : 0.66, boost = floor ? 1.6 : 1;
    let r = (-160 + 0.5 - SX) * AX + dy * AY, nn = (-160 + 0.5 - SX) * NX + dy * NY;
    R.a.fill(air);
    R.b.fill(1);
    R.c.fill(C[0]);
    for (let i = 0; i < W; i++, r += AX, nn += NX) {
      const ang = nn / r;
      let e = 0;
      for (let j = 0; j < n; j++) {
        const q2 = (ang - SC[j]) * SI[j];
        if (q2 > -1 && q2 < 1) {
          const w = 1 - q2 * q2;
          e += SK[j] * w * Math.sqrt(w);
        }
      }
      if (e <= 0) continue;
      const fall = 1.35 - (r - 200) / 330, si = ((ang + 0.36) * 700) | 0;
      e *= (fall > 1 ? 1 : fall < 0 ? 0 : fall) * (0.7 + 0.45 * STR[si < 0 ? 0 : si > 511 ? 511 : si]) * boost;
      if (e < 0.06) continue;
      const lv = e > 1.05 ? 6 : e > 0.78 ? 5 : e > 0.52 ? 4 : e > 0.3 ? 3 : 2;
      R.c[i] = floor ? C[lv] : L[lv];
      R.a[i] = floor ? 0.85 : Math.min(0.78, 0.12 + e * 0.5);
      R.l[i] = C[4];
      R.k[i] = e * (floor ? 0.32 : 0.26);
    }
  });
  // the sun's glare where the beams come in
  q.glow(-168, -178, 130, C[3], 0.3);
  q.glow(-168, -178, 50, C[5], 0.35);
  motes(q, t, S, C, sh, false);
}

export function draw(p, t, o) {
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 7);
  motes(q, t, S, C, shafts(t, S), true);
}

// each shaft breathes and sways on whole cycles; the strands drift slowly across the beams
function shafts(t, S) {
  for (let i = 0; i < 512; i++) {
    const a = i / 512;
    STR[i] = 0.5 + 0.5 * Math.sin(a * 190 + Math.sin((TAU * t) / D) * 2 + S) * Math.sin(a * 77 - (TAU * t) / D + S * 2);
  }
  return SHAFTS.map((s, i) => ({ c: s.c + s.sw * Math.sin((TAU * t) / D + i * 1.3), h: s.h * (1 + 0.15 * Math.sin((TAU * s.b * t) / D + i)), k: s.k * (0.72 + 0.28 * Math.sin((TAU * s.b * t) / D + i * 2.1)) }));
}

// dust motes drifting slowly, invisible in the dark, catching the light as they cross a beam
function motes(q, t, S, C, sh, front) {
  for (let i = front ? 0 : 50; i < (front ? 50 : 160); i++) {
    const R = (k) => rand(S, i, k), n1 = 1 + Math.floor(R(1) * 2), n2 = 1 + Math.floor(R(2) * 2);
    const x = -170 + R(3) * 340 + (8 + R(4) * 14) * Math.sin((TAU * n1 * t) / D + R(5) * TAU), y = -170 + R(6) * 172 + (6 + R(7) * 10) * Math.sin((TAU * n2 * t) / D + R(8) * TAU) + 4 * Math.sin((TAU * 3 * t) / D + i);
    const e = lightAt(x, y, sh);
    if (e < 0.12) continue;
    const big = front && R(9) < 0.5, k = Math.min(1, e);
    q.px(x, y, k > 0.6 ? WHITE : k > 0.3 ? C[5] : C[4]);
    if (big && k > 0.5) (q.px(x + 1, y, C[4]), q.px(x, y + 1, C[4]));
    q.glow(x, y, big ? 6 : 4, C[4], 0.4 * k);
  }
}

// The rain recipe (depth layers of two-tone streaks, far drops that end in the air, near ones that splash and
// throw droplets, mist low on the ground) is adapted from Sprite Fusion's open-source rain
// (https://www.spritefusion.com/pixel-art-vfx/rain), MIT License, Copyright (c) 2026 Hugo Duprez.
import { fit, clamp, smooth, rand, wrap, mix, WHITE } from "../../core/index.js";
import { clip, pass, field, sample, trips, crown, bayer } from "./_lib.js";

export const meta = {
  name: "Rain",
  desc: "Slanted rain at four depths: far drops fade into the dark, near ones glint and splash, drops ring the puddles and a low mist drifts over the wet floor.",
  tags: ["weather", "rain", "storm", "water", "ambient", "loop"],
  size: [320, 180],
  origin: [160, 170],
  duration: 8,
  loop: true,
  fps: 30,
  bg: "sky",
  options: {
    palette: ["#0e1322", "#1a2440", "#283a5e", "#3a5482", "#5674a8", "#84a6d6", "#c0dcf8", "#f2f8ff"],
    density: 1,
    seed: 4,
  },
};

const D = 8, SLANT = -0.2, UX = SLANT / Math.hypot(SLANT, 1), UY = 1 / Math.hypot(SLANT, 1);
// the depths, far to near: how many, falls a loop (speed), streak length, colors (tail, body, head), where
// they end (in the air, or on the floor at depth z), how big their splash
const LAYERS = [
  { n: 200, m: [10, 13], len: 2, col: [2, 2, 3], stop: [-80, -6] },
  { n: 150, m: [14, 17], len: 4, col: [2, 3, 4], stop: [-45, -2] },
  { n: 96, m: [19, 23], len: 7, col: [3, 4, 5], z: [0, 1.4], size: [0.15, 0.4] },
  { n: 42, m: [25, 29], len: 13, col: [3, 5, 7], z: [2, 6.5], size: [0.6, 1], near: true },
];

// puddles on the wet floor: long thin strips that hold the sky, at depth y, from x0 to x1
function pools(S) {
  return Array.from({ length: 5 }, (_, i) => {
    const x = -150 + i * 66 + rand(S, i, 61) * 30, w = 16 + rand(S, i, 63) * 26;
    return { x0: x, x1: x + w, y: 3 + Math.floor(rand(S, i, 62) * 3) };
  });
}
const poolAt = (P, x, y) => P.find((p) => x >= p.x0 + 2 && x <= p.x1 - 2 && Math.abs(y - p.y) < 1.5);

export function drawBack(p, t, o) {
  t = Math.round(t * 3e4) / 3e4;
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 8), P = pools(S);
  // an overcast haze, thicker toward the ground, that hides the stars
  const haze = mix(C[0], C[1], 0.6);
  pass(p, meta, -170, -0.5, (x, y, out) => {
    out.c = haze;
    out.a = 0.3 + 0.26 * smooth(-170, 0, y);
    out.b = 1;
  });
  floor(q, t, S, C, P);
  for (let L = 0; L < 3; L++) layer(q, t, S, C, P, L, o.density);
  mist(p, t, S, C);
}

export function draw(p, t, o) {
  t = Math.round(t * 3e4) / 3e4;
  const q = clip(p, meta), S = o.seed, C = fit(o.palette, 8), P = pools(S);
  layer(q, t, S, C, P, 3, o.density);
}

// one depth of rain: each slot falls a whole number of times a loop, somewhere new each time
function layer(q, t, S, C, P, L, density) {
  const Ly = LAYERS[L], sd = S * 11 + L, [c0, c1, c2] = Ly.col.map((i) => C[i]), len = Ly.len;
  const n = Math.round(Ly.n * density), G = field(S + 21, 256, 128, [4, 8, 16]), sweep = (256 * t) / D;
  trips(t, D, n, sd, Ly.m[0], Ly.m[1], (u, k, m, i) => {
    const j = wrap(k, m);
    // gusts: sheets of heavier and lighter rain sweep across with the wind
    if (L < 2 && rand(sd, i, j, 7) > 0.35 + 1.3 * (sample(G, (-166 + rand(sd, i, j, 2) * 332) * 0.8 + sweep, 9 + L * 40) - 0.32)) return;
    const end = Ly.z ? Ly.z[0] + rand(sd, i, j, 1) * (Ly.z[1] - Ly.z[0]) : Ly.stop[0] + rand(sd, i, j, 1) * (Ly.stop[1] - Ly.stop[0]);
    const y0 = -172 - len, y = y0 + (end - y0) * u, x = -166 + rand(sd, i, j, 2) * 332 - (end - y) * SLANT;
    // far drops thin out before they end; near ones are whole
    const a = Ly.z ? 1 : Math.min(1, (1 - u) * 5);
    if (len <= 2) q.dot(x, y, c2, a), q.dot(x - UX, y - UY, c1, a * 0.8);
    else {
      q.line(x - UX * len, y - UY * len, x - UX * len * 0.45, y - UY * len * 0.45, c0, (v) => a * (0.35 + 0.65 * v));
      q.line(x - UX * len * 0.45, y - UY * len * 0.45, x - UX, y - UY, c1, a);
      q.dot(x, y, c2, a);
    }
    // near drops catch the light
    if (Ly.near) q.glow(x, y - 2, 4, C[5], 0.12);
    if (!Ly.z) return;
    // the drops before this one landed: a crown on the ground, or rings sliding apart along a puddle
    const dur = D / m;
    for (let back = 1; back < 4; back++) {
      const age = u * dur + (back - 1) * dur;
      if (age > 0.7) break;
      const jp = wrap(k - back, m), z = Ly.z[0] + rand(sd, i, jp, 1) * (Ly.z[1] - Ly.z[0]), xp = -166 + rand(sd, i, jp, 2) * 332;
      if (rand(sd, i, jp, 5) > (Ly.near ? 1 : 0.7)) continue;
      const size = Ly.size[0] + ((z - Ly.z[0]) / (Ly.z[1] - Ly.z[0])) * (Ly.size[1] - Ly.size[0]), pool = Ly.near && poolAt(P, xp, z);
      if (pool) rings(q, xp, pool, age, C);
      else if (crown(q, xp, z, age, size, { hot: C[6], cool: C[4], white: WHITE }, rand(sd, i, jp, 4)) && Ly.near && age < 0.1) q.glow(xp, z - 1, 5, C[5], 0.3 * (1 - age / 0.1));
    }
  });
}

// a drop in a puddle: a bright point, then rings seen edge-on, so two short dashes sliding apart, twice
function rings(q, x, pool, age, C) {
  const X = Math.round(x), y = pool.y;
  if (age < 0.05) q.px(X, y, C[7]);
  for (let r = 0; r < 2; r++) {
    const a = age - r * 0.16, u = a / 0.5;
    if (u <= 0 || u >= 1) continue;
    const w = Math.round(1 + 7 * Math.sqrt(u)), c = u < 0.4 && !r ? C[6] : C[5];
    for (const s of [-1, 1])
      for (let d = 0; d < (u < 0.6 ? 2 : 1); d++) {
        const px = X + s * (w - d);
        if (px > pool.x0 && px < pool.x1) q.px(px, y, c);
      }
  }
}

// the wet floor: a clean wet edge (a lit lip over a dark line), a dark sheen, puddle strips holding the sky
function floor(q, t, S, C, P) {
  pass(q, meta, 0, 9.5, (x, y, out) => {
    if (y < 1) return void ((out.c = C[4]), (out.l = C[5]), (out.k = 0.08));
    if (y < 2) return void (out.c = C[1]);
    out.c = C[0];
    out.a = 0.55;
    out.b = 1;
    for (const p of P)
      if (x >= p.x0 && x < p.x1 && Math.floor(y) === p.y) {
