const D = 10;
// the meteors: when, where they start, which way, how fast, how long they burn, how big; the last flares
const METEORS = [
  { t0: 0.5, x: 60, y: -170, a: 2.45, v: 260, life: 0.55, s: 0.6 },
  { t0: 1.9, x: -40, y: -176, a: 2.2, v: 220, life: 0.7, s: 0.8 },
