const D = 12;
// the drift's top edge, and the gusts: a sway of the whole snowfall, periodic so the loop closes
const bank = (x) => -3 + 1.6 * Math.sin(x * 0.045 + 1.3) + 1.1 * Math.sin(x * 0.12 + 0.4) + 0.6 * Math.sin(x * 0.31 + 2);
